午前９時30分 開会
○議長（光益良洋）
おはようございます。定刻になりましたので、ただいまから令和８年第１回広川町議会定
例会を開会いたします。
なお、丸山幸弘議員については、欠席の届けが出ております。
本定例会に提出されております議案は、条例の一部改正12件、条例の制定１件、指定管理
者の指定１件、福岡県市町村職員退職手当組合規約の変更１件、令和７年度補正予算５件、
令和８年度当初予算６件の計26件となっております。
これらの議案については後ほど提案者から説明がありますが、議員の皆様方におかれまし
ては、円滑に議事が進められ、適正妥当な議決に達せられますよう念願申し上げ、開会の挨
拶といたします。
次に、町長より今議会招集の挨拶及び施政方針をお願いいたします。町長。
○町長（氷室健太郎）
皆さんおはようございます。本日ここに令和８年第１回広川町議会定例会を招集いたしま
したところ、議員の皆様におかれましては、公私ともに御多用中にもかかわらず御出席を賜
り、誠にありがとうございます。また、傍聴席の皆様、インターネット中継を御覧の皆様も
日程第１ 会議録署名議員の指名
日程第２ 会期の決定
日程第３ 一般質問

心から感謝申し上げます。ありがとうございます。
昨年は本町の町制施行70周年を迎え、11月１日には記念式典を盛大に挙行することができ
ました。そこでも申し上げましたが、先人のこれまでの数々の御英断や、今日まで田畑を守
り、伝統文化を守り、町発展の礎を築き上げてこられた全ての皆様の深い郷土愛の上に現在
の豊かな暮らしがあることを私たちは忘れてはなりません。私たちが受け取ったこの偉大な
バトンを次の世代へとつないでいく、未来への責任を果たすことこそ、今を生きる私たちに
課せられた最大の使命であると深く心に刻んでおります。
そのような揺るぎない覚悟で臨む本定例会において、新年度の当初予算をはじめとする重
要案件の御審議をお願いするに当たり、町政に臨む私の基本方針を申し上げます。
「町長は、住民の皆様の声を政策へと変換する「翻訳者」たるべき」、私は町長就任以来、
この考えを胸に刻んでまいりました。就任した令和５年度は、記録的な大雨災害に見舞われ
たことで皆様の生命と財産を守るための復旧・復興を最優先としましたが、その後、平穏を
取り戻しつつある中で、私が何よりも重視したのは対話であります。
令和６年度からは、年間数か所の公民館を巡回する、住みよいまちづくり懇談会に参加し、
商工会女性部やシニアクラブの皆様との意見交換も実施いたしました。
さらには、小・中学校、幼稚園、保育園での「町長と給食を食べよう」や、夏休み期間中
の高校生たちとの「町長と話そう」といった場を通じて、世代を問わず、様々な生の声に耳
を傾けてまいりました。
これだけ予測困難な時代にあっては、絶対的な１つの正解は存在しません。だからこそ、
切実なお困り事から地域をよくしたいという熱い情熱まで、対話を通じて皆様と分かち合っ
た思いこそがこれからの広川町をつくる羅針盤であり、最大の原動力となります。
令和８年度におきましても、この対話を重視する姿勢を貫き、皆様と共に考え、共につく
り上げるまちづくりを力強く推し進めてまいります。
私たちが進むべき道しるべである広川町第５次総合計画も着実に進めてまいります。目指
す将来像として掲げる「世代を超えて住み心地の良い、温もりと笑顔あふれるまち」の実現
に向け、「職・住・育プラス遊～未来に希望が広がるまちづくり～」という基本理念の下、
人々の幸福感（ウェルビーイング）を重視して、どの世代も暮らしやすく、未来に希望が持
てる地域社会の実現に努めてまいります。
令和８年度は、この総合計画の前期基本計画が折り返しを迎える節目でもあり、現執行体
制として、実質的に本格的な政策を反映し得る最終実行年度でもあります。
令和８年度予算編成に当たり、私は全職員に対して、現状維持は後退であると伝えました。
時代が目まぐるしく変化しているにもかかわらず、私たちが従前どおりの事業を漫然と続け
ていては、いずれ住民の皆様が求める本当のニーズとの間にずれが生じます。それは行政
サービスの相対的な価値を下げ、結果として、住民生活の質の向上につながることはありま
せん。この強い危機感を全職員と共有し、慣行にとらわれないゼロベース思考による選択と
集中、戦略的な資源配分と構造的な行財政改革を基本方針として、以下の３つの柱を軸に令
和８年度の施策を展開していきます。
第１の柱は、未来への投資を可能にするための強靭な行政経営基盤の確立と歳入強化です。
まず、行政運営の方針として、将来的な窓口開庁時間の短縮も見据え、令和８年度はその
基盤となる「書かない窓口」、あるいは「待たない窓口」、そして、デジタル化によって手

続をオンライン化する「行かない窓口」の実装を進めます。加えて、ＡＩの積極的な活用で
さらなる業務効率化を図り、そこで創出された職員の労力と時間を町民の皆様との対話や政
策立案、知識や能力を向上させる研修といった付加価値の高い業務へと注ぎ込めるようにし
ます。いわゆる行政のＤＸ化に取り組むわけですが、ＤＸ化は単なる業務の効率化のためで
はなく、住民サービスの向上につなげることが最大の目的です。あわせて、あらゆる分野に
おいて、民間活力の積極的な導入も検討しなければなりません。
次年度は、新たに地域活性化起業人制度の活用を始め、民間企業で活躍する人材を役場で
受け入れることにしています。民間企業から派遣される人材と町職員とが一緒になって事務
作業の効率化やデジタルツールの導入などに取り組むことで、民間のノウハウ活用と人材育
成を同時に進めてまいります。
歳入面におきましては、まずは国や県の各種交付金、補助金の確保に努めます。先月20日
には、高市総理がその施政方針演説において、どこに住んでいても安全に生活することがで
き、必要な医療、福祉や質の高い教育を受けることができ、働く場所があることが目指す日
本の姿であり、そのために何より重要なことは強い地域経済の構築であり、地域未来戦略を
推進し、魅力ある地域資源を生かした地場産業の成長を支援すると述べられました。この国
の姿勢を追い風に、責任ある積極財政の理念の下、創設される地域未来交付金などに採択さ
れるよう、本町の特性を生かした先駆的な事業を積極的に企画、実施し、国の財政支援を最
大限に活用してまいります。
また、これまで同様に、ふるさと納税による寄附額の増加に努めるとともに、基金運用の
強化、町税の的確な徴収など自主財源の確保を徹底してまいります。
第２の柱は、町の持続可能性を担保するための投資である、こどもまんなか社会の実現で
す。
総合計画で「育」として位置づけられるこの取組は、決して特定の子育て世代だけのもの
ではありません。この町に暮らす全ての皆様に関わる、広川町が未来永劫にわたって活力を
維持していくための最重要課題でございます。
高市総理は、足元で進む少子化、人口減少を我が国の活力をむしばんでいく静かな有事で
あると表現されました。私も全く同感であります。今、目の前にいる子供たちは未来の社会
の担い手であります。時間は刻一刻と進み、人は誰でも年を取ります。私も町民の皆さんも
いつかは必ず衰え、誰かの助けを必要とする時が必ず来ます。10年後、20年後、社会の支え
手となっているのは、今、目の前にいる子供たちなのです。もし彼らがいなくなり、支え手
がいなくて行き場を失う人が増える地域になったらどうなるか、想像するだけでぞっとしま
す。だからこそ、今から未来の担い手の育成に本気で取り組まなければなりません。
令和８年度は、小学校給食費の無償化や教育支援センター「ふんわり」の運営開始、体育
館や武道場への空調設備の設置など、教育環境の向上を図ります。また、上広川小学校の移
転や下広川小学校グラウンド整備の基本設計策定に向けた取組も着実に進めてまいります。
小規模な町だからこそできる強みを生かし、子ども課、福祉課、生涯学習課が緊密に連携す
ることで、妊娠期から学齢期に至るまで切れ目のない支援体制を強化いたします。
さらに、本年秋には供用を開始する竜光寺公園をはじめ子供の居場所づくりを重視し、地
域の公民館や地元企業が持つ資源も活用させていただきながら、地域全体で子供たちを育む
環境を整えてまいります。

この広川町で地域の皆様の愛情を受けて育った子供たちが、将来またこの地で働き、家庭
を築き、次の世代を育んでいく、そんな広川サイクルの好循環を町を挙げて力強く回してま
いりたいと願っております。
第３の柱は、住民の皆様の安心・安全な生活を確保する安全・共生社会の構築でございま
す。
令和５年７月の大雨災害の教訓を胸に、治水対策を最優先課題の一つとして、県による広
川浸水対策重点地域緊急事業の着実な進捗を支援するとともに、まだぬぐい切れない不安を
持つ地元の皆さんからの要望にも真摯に耳を傾け、さらなる治水対策の実現を目指します。
また、防災機能としても重要な国道３号広川八女バイパスや県道三潴上陽線バイパスの整備
についても強力に支援いたします。
地域コミュニティの基盤強化に向けては、自主防災組織の役割を重視し、次の災害に備え
た施設整備等を支援いたします。あわせて、自治会の持続性を高めるため、新たな地域コ
ミュニティ活動支援事業の制度構築にも努めてまいります。
町民の皆様の健康づくりも重要な課題です。
昨年の70周年記念式典では、100歳をお迎えになり、今なお現役で御活躍される梅本コフ
ミ様にすばらしい日本舞踊を御披露いただきました。年齢を重ねられてもなお尊敬を集め、
御活躍される先輩方がおられることは本町の誇りでもあります。その背中を追いかけるよう
に、各種健診の受診率向上を通じた健康寿命の延伸を図り、誰もが住み慣れた地域で心穏や
かに暮らせるよう、ｅスポーツをはじめとした高齢者の生きがいづくりも推進してまいりま
す。
第５次総合計画の理念にある「職・住・育プラス遊」の「遊」とは、単なる余暇を意味す
るものではありません。それは、まちづくりが本来持っている楽しさや喜び、創造性であり、
未来への希望をもたらす、わくわく感を意味します。職員に対しても、まちづくりとは本来
楽しいものだ、自分たちの仕事で地域が変わる、未来が変わる、そのことを想像しながら、
少しずつ実感しながらまちづくりを進めていこうと呼びかけました。住民の皆様にとっても
同じです。竜光寺公園のリニューアルや道路や河川整備など、目に見えてこの町が変わって
いくさまを見てわくわくしていただき、この町の未来は変わっていくかもしれないという期
待感からもわくわくしてもらいたい、そのためにも、対話を通じてインプットされた情報を
政策に変換し、多くの皆さんがまちづくりに参画していることを実感していただきたいと考
えております。
令和８年度予算は、私たちが広川町の未来に対して果たすべき責任の証でもあります。温
もりと笑顔あふれる町を次の世代へと手渡すため、私自身が先頭に立ち、全職員が一丸と
なって知恵を絞り、挑戦を重ねてまいる所存です。
議員の皆様、そして町民の皆様にお力添えいただきながら、町民に寄り添う持続可能なま
ちづくりを共に進めていけるよう、御理解と御協力を賜りますよう心からお願い申し上げま
す。
本定例会には、令和８年度一般会計予算をはじめとする諸議案を御提案申し上げておりま
す。提案理由につきましては後ほど詳しく御説明申し上げますが、慎重なる御審議の上、全
議案とも御決定いただきますようお願い申し上げ、私の施政方針とさせていただきます。ど
うぞよろしくお願いいたします。

○議長（光益良洋）
これから本日の会議を開きます。
本日の日程は、お手元に配付いたしております議事日程第１号のとおりであります。
直ちに議事日程に入ります。
日程第１ 会議録署名議員の指名
○議長（光益良洋）
日程第１．会議録署名議員の指名を行います。
本定例会の会議録の署名議員は、６番山下茂議員と11番池尻浩一議員を指名いたします。
日程第２ 会期の決定
○議長（光益良洋）
日程第２．会期の決定を議題といたします。
会期については、去る２月24日、議会運営委員会に諮ったところ、３月４日から３月19日
までの16日間にしたいという案が出ていますが、よろしいかお諮りします。
〔「異議なし」と呼ぶ者あり〕
○議長（光益良洋）
異議なしと認めます。よって、本定例会の会期は３月４日から３月19日までの16日間と決
定いたしました。
日程第３ 一般質問
○議長（光益良洋）
日程第３．一般質問を行います。
発言時間は、質問、答弁を含めて１時間以内とします。制限時間５分前にベルで合図しま
す。
３番藤島玄稔議員の登壇を求めます。
○３番（藤島玄稔）
３番藤島玄稔です。１番の発言機会をいただきまして、ありがとうございます。大変緊張
しておりますけれども、どうぞよろしくお願いいたします。
まず１番、広川町第５次総合計画について。概略として、進捗状況と展望をお尋ねします。
２番、個別の事業についてお尋ねします。１つ、令和５年７月の水害対策事業について、
進捗と展望をお尋ねします。①広川町の水害復興事業、②広川の浸水対策重点地域緊急事業。
２つ、こどもまんなか政策・事業について、進捗と展望をお尋ねします。
３番、日本国憲法について。１つ、学校教育ではどのように取り組まれているか、お尋ね
します。①平和教育について。２つ、町ではどのように取り組まれているか、お尋ねします。
①主権者教育への取組の姿勢について。
よろしくお願いいたします。
○議長（光益良洋）
町長。
○町長（氷室健太郎）

藤島議員の御質問にお答えをいたします。
まず、広川町第５次総合計画について。
広川町第５次総合計画は、令和６年度から令和13年度までの８年間を計画期間とする本町
のまちづくりの最上位計画です。「世代を超えて住み心地の良い、温もりと笑顔あふれるま
ち」を８年後の将来像に掲げ、「食・住・育プラス遊～未来に希望が広がるまちづくり」を
基本理念とし、これからも暮らし続けたい、訪れてみたい、魅力あふれるまちを目指してい
ます。
令和７年度は４年の前期基本計画期間の２年目に当たります。まずは、これまでの進捗状
況について御報告をいたします。
重点プロジェクトの一つである「地域防災 地域と備える安全安心プロジェクト」に関し
ましては、令和５年７月の記録的な大雨被害を受け、道路や河川等のインフラの復興を最優
先課題として全力で取り組んでおります。次の災害に備えるべく、国や県とも連携した河川
改修や道路整備などの基盤整備にも努めております。また、重点プロジェクトの一つである
「ともに育む出会い・子育て応援プロジェクト」につきましては、令和６年度からこどもま
んなかプロジェクトをスタートさせ、こどもまんなかアクションプランに基づく施策を進め
ております。当初の４年間で子供が大切にされていると実感できるまちを目指し、未来の地
域社会の担い手を育成すべく、地域や企業、関係団体等と連携しながら、各種事業を強力に
推進しているところです。
これらを含め、毎年実施している施策評価の結果としましては「順調に進んでいる」が約
４％、「おおむね順調に進んでいる」が約74％、「あまり進んでいない」が約22％という結
果になりました。全体の８割近くが着実に進捗しておりますが、遅れが見られる事業もあり
ますので、今後の展望としましては、３年目となる令和８年度につきましても、しっかりと
課題を検証した上で解決策を模索し、適切に対処してまいりたいと考えております。
次に、個別の事業について。
まずは、災害復旧事業についてお答えいたします。
令和５年７月に発生した九州北部豪雨で被災し、災害査定を受けた町の施設は、町道16か
所、河川６か所、橋梁３か所、林道３か所、農道１か所、水路１か所の計30か所で、９月議
会で御質問いただいた際には、令和７年９月末までに27か所について工事が完了していると
回答をさせていただきました。令和７年12月には、長延逆瀬谷線道路災害復旧工事も完成し、
現在までに28か所の工事が完了しております。残る２か所の松川原橋橋梁災害復旧工事と高
山橋橋梁災害復旧工事については、12月議会で事故繰越しの御承認をいただいたとおり、令
和８年度の出水期前までの６月に完了する見込みでございます。
次に、福岡県が事業主体となり、令和６年度から実施いただいている県営河川広川の浸水
対策重点地域緊急事業につきましては、１月末時点で６井堰の撤去工事と２か所の護岸工事
に着手するとともに、統廃合する井堰や護岸の詳細設計業務等、41本の業務を実施いただい
ております。また、12月末から堰改修等の地元説明会を各井堰ごとに開催し、事業計画につ
いて、おおむね地元関係者の同意をいただいていると聞いております。
今後の展望につきましても、令和８年度から用地買収に着手し、事業の実施が可能になっ
た箇所から工事に着手する計画とお聞きしております。
町としても、事業計画期間である５か年での完成を目指し、地元との調整役など、県と協

力しながら引き続き取り組んでまいります。
次に、広川町が取り組む、こどもまんなか政策についてお答えをいたします。
「こどもまんなかプロジェクト」は、広川町第５次総合計画の重点プロジェクトの一つで
あり、地方創生の一翼を担うものです。令和６年12月に策定した、こどもまんなかアクショ
ンプランでは、令和６年度より８か年の計画期間のうち、前半４年間を第１ステージとして、
子供が大切にされていると実感できるまちを目指し、こどもの声に耳を傾ける、こどもの居
場所をつくる、こどもへの愛着形成を支援する、こどもの主体性を育むの４つの柱を立て、
各種事業に取り組んでおります。
その進捗状況につきましては、これまで子ども医療費の無償化の年齢引上げや、竜光寺公
園のリニューアルに着手するとともに、おむつの定期便などを行ってまいりました。また、
夏休みを利用して子供たちの声を直接聞く取組「町長と話そう」では、高校生の声に応えて
役場を勉強部屋として開放することをはじめ、小学生の声から藤田運動公園へサッカーゴー
ルを設置しました。今年度からは新たに小・中学校や保育園、幼稚園で「町長と給食を食べ
よう」と題した取組も始めており、子供たちが町長と接する機会を積極的に設け、まちづく
りへの関心を早くから持ってもらい、地域社会の未来の担い手として自覚するよう促してお
ります。
加えて、こどもまんなかの社会づくりに賛同する企業、店舗等と連携し、地域ぐるみで子
供や子育て世帯を応援する取組を昨年11月より実施して、現在48の企業や事業所、店舗等の
登録により、のぼり旗などを設置いただき、地域全体で子供、子育てを応援しようとする機
運の向上に努めております。
来年度からは、第１ステージの後半として、町民の利便性の向上や地域資源の利活用を目
的としたデジタルインフラの整備に取り組むなど、子供を起点とした取組をさらに進めてま
いります。
私からは以上となります。
○議長（光益良洋）
教育長。
○教育長（冨山拓二郎）
おはようございます。私からは、日本国憲法について、学校教育での平和教育の取組につ
いてお答えいたします。
広川町は昭和59年、1984年に「非核・恒久平和の町」を宣言し、世界の恒久平和と核兵器
の廃絶を希求しています。本町における学校教育は、この「非核・恒久平和の町」宣言の崇
高な理念を次世代を担う子供たちへと確実に引き継ぐ責務があると考えております。
教育基本法第１条は、教育の目的を「人格の完成を目指し、平和で民主的な国家及び社会
の形成者として必要な資質を備えた心身ともに健康な国民の育成」と定めており、また、小
学校、中学校における平和に関する教育については、学習指導要領に基づき、全教科、全領
域において、児童・生徒の発達段階に応じて行っています。
具体的には、例年、夏季休業中の８月６日前後の出校日には平和学習を行い、戦争や原子
爆弾の恐ろしさを理解させるとともに、生命の尊さや平和、人権を守ることの大切さについ
て考える学習を行っています。また、小学校の修学旅行においては、長崎県を訪れ、被爆体
験を語り部の方々から伺う機会を設け、直接的な学びを得る体験は教科書や文献だけでは得

られないリアルな感覚を育むことができ、戦争の惨禍を忘れないための重要な一歩となると
考えております。
今後の展望としては、子供たち自身が平和について考え、意見を発表する場を設けること
で、平和な世の中をつくっていく一人として自覚を高めることが重要です。子供たちが自ら
の言葉で平和について語れるような教育の確立を目指していく所存です。
このように、本町における平和教育は次世代を担う子供たちにとって必須の学びであり、
これからの社会をよりよいものにするための基盤を築くものであると考えております。
以上でございます。
○議長（光益良洋）
選挙管理委員会書記長。
○選挙管理委員会書記長（鹿田 健）
それでは、議員御質問のうち、主権者教育への取組姿勢についてお答えいたします。
日本国憲法の前文及び第１条に主権が国民にあると明記されておりますとおり、主権者教
育は未来を担う子供たちや地域の方々が政治に関心を持つための極めて重要な取組であると
認識しております。
現在、広川町では区長会、分館長会、シニアクラブの代表者、中央公民館長、そして選挙
管理委員会委員で構成される広川町明るい選挙推進協議会が中心となり、啓発活動を進めて
おります。また、藤島議員が学級長を務めておられます、ぎんなん学級におきましても、身
近な暮らしと政治について誰もが学べる貴重な場を提供していただいているところでござい
ます。こうした団体の皆様に御協力をいただきながら、福島高校や町内の小学校において出
前講座を実施するなど、学校現場での主権者教育にも力を入れているところでございます。
さらに、明るい選挙推進協議会やぎんなん学級生の皆様には、八女地区や南筑後地区での
研修会等にも積極的に参加していただいており、先進的な取組を学ばれるなど、資質の向上
にも努めていただいておるところでございます。
今後につきましても、これらの事業を柱として、主権者教育を積極的に展開してまいる所
存でございます。
以上でございます。
○議長（光益良洋）
３番藤島玄稔議員。
○３番（藤島玄稔）
まず、第５次総合計画の施策評価について、かなり冷静にかつ厳しく評価をされておるこ
とに感服いたしました。
その中で、全体の約22％に当たる事業については「あまり進んでいない」というふうな冷
静な評価をされておりますけれども、この遅れの主な要因はどのように分析されておられま
すか、お尋ねいたします。
○議長（光益良洋）
企画課長。
○企画課長（井上新五）
前期基本計画に掲げます施策に対し「あまり進んでいない」と評価された事業及び要因に
つきましては、主に環境保全面として、空き家・空き地の管理や移住・定住施策、ふるさと

納税事業やＤＸ事業となります。その多くの事業につきましては、相手方の意思や行動が成
果に直結する事業となりますので、事業は進めていますが、成果が「あまり進んでいない」
という評価となっております。
以上でございます。
○議長（光益良洋）
３番藤島玄稔議員。
○３番（藤島玄稔）
その件でございますけれども、令和８年度はどのような対策をお考えでございますか。
○議長（光益良洋）
企画課長。
○企画課長（井上新五）
空き家・空き地対策につきましては、移住・定住事業との連携強化を進めてまいりたいと
考えております。国、県が進める制度を基本としまして、これまで実施してきました空き家
の利活用相談会、こちらの開催や移住希望者のニーズとマッチングさせる専門アドバイザー
の活用などを検討し、一体的に取組を進めてまいりたいと考えております。
また、ＤＸ事業につきましては、令和８年度交付金事業などを活用しまして、住民サービ
スの向上及び内部事務の効率化を図っていくＤＸ化、この事業に取り組む計画としておりま
す。
以上でございます。
○議長（光益良洋）
３番藤島玄稔議員。
○３番（藤島玄稔）
私の質問に対しまして、数字をちゃんと出されましてお答えをいただいたことに感服いた
します。
そして、スタートした第５次総合計画につきまして、進捗状況が厳しい状態もあるという
ところにつきましては、力強く立ち向かわれる姿に誠に感服をいたしました。
令和13年度には「世代を超えた住み心地の良い、温もりと笑顔あふれるまち」が達成され
ることを心から希求して、また願っているものであります。ありがとうございました。
次に、個別の事業についてお尋ねいたしました。
災害復旧・復興事業につきましては、常に進捗や展望を町民の皆さんに知らせて、安心に
つなげていくことが大切だと私は思うわけですけれども、そこでまず１つ目、災害復旧事業
については原形復旧工事が原則であると理解はいたしておりますけれども、利便性、危険性
に配慮した改修工事に取り組んでおられるか、お尋ねいたします。
○議長（光益良洋）
建設課長。
○建設課長（山口哲生）
お答えいたします。
議員御指摘のとおり、災害復旧工事におきましては原形復旧が原則となってございます。し
かしながら、災害査定前の国、県との設計協議の中で、例えば、現在、復旧工事中の松川原
橋、高山橋、完了しました内屋敷橋につきましては、被災前の橋梁には河川の真ん中に橋脚

というものが存在しておりましたが、現在の河川管理施設等構造令に基づき橋脚がない構造
の設計とし、今後、橋脚に流下物が引っかかることを防ぎ、被害を出さないような、以前よ
り安全性の高い橋梁となってございます。
利便性につきましては、災害復旧工事において、構造上で利便性を向上させることは難し
い面もございますが、できる限り早期に復旧を行うことで、地域住民の皆様が通常どおり利
用できる環境を整えることが利便性を確保する上で重要であると認識してございます。
このように、現在の復旧事業、また、今後起こり得る災害復旧につきましても、安全性、
利便性の両立を目指し、取り組んでまいる所存でございます。
以上でございます。
○議長（光益良洋）
３番藤島玄稔議員。
○３番（藤島玄稔）
広川の浸水対策重点地域緊急事業についてお尋ねしておりますが、地元説明会では、新た
な要望などは出ませんでしたか。
○議長（光益良洋）
都市計画課長。
○都市計画課長（園田和広）
地元説明会では、関係者から様々な意見や要望が出されております。具体的な数はちょっ
と把握しておりませんが、維持管理費の地元負担軽減に関する要望や、今回、事業に含まれ
ていない固定堰の改修要望等が多かったように感じております。その他、農地の浸水被害へ
の対策や床下浸水被害への対応等の要望が出されておりました。
以上でございます。
○議長（光益良洋）
３番藤島玄稔議員。
○３番（藤島玄稔）
私も扇島での説明会に参加したわけですけれども、井堰を転倒堰に改修した場合には、井
堰管理が課題となっているのではないかと思いますけれども、今後の対応についてはどのよ
うにお考えでしょうか。
○議長（光益良洋）
都市計画課長。
○都市計画課長（園田和広）
転倒井堰に改修した場合、維持管理が課題になっていることは認識しております。維持管
理費が固定堰よりも大きくなってまいりますが、ゲート本体は、今回、転倒堰についてはス
テンレス製のため、長期間運用できるものと考えております。また、保守点検料や電気代、
消耗品等の費用については約15年間分とお聞きしておりますが、県から町へ補償いただくよ
うになっております。転倒堰の改修までに地元水利関係者と維持管理についての運用方法等
について協議をし、決定していきたいと考えております。
以上でございます。
○議長（光益良洋）
３番藤島玄稔議員。

○３番（藤島玄稔）
それから、今後の課題についてですけれども、今回の事業で対象となっていない井堰であ
るとか河川の周辺についてのお考えについて、町の対応についてお尋ねしたいと思いますの
で、よろしくお願いいたします。
○議長（光益良洋）
建設課長。
○建設課長（山口哲生）
お答えいたします。
