子ども課長。
○教育委員会事務局子ども課長（才所潤一）
庁舎内でのこどもまんなか施策の関連事業の連携推進体制ですが、副町長をトップとして、
子ども課と企画課によるコアメンバー会議に加え、各課から選出のプロジェクトチームを編
成し、重点施策事業や、それぞれの課において取り組んでいる関連事業の進捗状況の確認を
行うとともに、課題を洗い出しまして、今後の方策などについて検討を行っているところで
ございます。
以上です。
○議長（光益良洋）
３番藤島玄稔議員。
○３番（藤島玄稔）
このこどもまんなか施策についてですけれども、こどもまんなか施策の進捗というのはど
のように捉えておられますか。
○議長（光益良洋）
子ども課長。
○教育委員会事務局子ども課長（才所潤一）
こどもまんなか施策の進捗につきましては、令和６年12月に作成しましたアクションプラ
ンにて、今後想定している事業として掲げておりました29の事業につきまして、関係各課へ

の年２回の進捗状況確認調査、またヒアリング調査により評価を行っております。29事業の
うち、現在順調に進んでいる事業が55％となっておりまして、全体の進捗は「おおむね良好」
としているところでございます。
また、昨年度に引き続き、小学４年生から大人までのアンケート調査も実施をしておりま
す。設問の中で「あなたの行動や発言で広川町を変えられると思う」という問いに対し、
「はい」と答えた子供の割合が、昨年度41％だったものが44％、「家や学校以外にここにい
たいと感じる場所や好きな場所はありますか」という問いに対しては、「居場所がある」と
答えた子供の割合は、昨年75％だったものが88％と上昇していることから、子供の声を起点
とした取組の成果が表れているものと考えております。
以上でございます。
○議長（光益良洋）
３番藤島玄稔議員。
○３番（藤島玄稔）
こどもまんなか施策というのはかなり浸透してきておりまして、子供たちからも、自分た
ちが注目されているという感じをよく受けるわけですけれども、これについては私も大変期
待をいたしておりますので、どうぞよろしくお願いいたします。
