小学校での修学旅行で被爆者体験を語り部の方に伺うということをお聞きしましたけれど
も、これはかなりショックなこともあるかもしれませんけれども、この貴重な経験というの
は今後もしっかりされていくことと思いますけれども、中学校ではどのような形で教育をさ
れておられるか、お尋ねいたします。
○議長（光益良洋）
子ども課長。
○教育委員会事務局子ども課長（才所潤一）
中学校におきましても、令和６年度に長崎の平和祈念館より語り部の方を派遣していただ
き、被爆体験講話を取り入れた直接的な学びを実施しております。中学校における平和教育
は、小学校で学んだことを基盤とし、より深い理解を促すための教育が求められていますの
で、被爆体験講話を通じて得た知識や感情を基に戦争や平和についての議論を行うことで、
現代の国際情勢や平和の維持に向けた課題について考える力を養うことを目的として行って
いるところでございます。
以上でございます。
