子ども課長。
○教育委員会事務局子ども課長（才所潤一）

平和な世の中をつくっていく一人としての自覚を高めるためには、子供たちが自らの言葉
で平和について考えたことを表現する機会を設けることが重要であると考えております。具
体的には、修学旅行を通して体験したことや学んだことを発表したり、平和学習で学んだこ
とを基に平和を維持していくための宣言文を作ったりするなどの取組をより一層充実させる
ことが重要であると考えております。
今後も、学校教育を通じて平和な世の中をつくっていく一人としての自覚を高め、次世代
に平和のバトンを渡すことができる人材育成に努めてまいりたいと考えております。
以上です。
