○選挙管理委員会書記長（鹿田 健）
小学生の感想でございますが、小学校のほうでは、私ども、それから明推協の方々に協力
していただきまして、給食大臣を選ぼうということで、明推協の方に候補者になっていただ
いて、給食に係る主張をしていただいて、それに対する投票という形でやらせていただいて
おります。それを私のほうも見ていましたところ、しっかりとその主張を子供たちが聞いて、
自分で考えて投票に参加しているように見えたところでございます。
それから、その投票のやり方につきましても、実際の投票用紙と同じ材質の投票用紙を使
いまして、投票用紙の交付、投票箱についても実際のものを使って投票を行ったところでご
ざいます。
一番の感想については、投票用紙が破れにくくて、折った状態からすぐ開くという工夫が
されていることに関心を持った子供たちが多かったようでございます。また、選挙の大切さ
についても理解できたという感想も見られております。
以上でございます。
