○議長（光益良洋）
休憩前に引き続き会議を開きます。
次に、６番山下茂議員の登壇を求めます。
○６番（山下 茂）
６番山下茂です。通告どおり２点お伺いいたします。
2020年12月に京都市長が財政再建団体に転落する可能性があると発表されました。政令指
定都市でもある人口約150万人の京都市でも破綻する可能性があるかと衝撃を受けました。
近年、財政非常事態宣言を発令されている自治体も増えてきているように感じておりま
す。主な財政悪化の原因は、人口減少による所得税など自主財源が減少したこと、扶助費や
社会保障費などの歳出が増加したこと、施設の維持費や公共インフラの改修費が膨らんだこ
とも一因となっております。
今後の広川町の財政状況についてお伺いいたします。それと、令和８年度税制改正に伴う
影響についてもお伺いさせていただきます。
次に、広川町が持続可能なまちづくりを進めていくためには、地域を担う行政区が活動の
拠点として住民の参画や協働を進める役割を果たさなければなりません。その行政区の活動
も年々厳しくなっていると感じております。そんな中、地域コミュニティ推進事業が２年間
の延長を決定されました。地域コミュニティ推進事業とその基盤でもある自治会の今後の在
り方についてお伺いします。よろしくお願いいたします。
○議長（光益良洋）
町長。
○町長（氷室健太郎）
山下議員への御質問にお答えをいたします。
まず、財政状況に関する御質問についてでございます。
議員御指摘のとおり、全国的に多くの自治体が厳しい財政状況に直面しており、本町にと
りましても決して対岸の火事ではないと思っております。本町の財政状況につきましては、
実質公債費比率などの財政指標で見れば、現時点では健全な水準を維持しております。現在、
好調な経済状況や賃上げ、物価高などを背景として、税収、交付金、地方交付税は増収と
なっておりますが、長期的には人口減少に伴う歳入の伸び悩みや高齢化による社会保障関係
経費の増加など、構造的な課題は年々深刻化するものと考えております。
将来にわたって持続可能な行財政運営を行っていくために、今後も危機感を持って財政規
律の堅持に努めてまいります。
次に、広川町の地域コミュニティ推進事業及び自治会の今後の在り方についてお答えをい
たします。
まずは、区長、分館長、衛生班長をはじめ、地域の自治会活動の最前線で多大な御尽力を
いただいている役員の皆様、そして地域の皆様に深く敬意と感謝を申し上げます。
本町の自治会は、山間部から中心部まで多様な特性を有しております。しかし、現在、全
国的な潮流である人口減少や少子高齢化、さらには生活スタイルの変化に伴う担い手不足な
どにより、自治会運営が転換期に直面していることは私どもも深く認識しております。
今後の自治会の在り方としては、人口の減少や偏在が進む中で、これまでの枠組みに縛ら
れない柔軟な手法があっていいと思っております。具体的には、複数の区で共同で地域活動

や連絡調整を行うモデルなどが考えられますが、大切なのは、町行政から押しつけられたよ
うなものではなく、各地域の住民の皆さんから自らが必要だと思える形であることです。こ
れまで自治会は、住民相互の連絡調整や親睦、交流、そして見守りや支え合いといった福祉
の基盤ともなり、極めて重要な組織として歴史を積み重ねてきました。これからの自治会も、
これらの本質は変わることはありません。町としては、役員の皆さんの負担を最小限に抑え
るなど、担い手不足を解消するための施策を講じるとともに、財政や情報提供の面からも支
えていきたいと考えております。
現在の地域コミュニティ推進事業においても、自治会を地域課題を自立的に解決するまち
づくりの主役と位置づけております。
今後も時代の変化に即した新しい自治会の形を行政と地域とで一緒になって模索しながら、
自治会の持続可能性を高めたいと考えております。
以上でございます。
○議長（光益良洋）
６番山下茂議員。
○６番（山下 茂）
まずは、広川町の長期的な歳入の見通しと、先ほど説明がありましたが、令和８年度の税
制改正に伴う町の影響についてお伺いいたします。
国はプライマリーバランスが28年ぶりの黒字、約１兆3,000億円の黒字と発表がありまし
た。物価高騰により、売上上昇分が法人税や消費税等にそのまま反映した形となっておりま
す。一部の税収の上昇は地方にも還元されているものと考えておりますが、広川町に目を向
ければ、今後の人口減少の影響など、所得税や固定資産税も自然と減少していくものと考え
ております。
今後の広川町の長期的な歳入の見通しについて先ほど町長から説明がありましたが、もう
一度説明をお願いします。
それと、今年度のガソリンの暫定税率の廃止、もしくは、いわゆる1,030千円の壁の撤廃
などに伴う広川町の歳入の減収が見込まれますが、それの予想について、広川町の影響につ
いてお伺いをいたします。
○議長（光益良洋）
総務課長。
○総務課長（鹿田 健）
それでは、お答えいたします。
国のほうは好調な税収等を反映して、予算上はプライマリーバランスが黒字であるという
報道がなされております。町のほうでは、歳入の根幹をなします町税につきましては、短期
的には国の動向と同様に、住民税、交付税等の増が見込まれますが、町長答弁にもありまし
たとおり、長期的には、人口減少や少子高齢化の進行によりまして、個人住民税を中心に緩
やかな減少傾向が続くのではないかと予測しておるところでございます。
一方、交付税につきましては、国の地方財政計画に大きく左右される側面がありますので、
総じて歳入環境、国全体の人口減少が進めば、これまで以上に厳しさを増していくものでは
ないかと思っているところです。
令和８年度の税制改正に伴う町の影響についてでございますが、ガソリン税の暫定税率の

廃止によりまして、地方揮発油譲与税の減収、また自動車税、軽自動車税の環境性能割の廃
止によりまして、環境性能割交付金と軽自動車税の減収が見込まれております。所得税1,030
千円の壁などの改正に伴う個人住民税への減収も見込まれておるところです。このうち、地
方揮発油譲与税、環境性能割交付金の減収見込額は、全額、地方特例交付金で措置される計
画となっているところでございます。1,030千円の壁の改正に伴います個人住民税への影響
額は、15,000千円の減収を見込んでいるところでございます。予算上の住民税、所得割につ
きましては、賃上げ等の影響によりまして、前年度よりも増収を見込んでおるところでござ
います。
以上でございます。
○議長（光益良洋）
６番山下茂議員。
○６番（山下 茂）
長期的には、人口減少を含めて減少傾向にあるかもしれないけど、今年度につきましては
問題ないということだと思います。
広川町の人口も２万人に近いと言われておったけれども、１万9,048名と。いつ１万9,000
人を下回るかといつも危惧しているところでございます。
次に、広川町の長期的な歳出の見通しについてお伺いをいたします。
国の社会保障費は、2025年度予算ベースで約40兆円となり、ＧＤＰ比でも約22.4％に達す
る見込みと言われております。関連の社会保障費を加えれば約32％を超え、今後も増加傾向
であると考えられます。専門家の間では、2040年頃には社会保障制度は継続できなくなるの
ではないかと危惧をされております。広川町でも同様に、扶助費等は今後も歳出の増加が見
込まれるものと考えております。
昨年１月28日に埼玉県八潮市で道路陥没事故が起こり、インフラ整備の改修についても社
会問題化しているところです。広川町でも同じような状況だと考えております。
私は９月議会で公共施設の維持管理について質問させていただきました。維持管理につき
ましては、管理費が一番の課題であると受け止めております。
その後、最近になりまして、町のほうから連結会計でもある八女地区消防組合から本部の
建て替えの概算の見通しの説明がございました。一部事務組合の八女西部広域事務組合では、
斎場の整備計画の委員会も立ち上がったとお伺いをしました。ほかにも公立病院の建て替え
の話も前からありますし、現状は大赤字ということが新聞のほうでも掲載されておりました。
また、今後ごみ処理施設の建て替えの話も出てくるようですし、広川町においては上広川小
学校の移設の建設委員会が立ち上がりました。広川ダムの改修の話もこの間から説明がござ
いました。県の予算ですが、町もそれなりの対応が必要だと考えられます。このことからも、
町の今後の扶助費等の増加、インフラ整備等はこの後も増加していくと考えられます。今後
の広川町の長期的な歳出の見通しについてどう考えてあるか、お伺いをいたします。
○議長（光益良洋）
総務課長。
○総務課長（鹿田 健）
国の社会保障費の増加と同様に、議員のほうが懸念されているとおり、少子高齢化や障害者
福祉に係る医療・介護サービスに関する扶助費や繰出金が年々増加をしておるところです。

また、町職員の人件費や地方債の利率が上昇局面にあるなど、削減することが容易でない義
務的経費が大幅に増加している状況で、今後もこの傾向は続くのではないかと考えていると
ころでございます。
また、御指摘のとおり、一部事務組合の消防庁舎改築事業をはじめ、火葬場についても改
築の検討が始まり、その他の施設についても老朽化問題等が出てきております。
さらには、町単独の課題としまして、上広川小学校の移転、道路等のインフラ更新等、今
後数年から10年程度の間に多額の財政需要が集中することが想定されているところです。９
月議会でもお話ししたとおり、公共施設の長寿命化などにも多額の財源を必要とする状況で
ありまして、有利な地方債を探すであるとか、基金の活用が必要不可欠であると考えている
ところでございます。
地方自治体の予算につきましては単年度の予算主義が取られておりますので、制度そのも
のが単年度で設計されることが多いために長期的な見通しは非常に難しいものではあります
が、歳入の減収傾向とは逆に、歳出は減収傾向とはならないのではないかと考えているとこ
ろでございます。
町長答弁にもありましたとおり、危機感を持った行財政運営を行いながら、将来世代に過
度な負担を残さないような財政運営に努めてまいりたいと思っております。
以上でございます。
○議長（光益良洋）
６番山下茂議員。
○６番（山下 茂）
町の行財政運営については、しっかり状況を見ながら判断をしていただきたいと思ってお
ります。
次に、さきの衆議院議員選挙の結果におきまして、第２次高市内閣が誕生いたしました。
２月20日に高市総理の施政方針演説が行われ、経済成長と国民生活の安定を最優先にすると
いう姿勢が鮮明に打ち出されました。その中で、財政に関わりそうな点を質問させていただ
きます。
高市政権では、コロナ以降に膨れ上がった補正予算を縮小させ、当初予算に盛り込む話が
出ています。これによって、例えば、町のほうとしては資金繰りがよくなる、もしくは急な
施策が入らないことによって重点施策に集中しやすいなど考えられますが、町の影響につい
て何かあるか、お伺いをいたします。
○議長（光益良洋）
総務課長。
○総務課長（鹿田 健）
国の予算編成の方針の転換に伴います本町への影響についてお答えをいたします。
議員が御説明されたとおり、国においては補正予算の規模を縮小して、当初予算に十分な
財源を計上する方針が示されておりますことは、地方自治体の財政経営にとっては極めて好
ましい変化であると受け止めているところでございます。その理由につきましては、１つ目
に事業の平準化と計画的な執行が可能となるということ、それから２つ目に、事務負担の軽
減と本来業務への注力ができるということ、３つ目に、財政見通しの確実性が確保できると
いうことでございます。

町といたしましては、国のこの方針転換を好機と捉えて、早期に事業計画を確定すること
で、町にとって必要とします施策を迅速かつ着実に実行してまいりたいと思っているところ
でございます。
以上です。
○議長（光益良洋）
６番山下茂議員。
○６番（山下 茂）
町としては運営がしやすくなるということですね。
次に、複数年度予算編成についても今議論がされているところです。これはまだ行ってい
ませんけど、町への影響、もしくは課題、研究調査等をされておられるか、お伺いいたしま
す。
○議長（光益良洋）
総務課長。
○総務課長（鹿田 健）
国が掲げる複数年度での予算編成の方針につきましては、具体的な話とされているもので
はありませんが、地方自治体が中長期的な視点でまちづくりを進める上で大変有意義なもの
ではないかと考えているところでございます。
特に、道路、橋梁などのインフラ整備事業におきましては、単年度の予算措置にとらわれ
ず、計画的かつ効率的に事業を進めることが可能となるのではないかと思っているところで
ございます。
以上です。
○議長（光益良洋）
６番山下茂議員。
○６番（山下 茂）
複数予算制度の件につきまして、ちょっと紹介だけさせていただきます。
これは平成18年、約20年前に農林水産政策情報センターというところが作っています複数
年予算制度ガイドです。初めのところだけ少し読ませていただきます。
「1973年のいわゆる「石油危機」の発生に伴い、ＯＥＣＤ加盟国を始めとする先進諸国は、
厳しい財政状況に陥らざるをえなかった。このため、1980年代に入ると、各国とも「小さな
政府」を目指し、各種の行政改革への取組みを行うとともに、予算編成システム面でも、複
数年度化、グローバル（プログラム）予算、発生主義といったそれまでにはなかった要素が
取り入れるようになった。」と。これの最後のところに「わが国が複数年度予算の導入の検
討を始める場合の「道しるべ」としてとりまとめたものである。複数年度予算導入が検討が
行われることとなった際に関係者に参考としていただければ、幸いである。」ということで
書いてあるのです。
中身に対しては、数字も20年前のことで変わっておりますが、大切なのは予算編成システ
ムの複数年度化の動きは、単なる従来の単年度にあった予算編成の期間を複数年度にするも
のではなく、予算編成システム全体ないしは従来の予算編成手法の一部を抜本的に改革する
動きであり、ｎｐｍによる行政改革と相まって、行政決定の過程と相互に密接する関係にあ
るものということが分かったということでございます。ぜひ行政改革を含めて予算編成は、

時間があるときはこれを一度読んで参考にしていただきたいと思います。
次に、国では日本版ＤＯＧＥ（デパートメント・オブ・ガバメント・エフィシェンシー）、
政府効率化省などが検討されていると伺っております。また、片山財務大臣は租税特別措置
の徹底的な見直し、聖域なき歳入改革を断行する姿勢を見せられ、補助金担当見直し室が内
閣官房に設置されました。いわゆるコスト型の施策から成長分野に投資する施策へ転換させ
るための予算システムだと思っております。
役場の現状を見ますと、課題解決のない事業はゼロベースで考え直すことも必要だと思っ
ています。これは町長の答弁にもありましたので、重なるところも出てくると思います。私
自身も、うまくいかないケースは無理に継続しますと属人化したり、取得権益化するケース
もあると思いますので、少し考えていただけたらどうかと。私自身も60年間広川町に住んで、
一歩も出たことがございません。町の職員の方を見られても、昔からお知り合いの方で、行
政も20年、30年ここでやってある方でベテランではございますが、やっぱり新しい目線で見
ることが必要だと思います。
そこで、川畑副町長はほかの各自治体の行政も見られております。新しい基準で判断でき
るところが大いにあると思っております。町としても、効率の悪い事業、やり過ぎ需要など
を廃止、削減を検討するのもどうかと思います。また、働き方改革の目線やコスト意識など
の面からも検討していただきたいと思います。
そこで、副町長にお伺いいたします。
広川版ＤＯＧＥみたいなプロジェクトの結成や、将来、人口減に伴う難しい財政運営など
を踏まえた町の施策の方向性について副町長の見解をお願いいたします。
○議長（光益良洋）
副町長。
○副町長（川畑研介）
御質問ありがとうございます。私が国から来ているということもありまして、大変期待の
まなざしで御質問いただきましたことをうれしく思っております。ありがとうございます。
まず、議員御指摘の日本版ＤＯＧＥでございますけれども、これは御質問の中にもござい
ましたが、昨年11月25日に租税特別措置や補助金の適正化を進めるために内閣官房の行革事
務局のほうに設置をされました、議員おっしゃった租税特別措置・補助金見直し担当室を指
しているものと承知してございまして、その中においても昨年末、12月25日でございますが、
点検、見直し等に関する資料が公表されてございます。そちらを拝見しますと、不明繰越し
といった、そういった発生状況などに鑑みた補助金の縮減の方針などが示されてございまし
て、先ほどの総務課長への御質問に関しましてもお話しございましたけれども、議員おっ
しゃるとおり、広川町を取り巻く中長期的な目線での構造的な難しさや福祉関連経費の増加
といった大変厳しい財政状況、局面を迎えているものというふうに考えてございまして、
おっしゃるようなゼロベースという考え方はとても重要であるというふうに私も考えており
ます。
今議会の冒頭で、氷室町長からも施政方針として、先ほども申し上げましたけれども、次
年度予算案ですね、こちらは議案にも提示をさせていただいておりますが、その中でも、基
本方針として現状維持は後退、それから慣行にとらわれないゼロベース思考による選択と集
中、戦略的な資源配分と構造的な行財政改革を基本方針とするということで、私も予算編成

過程におきましては査定に参加をし、各事業の内容、必要性等についてしっかりと関係各担
当課長であったりとか係長と議論を交わしてございます。そして、提示をしております予算
につきましては、より効果的でめり張りのあるものに仕上がっておるかなというふうに考え
てございます。
一方で、かねてから今年は町制施行70周年ということもございまして、これまで広川町の
御先人の方々が積み上げてこられたものもあります。そうした、かねてから大事にされてき
たもの、今ある仕組みはこの広川町のつくりということにもしっかりと目を──温故知新の
観点から大事にしながらも、日々変化していく行政需要に機動的に対応していくことが今
我々広川町の執行部として求められることであろうというふうに考えております。その中に
おいて、まさにおっしゃったようなＤＯＧＥの趣旨というものに関しては、８年度予算案の
編成過程においてもしっかりと我々の理念としても受け持っておりますし、こうした取組を
職員一人一人が発想として自分の中に持っていくことも大変重要であるというふうに考えて
ございます。
いずれにしましても、広川町の第５次総合計画に掲げておりますような「世代を超えて住
み心地の良い、温もりと笑顔あふれるまち」の実現に向けて、氷室町長の下で私も役場職員
を牽引しながら広川町一丸となって必要な取組を進めてまいりたいと思っております。よろ
しくお願いいたします。
以上です。
○議長（光益良洋）
６番山下茂議員。
○６番（山下 茂）
ありがとうございます。ぜひ活躍を期待しておりますので、よろしくお願いいたします。
次に、広川町の基金の取扱いについてお伺いをいたします。
国の施策の中で、ファンドの利用の施策等がいろいろと検討されております。令和６年度
の広川町の決算特別委員会の意見書の中でも、計画的な財政運営に努めるとともに、基金の
活用については、今後、在り方を十分検討されたいとありました。広川町でも何らかの金融
資産の運用を行うべきだと私は考えております。
最近、大阪府の和泉市や岡山県真庭市、京都府亀岡市など、ＪＲ西日本株を１億円分保有
し、新たな資産運用戦略として話題になっております。同時に、地域課題の一つでもある公
共交通路線の維持に物言う株主として自治体が企業と向き合う機会になるとも考えておられ
ます。広川町でいえば、西鉄やＪＲ九州、九州電力、九電工などが公共インフラ企業と思い
ます。小さな自治体とそういう企業が向き合う機会になると考えております。
今後の基金の取扱いの方針とともに、もし株購入に踏み切る場合、条例、規約等、何か問
題があるようなことがあれば、お伺いいたします。よろしくお願いします。
○議長（光益良洋）
総務課長。
○総務課長（鹿田 健）
御質問の基金の運用に関する件についてお答えいたします。
貴重な自主財源であります基金を少しでも有利に運用し、歳入を確保したいという議員の
御提言は大変重要な視点であると認識しております。また、交通事業者等の株式を取得して、

株主として権利を行使することで地域公共交通の維持を図るという考えにつきましても共感
するところでございます。しかしながら、公金の運用につきましては、地方自治法に「確実
かつ効率的に運用しなければならない。」と規定されており、安全性、流動性、効率性の３
つの原則が求められているものと解釈しているところでございます。
地方自治法において、基金の運用を株式で行うことは否定されているものではございませ
んが、住民の皆様からお預かりした貴重な税金である以上、元本が保証されていることを最
優先として、元本割れのリスクを負うことは慎重であるべきではないかと考えているところ
でございます。
ただし、昨今の物価上昇局面におきましては、現金の価値が実質的に目減りするリスクも
無視はできないところです。株式はインフレに強いと言われるところもありますので、長期
的に基金の実質的な価値を維持させ、町財政に有利に働く可能性もあると考えておりますの
で、先進事例などの情報収集に努め、幅広く調査研究を行ってまいりたいと考えております。
以上でございます。
○議長（光益良洋）
６番山下茂議員。
○６番（山下 茂）
僕はユーチューブなどで国会議員である、元ゴールドマン・サックスの岡本三成さんとか
をよく見るんですけど、やっぱり政治のほうでも金融感覚のある行財政というのは必要じゃ
ないかなと最近考えているところでございます。議会からも監査委員さんを出しております
し、いろいろな立場から意見を取り入れてもらいながら、今後、調査研究をしていかれたら
と思っておるところでございます。
そこで、氷室町長にお伺いをいたします。
今後の財政状況は先ほどから説明のとおりだと思います。今日の中でも言われておりまし
たので──とは思いますが、国では責任ある積極財政と銘打ちまして、財政支出を拡大しな
がら景気回復を促す施策を行うようでございます。広川町でも持続的な発展と住民が安定し
て楽しい生活ができるまちづくりをするためには、町長として非常に難しい立場であること
は理解をしているところです。
氷室町長の令和８年度の予算編成方針、先ほども言われたんですけど、それと、長期的な
財政施策の方針についてよろしくお願いいたします。
○議長（光益良洋）
町長。
○町長（氷室健太郎）
ありがとうございます。議員御指摘のとおりでありまして、人口減少であるとか、広川町
を取り巻く環境というのは本当に厳しい状況にあるというふうに思っておりまして、私ども
も少ない資源ではありますけれども、若い世代が都市部にどんどん流出していく、これに対
抗する移住・定住であるとか、社会減に対する対策、やっぱり少子化が進んでいるので、子
ども・子育て支援策を講じていかないといけないという自然減の対策、なおかつ、これから
人口減少が進んでいく中で、それでも活力ある地域社会をつくっていかなければいけないと
いう、この３本ですね、三正面に取り組まなければいけないという状況にありますので、非
常に難しいかじ取りだというふうな認識をしております。

そういった中でも、先ほどからありますように、公共施設の維持管理とか、将来的にも当
然必要になってくる経費等はもう既に組まれているわけですので、令和８年度当初予算の施
政方針で申し上げましたように、職員に対するメッセージの中でも、行財政基盤の確立であ
るとか、選択と集中であるとか、そういった危機感を共有して、規律ある財政の運営に努め
ようということでしております。
中長期的な視点も含めながら、厳しい財政運営ではありますけれども、未来に希望が持て
るような、そういった予算編成に努めてまいる所存でございますので、引き続きの御指導を
よろしくお願いいたします。
○議長（光益良洋）
６番山下茂議員。
○６番（山下 茂）
先日、簑原八女市長が2040年何とかプランというのを立ち上げるみたいな話があります。
単年度もそうですし、総合計画も半分が終わるということで、長期的なプランもしっかり見
ていただきながら運営をしていただきたいと思います。よろしくお願いします。
次に、地域コミュニティ推進事業についてお聞きいたします。
広川町では、住民による自主的なまちづくりの活動を支援する取組として、地域コミュニ
ティ推進事業を実施されておりますが、その基盤でもある自治会の運営についても後ほど質
問させていただきます。
まずは、地域コミュニティ推進事業についてお伺いいたします。
約15年に及ぶこの事業の受け止めについてお伺いいたします。当初と比べると、基礎自治
体である力も弱くなっておると思いますし、担い手不足や未加入者が増加している現象だと
思います。事業も、役員さんに引き継ぐごとに事業消化になりやすくなっているような気も
しております。また、これは公金ですので、取扱いも割と難しく、結構やる方が属人化して
いるようなところもあると思います。この事業の15年間の町の成果や受け止め、また行政区
からの要望等、意見がございましたらお伺いをしたいと思います。
○議長（光益良洋）
企画課長。
○企画課長（井上新五）
この地域コミュニティ推進事業につきましては、第１期、第２期と継続をしてまいりまし
た。その成果につきましては、自治会の大きな基盤となったものと認識をしているものでご
ざいます。
まず、協働のまちづくりの実践と定着という部分で考えますと、平成30年度の調査では、
ほぼ全ての地区で地域課題の解決という具体的成果が得られております。住民、ボランティ
ア、行政が連携する協働の形が構築されております。その後、コロナ禍という社会情勢を経
て実施しました令和６年度のアンケート調査では、７割を超える地区において、地域課題の
解決や活発な住民参加が継続されているとの報告を受けております。依然として厳しい社会
情勢が続く中、伝統行事の継承や子供、高齢者の見守り活動が急激に衰退することなく継続
されているということは、まさに本事業が地域に根を張り、維持してきた成果であると、現
在捉えております。
事業実施主体からの各地域からの御意見としましては、今後も制度の継続を望むという多

くの声がある一方で、制度開始から長期間が経過したことで、まちづくり委員の交代などに
伴う事業目的の再認識や少子高齢化による次世代の担い手不足、さらには、事務負担軽減の
ための交付金形式の再考などを求める御意見など、持続可能性に関する御意見、課題等が寄
せられている状況となります。
以上でございます。
○議長（光益良洋）
６番山下茂議員。
○６番（山下 茂）
今回、コロナ禍ということで２年の延長が決定されました。なぜ２年だったのか、５年で
も10年でもよかったはずですけど、２年ということでしたので、理由があると思います。ま
た、３年後はどうするのか、事業をされるのか、３年後の方針についてもお伺いをいたしま
す。
○議長（光益良洋）
企画課長。
○企画課長（井上新五）
今回の第３期計画の策定に当たりまして、町としましては、第３期として事業継続を行う
か否かのほうの検証をさせていただきました。
事業実施主体である各地域からは、先ほども申し上げておりましたが、コロナ禍による活
動自粛で十分な活動ができなかった、今後も制度の継続を望むという多くの声をいただく一
方で、地域によっては、事業の継続はもう必要がないというような御意見もいただいており
ます。また、各方面からこの制度の必要性や運営の在り方などについて様々な御意見や御指
摘をいただいているという状況となります。
このように、地域によって事業に対する捉え方や抱える課題が多様化している中で、これ
までの枠組みのまま５年、10年といった長期の継続を決定することはかえって現場の負担を
固定化させ、コミュニティの疲弊を招くおそれがございます。また、コロナ禍により十分な
活動ができなかった期間に対し、本来の活動を展開していただく支援の期間の実施も考慮し
まして、第３期への移行を一旦保留し、第２期を２年間延長する形を取っております。
今回のこの延長期間につきましては、単なる延長ではなくて、令和10年度の制度刷新に向
けた検証準備期間として２年間の延長を設定した形となります。
以上でございます。
○議長（光益良洋）
６番山下茂議員。
○６番（山下 茂）
刷新期間ということでございますね。
１月30日に地域コミュニティ推進事業の延長に伴う説明会がございまして、私も川瀬の代
表として参加させていただきました。参加者のほとんどは区長さん、また、引継ぎの方か分
館長さんか分かりませんが、２人程度で参加してあるところもありました。
説明の中身ですが、食費が物価高騰によって上限がちょっと変更したことで、２年延長と
いうことで、あまり中身についての説明のほうがございませんでした。町でも、町の方針や
参考となる事例も少し説明をされていたと思いますが、あまりそれが届いていなかったよう

に感じております。
それと、来年度、新しい区長さんも出てくると思いますが、来年度の区長さんにも、先ほ
ど言った趣旨説明をきちんとされるべきだと思いますが、趣旨説明をされるのかどうか、お
伺いをいたします。
○議長（光益良洋）
企画課長。
○企画課長（井上新五）
来年度のまちづくり委員会の委員長への説明につきましては、１月末に実施を１回させて
いただいております。本来ならば、１月の説明会の折に次期の委員長なりに事業の目的など
を引き継いでいただきたいというふうには町のほうは思っておりますが、地域のほうから、
この目的を再度お聞きしたいという声が上がれば、事業説明会のほうを開いて、よりよい制
度となるようにしていきたいと思っております。
以上です。
○議長（光益良洋）
６番山下茂議員。
○６番（山下 茂）
ありがとうございます。ぜひ来年度よろしくお願いしておきます。
それでは次に、行政区自体のほうについてお伺いいたします。
町自体が直接行政区に関われないことは理解をしております。しかしながら、広川町では、
区長、分館長、衛生班長さんと委任契約を結ばれております。また、各区には運営補助金や
公民館活動費、新たな地域コミュニティ活動支援事業など補助金も多く出ておりますし、隣
組長さんには、地域連絡助成金など様々な支援をされております。近隣の市町村と比べても、
突出して支援をされていると認識をしているところでございます。
しかしながら、町民の皆さんからお話を聞けば、今後の行政区の運営については大変不安
を感じておられます。特に担い手不足は課題になっておりまして、区長さん方に聞くと、民
生委員や消防団員の人材確保は難しくなっていると聞いております。また、ちょうど今、年
度末で改選の時期でもありますが、自分の後継者探しでさえ苦労しているような状況でござ
います。
運営上の課題では、小さな行政区では、公民館施設や山林などの維持管理費が課題になっ
ております。また、大きい行政区では、区に入らない人が増加しており、ごみ置場の管理や
巨大化した様々な事業に対応できる人材不足を感じております。この後、役員の成り手不足
から、事実上、運営ができなくなるような行政区や、今後、行政区の合併ですね、先ほど町
長からの答弁でもございましたけど、その辺りは様々な市民要請をされると思いますが、今
後の行政区に対しての町の方針についてお伺いをいたします。
○議長（光益良洋）
企画課長。
○企画課長（井上新五）
将来の行政区の方針といいますか、在り方についてちょっと回答させていただきます。
今後の行政区の在り方としましては、人口減少や偏在化が進む中で、これまでの固定的な
枠組みに縛られない柔軟な手法を展開していく必要があると捉えております。

先ほどの町長答弁にもございましたように、役員の成り手不足、こちらが深刻化している
地区などにつきましては、近隣区などとの連携による実務レベルの共同化が有効な手段の一
つではないかと考えております。具体的には、連絡調整業務を近隣区で分担し、事務の負担
を軽減することで役員を引き受けやすい環境を整える事務の共通化や、単独開催が困難と
なった祭りや防災訓練などを複数の区で力を合わせて実施する行事の合同開催といった、い
わゆる緩やかな連携でございます。これらは決して行政が押しつけるものではなく、やはり
各地域の皆様たちが自らの地域の維持に何が必要かを話し合っていただき、納得感を持って
選択される形だと考えております。
以上でございます。
○議長（光益良洋）
６番山下茂議員。
○６番（山下 茂）
ありがとうございます。このことにつきましては、町長答弁でもありましたように、新し
い自治体の形を模索しながらという話もありましたので、どうぞよろしくお願いしておきま
す。
その中で、近隣の自治体では、地域コミュニティセンターとか校区センターみたいなもの
がございます。そちらには事務局員などが滞在をしておりまして、様々な活動がフォローさ
れているように感じています。また、居場所づくりとして、拠点施設になっているところも
あると思います。将来的に、こういうコミュニティセンターみたいな構想等があるのか、お
伺いいたします。
○議長（光益良洋）
企画課長。
○企画課長（井上新五）
広川町におきましては、現在、各行政区単位で地区公民館や集会所は設置されまして、長
年にわたり地域活動の重要な拠点として機能をしております。
御提案のセンター化につきましては、広域な面積を持つ自治体においては、事務機能の集
約化、また多世代交流の促進を図る上で非常に有効な手段であるというふうには思っており
ますが、本町のようなコンパクトな町域においては、住民の皆様にとって最も身近な既存の
地区公民館や現在の自治会体制、こちらをベースに活動を進めるほうが利点があるのではな
いかというふうに現段階では思っております。
町としましては、新たな施設や団体を立ち上げるのではなく、既存施設の利便性向上や既
存組織の事務負担軽減など、こちらを用いて地域のやり方というのを進めていきたいと、現
段階は思っております。
以上でございます。
○議長（光益良洋）
６番山下茂議員。
○６番（山下 茂）
ありがとうございます。広川町では、アリーナみたいなものとか中央公民館がございませ
んので、ぜひその辺は研究して、先ほどエリア分けみたいな話もされておりましたが、その
辺も研究と、行政区の御意見も聞きながら進めていただきたいと思います。

氷室町長にお伺いをいたします。
４年ほど前、川瀬の公民館で当時の地域おこし協力隊の井上君とか、あと様々な企業と連
携をして、まだ町長が職員時代というか、企画課におられたときですが、イベントをしたこ
とを思い出します。英会話教室やスマホ教室、ピタゴラスイッチみたいないろんな事業をし
ました。コロナ明けでさほど参加人数は多くはございませんでしたが、子供たちは大変喜ん
でいたのを思い出します。
その当時から、町長は公民館の活用や自治会の運営の在り方については課題を持っておら
れたと思います。先ほどの町長の施政方針の中でも、居場所づくりと公民館の活用などあり
ましたが、これは僕は喫緊の課題の一つだと思っておるところです。今後の持続可能な自治
運営について、何度もになりますけど、町長に町の方針についてちょっとお伺いをいたしま
す。
○議長（光益良洋）
町長。
○町長（氷室健太郎）
ありがとうございます。先ほども申し上げましたように、やはり自治会は地域づくりの基
盤であるというふうに考えておりますので、非常に重要な役割を期待するものであります。
４年前に行ったイベント、これは地域おこし協力隊自身が企画をして、インターネット環
境を公民館に持ち込んで、遠隔、離れた場所とつないで英語で交流をしたりとか、そういっ
たことであったり、スマホ教室を高齢者向けにさせていただいたという事業でありますけれ
ども、ああいったような形で、町としても行政区に対する支援、人的なものもありますし、
先ほど行政の中でもＤＸを進めるという話がありました。そういったデジタルインフラを活
用することによって、地域の役員さん方の負担の軽減につながるようなことがあれば支援を
する、そういったふうな様々な手法を用いて自治会の持続可能性を高めていければというふ
うに考えております。
将来的な厳しい行財政運営の見通しも併せてなんですけれども、やはり先ほど議員御指摘
の未加入世帯の増加の問題であるとか、そういったような厳しい現実、耳の痛い現実を真摯
に住民の方々にも説明をして、御理解をいただいて、そして共にどのような在り方が最も広
川町として望ましいかということを議論しながら自治会運営の支援の在り方についても検討
していきたいというふうに思っておりますので、引き続きの御協力をお願い申し上げます。
○議長（光益良洋）
６番山下茂議員。
○６番（山下 茂）
結びになりますが、先日、川瀬区のサロン活動において副町長がお見えになりました。あ
りがとうございました。
副町長の挨拶の中で、地域と医療機関が連携できたことを報告いただきました。内容は、
無償で町内の医療機関の看護師さんが血圧測定や相談ができる体制を取っていただきました。
とてもすばらしい企画だと思っております。今までにない、こういう取組を考えていただく
ことに感謝いたしますとともに、これからも新しい発想、新しい事業をぜひとも実行してい
ただきたいと思って、期待をしておるところでございます。
これにて一般質問を終わらせていただきます。どうもありがとうございました。

○議長（光益良洋）
次に、５番竹下英治議員の登壇を求めます。
○５番（竹下英治）
改めましておはようございます。
今日の一般質問にもあったように、いわゆる政府の動きについての言及はよくあったんで
すが、所属する政党の話はあんまり多くは語らないというのが今までの流儀だったかと思い
ます。私は日本維新の会に入っていますから、ちょっと質問の初めに、12本の矢を活用しな
がら質問に入らせていただければというふうに思います。
後ほどまた小学校の給食の無償化が本予算編成にどう影響するのか聞きますけれども、こ
の小学校給食の無償化については、12本の矢の10番目に書かれていることでございます。あ
わせて、高校授業料の無償化、これも書かれています。
12本の矢の特徴は、いつまでにやると、やれなかったら政治生命をかけるというところに
やっぱり地方行政においても見るべきところがあって、言ったこと、公表したことはしっか
りやり切るということが大切かなというふうに思っています。
それで、約束をしっかり果たすためには、先ほどから副町長もおっしゃっていますが、厳
しい財政状況という言葉がありました。日本版ＤＯＧＥという話も出てきましたけれども、
僕は平生の体制の中で、しっかりと今までも何回もインフラ、フローされているＰＤＣＡ、
これをしっかり回すということ、それと、特にチェック機能をしっかりやるということを平
生の体制からやっていただければなというふうに考えていまして、そのスタンスから質問さ
せていただきますので、どうぞよろしくお願いします。
それでは、今日は大きく２つ、令和８年度の予算についてなんですが、大体予算編成のと
きは執行部から我々議会がトータル的な状況はどうなっているんだということを──前から
総務課長にはちょっとお話しした経緯があると思うんですが、もともと聞きたいことなんで
すよね。全般の状況をつかんで、そして、それぞれの特別委員会に入っていければという趣
旨で聞いています。
２番目の役場職員の人材育成等についてということなんですが、これは前も聞いた内容で
ございます。これについては副町長に最後にちょっとお手数をかけたいと思っていますので、
どうぞ御対応方よろしくお願いいたします。
これについては皆さん立派にやっておられますという部分はいっぱいあると思います。だ
けど、やっぱり悪いところを指摘しないと、なかなかここは語れないので、そういう部分が
流れによってあったらちょっと御容赦を賜りたいというふうに思います。僕は令和８年度の
予算については、各種予算、一般会計、特別会計、公営事業会計、あと基金運用があると思
うんですけれども、それらについて着手した事項を簡単で結構ですから、述べていただきた
いと思います。
あと、特出しとしては、広川町の産業展示会館、これは皆さん、町民もある程度御興味が
あられると思うんですが、これの状況はどうなっているのか。
それと、ネイティブテキスタイル、僕はちょっと疑義を持った事業だなと前から言ってい
ますが、これはどうなっているのか。
それと、先ほど申し上げましたように、小学校給食の無償化、これは確実にやられます。
これについて予算編成上どういう影響等があって、またどういう考慮がなされておるか、そ

ういうのをお伺いしたいと思います。
総括回答は簡単で結構です。
それと、役場職員の人材育成については令和７年３月に広川町人材育成基本方針、これが
12年か13年ぶりに改正されて、１年間過ぎた状況において、今の進捗状況はどうなっている
んだと、抽象的な聞き方ですが、そういうことを聞きたいというふうに思います。
それと、恒常的な組織の中で人に関わる教育の体制があると思います。それがうまく機能
しているかどうか。
あとは、具体的には、定年延長や再任用、それと新規採用についてどういう着意事項があ
るのか。会計年度職員もおられて、また本雇いの方とはちょっと対応の仕方が違うのかなと
思いますが、その辺の人材育成はどうなっているのか、そういうことをお伺いしたいと思い
ます。
以上です。
○議長（光益良洋）
町長。
○町長（氷室健太郎）
竹下議員の御質問にお答えをいたします。
令和８年度予算編成における、まず、熟慮と工夫についてお答えをいたします。
施政方針でも述べましたとおり、予算編成の根底にあるのは、現状維持は後退であるとい
う強い危機感であります。令和８年度は現執行体制として、実質的に本格的な政策を反映し
得る最終実行年度であり、第５次総合計画前期の折り返し地点でもあります。私自ら新年度
予算編成に係るメッセージを発し、戦略的な資源配分と構造的な行財政改革を基本方針とし
て、強い危機感を全職員と共有し、慣行にとらわれないゼロベース思考で予算編成を行って
まいりました。
具体的な工夫と熟慮内容を大きく３点申し上げます。
１点目は、予算編成を２段階に分け、第１段階では、継続事業や経常的経費、第２段階で
は、新規・レベルアップ事業の予算要求を行う取組を実施しました。継続事業等については、
その大本から必要性、合理性等を検証するとともに、未来に向けた投資の観点から、構造的
に既存と新規・レベルアップというマクロな視点での予算配分を重視いたしました。
その過程においては、社会変化の激しい中で新たな行政サービスに対応するべく、第１段
階の予算要求内容を所属長に再査定させ、可能な限り、新規・レベルアップ事業への財源を
確保できるように努めました。
２点目は、限りある財源をどこに振り向けるか、選択と集中による未来への戦略的投資で
あります。
この見直しにより、次の３つの柱へ重点的に配分をいたしました。
１つ目は、強靱な行政経営基盤でありますが、将来の窓口時間の短縮を見据えたＢＰＲ、
ＤＸへの投資、２つ目のこどもまんなか社会では、教育環境の整備への投資、３つ目の安
全・共生社会では、浸水対策事業や国県道バイパス事業、地域コミュニティ事業、健康で暮
らせるまちづくりなど、住民生活の安心・安全を高める事業に予算を重点的に振り向けまし
た。
３点目は、基金運用と特別会計における持続可能性の追求です。

基金につきましては、これまでの定期預金中心の保有を見直し、国債や政府関係機関が発
行する債券への運用へと切り替えるなどを行いました。
また、特別会計、企業会計につきましても、将来を見据えた精査を行っております。
国民健康保険や後期高齢者医療特別会計では、医療費適正化や一般管理費の精査を行い、
広川防災ダム管理特別会計では、費用の平準化を図りました。
水道事業では、管網のループ化による安定供給を、下水道事業では、新たな事業認可区域
である吉常東部付近の整備を進めるなど、インフラの強靱化と生活環境の向上に直結する予
算を計上しております。
広川町産業展示会館につきましては、令和８年度より町直営となりますが、観光協会や商
工会等とも連携をし、引き続き地域のにぎわい創出に努めてまいります。
ネイティブテキスタイル事業につきましても、推進協議会を中心に、拠点施設であるOrige
（オリゲ）、Hodoku（ホドク）の活用や情報発信を通じ、産地の活性化と次世代育成を着実
に進める計画としております。
移住・定住促進事業につきましては、予算規模に大きな変更はございませんが、空き家活
用相談会の開催や専門家の知見を取り入れるなど、実効性の高い取組を継続してまいります。
最後に、小学校給食の無償化につきましては、国の補助基準額と実費との乖離分を町単独
予算で補填することで保護者負担の完全無償化を実現する予算を計上いたしました。
総じて申し上げますと、令和８年度予算は、厳しい財政状況の中でも未来への投資という
変革の意思を込めた予算編成を行ったものであります。
次に、役場職員の人材育成についての質問のうち、令和７年３月に改定いたしました、広
川町人材育成基本方針に基づく本町の人材育成の進捗状況等についてお答えをいたします。
まず、現在の具体的な取組やその成果について申し上げます。
職場風土の醸成として、私は毎月、職員向けにマンスリーレポートを発信しています。唯
一無二のふるさと広川町の発展に向かい、町職員が一体感を持って前進するべく、私の考え
や町の動きについて職員全体で情報共有を進め、チームで仕事をする意識の浸透を図りなが
ら職場の雰囲気づくりや意識改革を促しております。最近では、職員と話す中で、各係や各
課の縦割りを超えて一つの案件に向き合う姿を多く見かけるようになりました。啓発が役場
内での機運醸成に着実につながっていると感じております。
また、組織としても、役場管理職を経営チームと見立てた会議を複数回開催し、組織体制
や人事制度に関する議論を行っているほか、管理職を対象としたマネジメント研修を実施す
るなど、人を生かす職場風土づくりを進めております。
さらに、組織や仕組みをより一層機能させるための最重点項目として、人事評価制度の見
直しを進めております。
現在、職員組合との協議中ではありますが、新年度より評価項目の見直しを行い、行動姿
勢や職位ごとのあるべき姿を評価基準とし、職員の成長とまちの発展との連動を重視した仕
組みへと転換を図り、さらに処遇へも反映させていく計画としております。
採用に関しましては、職員募集要項に人材育成基本方針に掲げる目指すべき職員像を明記
し、従来の筆記試験に代えて人物重視の採用試験を行うなどの見直しを行っております。
さらに、地域活性化起業人など、民間人材の活用も予算化し、多様な人材確保に努めてい
きたいと考えております。

能力開発におきましても、主査クラスへのホワイトボードミーティング研修の実施や社会
人経験枠で採用された職員に対する研修、健康管理、ハラスメント防止に向けた啓発や個別
面談など、職員が安心して働ける環境整備を進めているところです。
一方で、課題について申し上げます。
依然として退職者が多い現状があり、職員の定着に関する取組は喫緊の課題であると認識
をしております。キャリアパスの明確化や個人の才能を生かすタレントマネジメントについ
てはこれから重点的に取り組む必要があると考えております。令和８年度には全ての正規職
員を対象に、個々の強みや特性を診断する取組を実施し、才能を伸ばしつつ、伸び代を明確
化することで個人のレベルアップと組織力の向上を図ってまいります。
また、職場内研修（ＯＪＴ）の質を高める取組や有給休暇取得率といった具体的な数値目
標の設定について令和８年度からの目標を立て、それに向かって具体的な施策を着実に進め
てまいります。
次に、定年延長や再任用、新規採用に関わる事項についてでございます。
現在、複数名の再任用職員に活躍してもらっていますが、限られた職員数の中で多様化す
る業務を遂行する上では欠かせない存在となっております。60歳でリタイアという従来の意
識を変え、シニア人材の豊富な知識や経験、地域との人脈を次世代へと継承していくことが
重要です。現時点においても、個々の業務においてその経験が発揮されている場面もあると
認識しておりますが、方針に掲げる地域課題解決への活用や知識・技能の継承を十分に行え
るような取組を今後も進めてまいります。
会計年度任用職員につきましては、繁忙期のサポートや特定の期間のみ発生する業務に従
事してもらう職員から、保健師や助産師など専門性を有する職員まで様々な職員がおります。
その研修については、中長期的な視点で育成する一般職員とは異なり、現在の業務を正確に
かつ円滑に遂行するための知識等の付与が中心となります。人事評価についても、現在の職
務を適切に遂行できているかや、意欲的に取り組んでいるかなどの確認を通じて、任用期間
中の成長を促してまいります。
最後に、全体的な進捗状況の判断について申し上げます。
新たな人材育成基本方針に基づく取組はまだスタートしたばかりではありますが、職位に
応じた研修の実施や、人事評価制度の刷新をはじめ土台となる仕組みづくりは着実に動き出
しております。今後も人こそが最大の資源であるとの認識の下、粘り強く人材育成に取り組
んでまいります。
以上でございます。
○議長（光益良洋）
５番竹下英治議員。
○５番（竹下英治）
まずは、令和８年度予算についてお伺いします。
先ほどから厳しい財政状況であるとか、町長からは実質公債費比率８％強ぐらいだったと
思うんですけれども──言葉があったんですけれども、現状、６年度の経常収支比率の説明
が前に監査からあったと思うんですが、６年度は大体90％を切った状況だったですよね。７
年度の結果はまだ出ていませんけれども、今の見積りとして、令和８年度の経常収支比率は
大体どのぐらいになるのかなという何か見込みがあれば。

それと、固定費は大体分かると思うんですけれども、予算額から固定費を除いた金額はど
のぐらいになるのかなと。補正はいろいろあると思うんですけれども、その金額が今の時点
でどういうふうに見積もっているのか、丸い数字で結構ですから、教えていただいていいで
すか。
○議長（光益良洋）
総務課長。
○総務課長（鹿田 健）
まず、１点目の経常収支比率の見込みでございますが、これは決算が出ないと出ない数字
でございますので、申し訳ございませんが、見込み等はございません。
それから、固定費という概念もございませんで、現時点での集計した数字はございません。
また概念を整理していただいて、この数字の積み上げをということであれば、集計をさせて
御報告させていただきたいと思います。
以上でございます。
○議長（光益良洋）
５番竹下英治議員。
○５番（竹下英治）
確かにそうなんでしょうけど、町民目線から言うと、大体どのくらいが今後の新たな事業
等に８年度は使えるんだというような、やっぱり丸い数字はちょっと知りたいかなと思うん
ですよね。そういうことで質問させていただきました。
それと、広川町の産業展示会館、先ほどの具体的な項目をお挙げしたんですけれども、こ
れは全協で御説明いただきましたけれども、何で令和８年度は直営とせざるを得ない状況に
