○議長（光益良洋）
産業課長。
○産業課長（山下誠紀）
広川町産業展示会館につきましては、平成23年度から15年間、広川町商工会のほうで指定
管理で運営をしていただきました。今年度をもって広川町商工会が指定管理から退かれるこ
とから、町としましては令和８年４月からの指定管理について一般公募を含め検討を行って
きました。その中で、広川町観光協会事務局の体制強化も含め協議を行ってきましたけれど
も、結果的に協議のほうは調わず、それからの一般公募にも一定の期間が必要なこと、また、
４月から管理者の不在では一般の利用者の方に影響が大きいことから、令和８年度からは直
営管理に至ったものでございます。
以上です。
○議長（光益良洋）
５番竹下英治議員。
