それと、Origeの本来の設置目的、ここは条例で定めてあるとおりなんですが、簡単に言
うと、広川町の移住・定住の促進と滞在交流なんです。この使い方については、町長が特別
に使うこともできるということが条文の中にあることも承知しているんですけれども、かつ、
このネイティブテキスタイル自体が広川町の移住・定住促進を複合的に展開すると趣旨にも
書いてあることも承知しているんです。この移住・定住の機能がOrigeの切り口からは
ちょっと止まっている感じがするんですけれども、これは継続されていると判断してよろし
いんですかね。空き家対策の話とかは結構ですから、ここのOrigeの切り口だけ。
