次に行きますが、直接どういうふうに予算に絡むかという話は今後お伺いする予定なんで
すが、ＳＤＧｓについて、過去も説明しておったんですけれども、今回新たなＳＤＧｓに係る
広川町地球温暖化対策実行計画というやつを配っていただいて、御説明はなかったんですよ
ね。ちょっと読ませていただいたんですけれども、広川町の第５次総合計画の中にもＳＤＧｓ
は総則からしっかりと全ての行政の施策に結びつけるんだということを述べられているんで
すけれども、具体的に広川町地球温暖化対策実行計画の中で、第１項「計画策定の背景」、
それと、第２項に「地球温暖化対策を巡る国際的な動向」ということが同じように総合計画
の趣旨で述べられているんですが、この中で、2015年に開催された第21回のいわゆるＣＯＰ21
ですよね、締約国会議、このことだけが述べられていて、全世界が全て温室効果削減に向け
たというような説明があるんですよね。ところが、御承知のように日本は結構頑張っていて、
温室効果の排出量は、今言われているのは４％未満なんですよね。現実的には、40％を排出
している中国、それと米国。中国はほぼほぼ何もやっていないし、米国はどっちかというと、
パリ条約から外れましたよね。こういうのが世界の現実だと僕は思うんです。
こういう書き方をすると、役場職員も含めてなんですが、町民の方に僕はミスリードする
と思うんですよね。結果的に言うと、施策に対しても影響が出てくると思うんですが、この
書き方で本当にいいのかということをちょっとお伺いさせていただきたいと思います。世界
の現実と違うことを書いておられるのかなと考えています。ただ、担当課長から、係る補助
金を取るためにはこういった計画をつくるということは必要だということは、そういうこと
は僕は理解をしているという状況でございます。
