議員の御質問の中で、この計画をつくった背景について、近年の国際の状況、大国ですね、
米国や中国のスタンスと乖離というか、違いがあるんじゃないかということですけれども、
地球温暖化の状況、現実的には、やはりこれまでの世界の全ての国々がやってきたところが
影響していることは間違いないと思います。それをどれだけ力点を持って各国がするかとい
うのは、それぞれの考え方があるとは思うんですけれども、こういった状況と町民の皆様、
それから各事業者、産業界、農耕関係の方々、いろんな立場の方でこのことを考えていただ

くことが必要かと思っておりますので、そういった考えで広川町地球温暖化対策実行計画
（区域施策編）を作成したところでございます。
以上です。
