す。その中で、この広川町に対する愛着であったりとか思いを持って日夜仕事に邁進できて
いるというふうに感じておりますし、私自身も国家公務員として、初めにやはりそういう第
一線の現場であったりとか、各施設とかの現状を見聞きする中で、そういうところを大事に
してやっていこうという部分から始まっておりますので、今の広川町の職員においても、い
ろいろなところに自分から足を運んでいって、ぜひ地域の方々や各施設であったりとか、そ
