○議長（光益良洋）
次に、９番江藤美代子議員の登壇を求めます。
○９番（江藤美代子）
９番江藤です。通告に従いまして、３点質問をいたします。
１点目、国民健康保険について御質問いたします。
国民健康保険法では「社会保障及び国民保健の向上に寄与することを目的とする。」と書
いています。平成30年、国民健康保険の運営が県のほうに移行しました。町はこれまで５年
間をかけて資産割をなくすため、国民、また国民健康保険制度の維持のために税率の改正な
どを進めてきました。資産割は令和７年度をもってなくなり、３方式となりました。国民健
康保険の税額とか、医療費とか、加入者数とか、どのような現状でしょうか。また、現状や
今後の動向についてどのように受け止めていますか、お尋ねいたします。
２点目、教育費の保護者負担軽減について御質問いたします。
子育て世帯に対しての経済的負担軽減については９月議会でも質問いたしましたけれども、
今回は給食費以外の教育費の負担について再度質問をいたします。
憲法第26条は「義務教育は、これを無償とする。」と明記していますけれども、授業料、
教科書は確かに無料になっていますが、それ以外の副教材費、学級費、ＰＴＡ会費、修学旅
行や校外活動、卒業アルバムなどの積立金などの負担は大きいものがあると思います。さら
に、入学時は学校指定品等の購入など、保護者の負担はさらに大きくなっていると思います。
どのくらいの負担になっているのか、現状をお尋ねいたします。
３点目、各種基金の運用、活用についてお尋ねをいたします。
自治体が自由に使うことができる財政調整基金や使い道が決められている各種目的基金が
ございます。このような基金を設けることについて、もちろん理解をしています。問題は、
その額と使途計画についてであると考えます。その必要性や根拠について、住民に対してき
ちんと説明されなければならないと考えます。
令和６年度決算では、基金総額は増額傾向です。ふるさと創生基金１億円、ふるさとづく
り基金２億円、どのように活用していますでしょうか。今後の活用についてどのような方針
を持っていますでしょうか。
また、公共施設整備基金870,000千円、学校建設基金690,000千円、災害対策基金など、必
要な基金ともちろん考えますけれど、いつ、どんなときに、何に使うという計画があります
でしょうか。また、額としてはどのくらい必要と考えていますか。
最後に、財政調整基金についてですけれども、令和６年度決算では18億円、減債基金360,000
千円の現在高です。この金額は妥当と考えますか。基金の活用、運用についてどのような実
態か、また、どんな方針を持っているのか、お尋ねいたします。お願いいたします。
○議長（光益良洋）
町長。
○町長（氷室健太郎）
江藤議員の御質問にお答えをいたします。
まずは、広川町国民健康保険の現状と今後の動向についてでございます。

国民健康保険の被保険者数は、75歳以上の高齢者の後期高齢者医療制度への移行などで減
少傾向にあり、令和８年１月末の被保険者数は、昨年同時期と比べ95人減って3,779人と
なっております。１人当たり医療費は、令和５年度は419,178円、令和６年度も410千円台と
なる見込みで、県平均を下回ってはいるものの、依然高い状況にあり、削減への取組は引き
続き必要であります。
また、令和８年度からは国の少子化対策として子ども・子育て支援金制度が始まり、医療
保険制度を通じた拠出の仕組みが導入されることとなります。国保の被保険者の皆様にとっ
ても新たな御負担となるものではありますが、少子化対策の抜本的強化につながるものとし
て御理解いただく必要もございます。関連した条例改正案も本定例会に上程しておりますの
で、慎重な御審議を賜りますようにお願いを申し上げます。
さて、国民健康保険は平成30年度から都道府県がその財政主体となり、保険料水準の統一
に向けて動き始め、広川町においても算定方式の変更を５年かけて行いました。県は自治体
ごとに医療費水準や所得水準を基に算定する標準保険料率の統一時期を令和15年度としてい
ます。税額への影響や町の負担を考慮し、段階的に統一に向けた取組を進めるため、県や県
内自治体との協議が今後より加速するものと認識をしております。
次に、保険税滞納の現状についてでございますが、昨年度から短期保険証が廃止された影
響もあって、令和８年１月末時点の収納率は73.1％となっており、昨年度の同時期と比べ
1.5％の減少が見られます。滞納への対応ですが、滞納者に対し、督促状や催告書を適宜送
付し、速やかに納付を促しているところです。また、資力のある滞納者に対しては、預貯金
の差押えや確定申告の国税還付金の差押えなどの法的手段を講じることで収納率の向上に努
めております。一方、資力に乏しく納付が困難な滞納者に対しては、税務会計課及び住民課
が密接に連携し、個別の事情を丁寧に考慮しながら、分割納付の相談に応じるなどの柔軟な
対応を行っております。
最後に、マイナ保険証移行後の今後の対応についてです。
国民健康保険の保険証は、昨年８月の廃止後、マイナ保険証を基本とする仕組みに移行し
ましたが、その保有状況に応じ、資格確認書や資格情報のお知らせを職権により交付してい
るところです。両者の有効期限は今年７月末までですが、それ以降についても、これまでど
おり更新作業を実施し、最長１年間の期限を設け、交付する予定としています。
マイナ保険証は、電子証明書の有効期限から３か月が経過すると使用できないことから、
有効期限の二、三か月前を目途に国から通知が届くことになっています。その通知をもって
役場で更新の手続を取っていただくことになりますが、現在、多くの方がその手続のために
来庁されており、毎月第２日曜日の午前中は事前予約制によるマイナンバーカードの各種手
続のため開庁して対応しております。
今後も被保険者の皆さんが必要な医療を受けられるよう、適切な対応に努めてまいります。
次に、各種基金の今後の活用方針についてお答えをいたします。
現在、町ではそれぞれの設置目的を持って15の基金を保有しており、令和８年１月末時点
で約4,360,000千円の残高を保有しています。
令和７年度においては、40年弱保有していたふるさと創生基金につきましては、竜光寺公
園改修事業の財源として全額活用させていただき、今年度末で全額取り崩す予定としている
ところです。

また、ふるさとづくり基金につきましては、それぞれの目的に応じてその一部を各種事業
に充てさせていただいておりましたが、令和８年度からは活用ルールを明確化し、本定例会
にも議案提出させていただいております次年度予算案において、目的別の残高の３分の１を
上限として積極的に経常経費などにも充当する方針を取っております。
学校建設基金の残高は約735,000千円、公共施設整備基金の残高は約880,000千円でありま
すが、上広川小学校の移転事業、広川中学校、中広川小学校、保健福祉センター、産業展示
会館、古墳公園資料館の長寿命化のための大規模改修等の費用について、その負担を将来に
先送りせずに基金で賄おうとすると大幅に財源不足になるものと考えております。
基金のうち、その残高が一番多い財政調整基金は約1,920,000千円の残高であり、減債基
金においては約356,000千円の残高となっていますが、これらの基金についても経済事情の
著しい変動などによる財源不足等への対応に必要な残高であると考えております。
人口１人当たりの基金残高を県南５町村で比較をしてみると、人口が一番多い筑前町が一
番少なく、次に人口が多い本町が２番目に少ない額となっており、特に基金残高が課題に
なっているとの認識はございません。
今後とも、基金の設置目的に沿って計画的な積立て、取崩しを行ってまいります。
私からの回答は以上でございます。
