教育長。
○教育長（冨山拓二郎）
それでは、私から江藤議員の教育費の保護者負担軽減についての御質問にお答えいたしま
す。
学級費、教材費、修学旅行等の積立金をはじめとする学校徴収金について、小学校は年額
で１年生が21千円、２年生から４年生が約18千円、５年生が約30千円、６年生が41千円です。
中学校につきましては、同様に年額で１年生、２年生が約48千円、３年生が27千円となって
おります。
また、入学時における学校指定品については、各小・中学校の制服等の代金として、小学
校は約33千円、中学校は約100千円となり、小学校では別に教材費として９千円程度の教材
を購入いただいております。
就学援助は、経済的な理由により就学が困難な児童・生徒の保護者に対し、学用品や学校
給食費、修学旅行などの校外活動費等を援助する制度で、本年度の小・中学校の認定者数は
222名、認定率は13.5％となっています。制度の周知については、学校を通じた全児童・生
徒への配付や町ホームページへの掲載に加え、昨年度末より入学支度金のオンライン申請も
導入いたしました。金額面では、入学支度金の単価を見直し、小学校64,300円、中学校81千
円へと増額改定を予定しておりますが、支給項目の変更はありません。入学支度金の申請時
期及び支給時期につきましては、入学予定者の保護者へ12月に案内を行い、１月末までの申
請分は３月上旬に、２月以降の申請分については新年度の７月頃に支給しております。
保護者負担の軽減対策についてですが、学校徴収金につきましては、各学校において教育
活動を行う上で真に必要なものに限定し、保護者の皆様に御負担をお願いしているところで
す。
今後とも教育の質を確保しつつ保護者の過度な負担とならないよう、引き続き各学校に対

し、教材等の厳選を促してまいります。
私からは以上です。
