子ども・子育て支援金についてですけれども、町長の御答弁にもありましたように、８年
度から負担が導入されます。この制度は、国民健康保険の税率に子ども・子育て支援分を設
けて課税する増税です。国民健康保険は、病気やけがのとき安心して医療が受けられるよう
にする社会保障の制度です。しかし、子ども・子育て支援金の対象事業は、児童手当とかこ
ども誰でも通園制度など、子育ての施策です。子育て施策を充実させるなら、国の一般財源
で対応すべきと考えます。明らかな目的外使用で、私は納得ができない制度です。
もう一つ納得がいかない点は、子ども・子育て支援金は子育て支援のための増税であるか
ら、子供に負担させるのはおかしいということで、18歳までの均等割は10割軽減措置となる
となっています。しかし、そのうち未就学児の５割の均等割は公費で負担しますけれども、
未就学児の残りの５割と６歳から18歳までの均等割分は子供以外の国保被保険者が負担する
となっています。これも子育て支援というならば、国が財源を手当てすべきです。国の税の
集め方、税の使い方が問われるのではないでしょうか。
それを受けて、町は今回議案を提案していますけれども、それによりますと、子ども・子
育て支援分として所得割で0.27％、均等割で1,100円、平等割で1,100円、さらに、さっき言
いました18歳以上の方に均等割100円と提案されています。常任委員会の折に、53自治体が
このような方式を取っているというふうに御説明をいただいたかと思うんですけれども、と
いうことは、７自治体はそういう対策ではない、違う方法を取っているということだと思い
ます。この子ども・子育て支援金は今後どのように推移するというふうになっていますか。
