○議長（光益良洋）
９番江藤美代子議員。
○９番（江藤美代子）
教育長の答弁にもございましたけれども、副教材とか積立金とか様々なものがありますけ
ど、これらは教育活動上必要なものであると判断されて採用されているわけであります。そ
れであるならば、公費で負担すべきものがあるのではないかという考えを持っています。
必要な副教材とか、そういうものを公費で負担すべきものなのか、それとも保護者が私費
で負担すべきものなのか、この点について精査が必要であるというふうに考えます。
学校における補助教材及び学用品に係る保護者の負担軽減については、文科省は何度も通
知や事務連絡を出しています。平成27年３月４日付「学校における補助教材の適正な取扱い
について」、平成30年３月19日付「学校における通学用服等の学用品の適正な取扱いについ
て」、令和５年10月23日付「学校における通学用服等の学用品等の適正な取扱いについて」、
つまり、補助教材の購入に関して保護者等の経済的負担が生じる場合は、その負担が過重に
ならないように留意することという通達なんですよね。
これに続けて、さらに2025年６月25日にまた通知を出しています。これはちょっと中身を
読みますが、「この度、現下の物価高により、影響を受ける家計の負担軽減が一層重要と
なっていることも踏まえ、各教育委員会等における検討に資するよう保護者等の経済的負担
を軽減させるために、教育委員会等が工夫をしている事例を下記のとおり整理いたしました
ので周知します。これらも参考としながら、引き続き、地域の実情に応じて、積極的に取組
を御検討いただきますようお願いします。」という通知なんですよね。
その中で、５つぐらい事例を挙げているんですけれども、その１つを紹介しますと、保護
者等負担で購入していた教材を学校備品化──学校の備品として整備して保護者の負担を軽
減するという提案です。これについて教育委員会が学校にヒアリングを行ったり、学校備品
化できる教材を精査したりする、保護者へのアンケートを実施しているところもあるという
ことですね。備品化する教材を一律にするんじゃなくて、学校の裁量に任せているという例
もありますよと紹介しています。また、財源としては、ふるさと納税を活用している事例も
ございますと。備品化するのに予算がつけられないという場合であれば、卒業生や地域から
寄付された物品を活用するという事例も挙げられています。これに対して保護者の声は、購
入する手間と費用が不要となって助かっている、学校の備品としてあることが当たり前と感
じるようになったというふうな事例が挙げられています。
このような事例を参考にして、検討を進めるべきではありませんか。
○議長（光益良洋）
子ども課長。
○教育委員会事務局子ども課長（才所潤一）
学校備品の全体で使用する備品、教材、消耗品などにつきましては、町で予算のほうを組

んで学校で購入をしております。個人持ちの教材等については個人負担をお願いしていると
ころもございますが、公費で負担している備品、消耗品等につきましても、かなり高額と
なっております。令和７年度の予算ベースにおきましても、小学校３校ですが、消耗品費で
12,000千円程度、中学校消耗品で7,500千円程度、小学校の備品購入が4,500千円程度、中学
校の備品購入が3,000千円程度というふうに、全体で使用するような教材、備品等について、
毎年、町のほうで予算を組んで支出を行っている状況でございます。
個人持ちの教材等について備品化できないかということではございますが、そこは発注す
る際も、予算計上する際もしっかりと厳選をいたしまして、保護者の過度にならないように
精査を行っていきたいと考えております。
以上です。
○議長（光益良洋）
９番江藤美代子議員。
○９番（江藤美代子）
十分予算をつけて備品化しているという御答弁だったのかなと思いますが、これについて、
2019年８月に、これも文科省が補助教材の取扱いについて教材整備指針というのを出してい
ます。これは必要数量などを定めて計画的な整備を図ることが望まれる具体的な項目を挙げ
ています。
小学校について見てみますと、例えば、計算ブロック、方位磁針、星座早見板、彫刻刀、
粘土板、粘土べら、短縄など、これは１人に１つずつ備品として整備する項目として挙げら
れています。また、裁縫セットなどは４人に１セットというふうに数をもって指針が示され
ているわけです。今、頑張って備品化していますよという御答弁ですけれども、備品として
整備するものとして挙げられているのに保護者が私費で負担するのが当たり前になっている
ものがないでしょうか。その点をもう一度しっかりと検討していくべきだと思います。１人
何十円とか何百円の負担だったとしても、本当に必要なものなのか、公費で負担できないの
かを検討することは重要だと思います。
例えば、算数ボックスとかだったら分けて、計算カードとかはやっぱり個人持ちかなと思
いますけれども、備品としても大丈夫なところもあるかなと思います。実際、そういうふう
にやっている自治体もございます。丁寧に精査した結果、年間10千円もの削減ができたとい
う事例も紹介されています。
教育長に最後にお伺いいたします。
まず、この学校徴収金の中に含まれているものが教育上、教育の理解を深めるために本当
に必要があるものなのか、その視点で御検討をいただきたい。その教材の使用法とか使用の
程度、頻度などを見直して、本当に必要なものかどうかを精査するという作業が必要なので
はないかなと思います。
２番目、さっきから申しておりますように、じゃ、それを私費で購入すべきものなのか、
公費で購入すべきものなのかを検討するという段階があると思います。使い回しができるも
のは公費で負担する。例えば、さっき言いましたけど、セット教材はばらして、一部は個人
負担、一部は公費とするとか、いろんなやり方があると思います。９月議会でも、こどもま
んなかアクションプランのスタートに当たって町が行ったアンケートにおいて「何があった
ら幸せか」の質問に、大人も子供も「お金の心配なく生活できる」「お金の心配なく勉強・

スポーツ・習いごとができる」ことが大きく求められているというふうに指摘をいたしまし
た。保護者のみならず、子供がこのような回答が多いというのは本当に心苦しい思いを私は
しています。
学校現場は本当に忙しくて、前年度踏襲主義、前年どおり、例年どおりすればいいんじゃ
ないかというふうに流されてしまうところがあると思います。また、保護者の中にも、負担
が大きいなと感じながらも、学校から求められたら当たり前で負担をする、対応しなければ
子供が困るのではないかと、そうせざるを得ないということがあるのではないですか。教育
委員会が保護者の負担軽減の視点をしっかりと持って、ヒアリングとかアンケートを行って
指導すべきと考えます。数十円、数百円の金額ではないかと思われるかもしれませんが、そ
うであるならば、逆に公費負担に切り替えることも可能ではないかというふうに私は問いた
い。一気にできないにしても、金額的に少額であったとしても、この視点で検討することは
大切であると考えますが、教育長いかがお考えですか。
○議長（光益良洋）
教育長。
○教育長（冨山拓二郎）
ただいまの江藤議員の御発言、大変ありがたく聞いておりましたけれども、これまでも学
校は副教材等の精査はかなり行っておりますので、学校で活用する、特にＩＣＴの活用が進
んでまいりましたので、資料集とか、そういったものはタブレットで見られるようにする、
あるいは、教科書も随分進んでまいりましたので、教科書で十分間に合うような部分もござ
いますから、副教材化の軽減はかなりやってまいりました。今後も、そういった部分ではド
リル等も含めまして精査していくようには考えております。他市町の動向等もまた研究して
まいりたいと思っております。
以上です。
○議長（光益良洋）
９番江藤美代子議員。
○９番（江藤美代子）
教育委員会としても、学校としても努力していただいているということは重々理解をしま
すけれども、さらに今後取組をしていただきたいというふうに思います。
次、基金の運用についてお尋ねをいたします。
何点か基金の活用とか、それから今後のルールなどについて御答弁いただきました。運用
についても午前中の一般質問の中で、効率的で確実でかつ安全な運用に努めますというふう
に御答弁いただいておりますので、そこは省きたいと思いますが、私が気になりますのは、
10年以上金額が変わらない基金というのがございます。鶴寿奨学会基金20,000千円、地域振
興基金35,000千円、最終処分場対策基金40,000千円、中山間ふるさと・水と土保全基金10,000
千円など、これについてはどのような計画をお持ちでしょうか。
○議長（光益良洋）
子ども課長。
○教育委員会事務局子ども課長（才所潤一）
私のほうから、まず、鶴寿奨学会基金について御説明をさせていただきます。
昭和50年に個人の方からの寄付を受けまして設置された基金でございます。昭和51年度か

ら平成21年度まではその基金を活用しまして奨学金給付のほうを行っております。34年間で
244名の給付を行ってきております。ただ、平成22年度に公立高等学校の授業料無償化及び
国・私立高等学校等就学支援金制度が開始されたことに伴いまして給付のほうは廃止が決定
され、その基金の利息につきまして小・中学校の図書の購入を行うということで決定され、
現在も利息によりまして図書の購入を行っているところでございます。
現在は国が進めております高校無償化の所得制限の撤廃の状況や他の自治体の状況等を注
視している状況で、今後の方向性は未定となっておりますが、効果的な基金の運用となるよ
うに研究を進めていきたいと考えております。
以上です。
○議長（光益良洋）
環境課長。
