○建設課長（山口哲生）
私のほうからは、中山間ふるさと・水と土保全基金についてお答えいたします。
この基金につきましては、平成５年12月、広川町中山間ふるさと水と土保全基金条例が制
定され、第４条で、その使途につきまして「中山間地域における土地改良施設の機能を適正
に発揮させるために必要な集落共同活動の強化を図るための調査、研究及び研修に関する事
業に要する経費並びに基金の管理等に要する経費に充てるものとする。」と定められてござ
