いったような事例がございます。
また、市町レベルでの活用につきまして、近隣の自治体に確認しましたところ、活用に苦
慮している状況でございました。
今回、質問議員により御指摘をいただき、目的に沿った有効な活用方法について検討して
まいりたいと考えております。
