福祉課の関係で地域振興基金になっている分でございますが、これにつきましては、今シ
ニアクラブ等の補助でやっておりますけれども、今後それ以外で、あるいは、シニアクラブ
が様々な観点で活動するということでございましたら、この基金を取り崩しながら検討して
