○議長（光益良洋）
９番江藤美代子議員。
○９番（江藤美代子）
今後しっかり検討していただきたいなと思います。
鶴寿奨学会基金でございますけれども、私は本当にこの物価高の中、今こそ再開すべきで
はないかという考えを持っております。確かに御答弁いただきましたように、高校就学支援
金については所得制限を外すとか、私立の高校については金額加算などと言われていますけ
ど、制服代とか教材費、通学費など本当に負担が大きい、私立の高校については入学金とか
施設費なども必要です。
これはネットの記事なんですけど、春日市の50代の方の投稿記事がありました。中３の娘
さんが私立の高校への進学を検討されたそうですけど、授業料が無償になったとしても、施
設維持費、修学旅行の積立金やタブレットなど、それを考えると月70千円前後は必要である。
さらに、塾通いとか今後の大学の学費などを考えた結果、私立は断念したとあります。授業
料の無償化でも進路の選択肢が広がったとは言えないという状況です。
また、広川町在住の方で久留米の市立高校に入学なさった方の様子を聞いてみました。入
学時には、制服で150千円、入学金で145千円など、これだけでほぼ300千円が必要です。さ
らに、教材費として一括で90千円、そして、バス通学代で６か月分ですけど80千円とまと
まったお金が必要だったということでした。これは一部で、これ以外にもまだ必要な出費が
あるのだろうと思います。
鶴寿奨学会基金は奨学金のための基金です。何年もため込んでいたのでは何のための基金
なのかということになります。私は鶴寿奨学会基金とふるさと創生基金を併せて奨学金とし
て活用するということができないかというふうに思ったんですけど、竜光寺公園に全額使う
というふうに先ほど御答弁があったので、この提案は無理かと思いますけれども、本当に奨
学金については今こそ検討すべき課題だというふうに思います。御検討をお願いいたします。
あと最後に、繰り返しになりますけど、町長にお尋ねいたします。
基金は全体として増加傾向です。いつまでも様子を見ているだけでは生きたお金にはなり
ません。生きた使い方をすべきと考えます。基金が増え続けるということは、厳しいですけ
ど、税の取り過ぎ、住民サービスの低下というふうにも言えるのではないでしょうか。物価
高の中、住民の暮らしは本当に厳しい状況です。町の財政も厳しいんだというふうにさっき
からずっと話があっていますけれども、今こそ計画的に効率的な活用をして、住民サービス
の向上、住民福祉の向上を図るべきと私は考えます。町長の御意見をお伺いいたします。
○議長（光益良洋）
町長。

○町長（氷室健太郎）
先ほど冒頭の私からの答弁にありましたように、これから広川町では上広川小学校、下広
川小学校、中学校の校舎もそうですし、長寿命化が待っています。産業展示会館、古墳資料
館、様々な施設の長寿命化に備える必要もありますし、これからの国県道バイパスの整備等
に伴っても、例えば、地元住民の方々から、降った雨水の流れが変わるんじゃないかという
ことで、その流末の処理なども要望が出され、そういうときには当然ですけれども、普通河
川であれば広川町が水路の整備などを行わなければならないし、アクセス道路についても町
道の整備を行わなければならないといったようなインフラ整備に関してもこれから増加して
いくことが──河川改修に関しても同じなんですよね。
そういったことを考えますと、軽々に基金が積み上がっているというふうには考えており
ませんで、これからの財政支出に備えているというような意識で私はおります。
ただ一方で、今、議員が御指摘いただいたような、まだ使う余地があるような基金がある
という視点については職員とも共有して、今後、活用ができる範囲内で活用していきたいと
いうふうに思っておりますので、よろしくお願いいたします。
以上です。
○議長（光益良洋）
９番江藤美代子議員。
○９番（江藤美代子）
