午後２時６分 休憩
午後２時15分 再開
○議長（光益良洋）
休憩前に引き続き会議を開きます。
次に、11番池尻浩一議員の登壇を求めます。
○11番（池尻浩一）
11番議員、池尻です。通告どおり、事項順に質問させていただきます。
まず、役場の職員数についてですが、これについて、今回の一般質問につきましては、竹
下議員、藤島議員と重なるところがありますので、意識して要点だけを質問させていただき
ます。
町では、役場の業務の増加に対応するため、また、住民サービスの充実を含めた中で、職
員定数増を行いました。社会人枠を中心とした中途採用、新年度を経過し、その状況はどの
ようか。
先日の全協でも資料がありましたが、現在、一般職員118人、会計年度職員150人というこ

とを一応伺っております。さきの質問の中で、町長からも相変わらず定年前の退職、しかも、
40歳前の退職者も多いと耳にしております。機構改革も行われる中、町が取り組むべき事業、
また、住民の要望に対する取組の多さは本当に目に見えて増える一方です。以前、小学校教
職員が業務負担増などから教職員数が不足する状況が増えていました。働き方改革や少子化
からの学校の統廃合による減少によりカバーできていますが、これに似た状況と感覚を役場
にも感じる状況です。事業に対する適正数が確保できている状況か、伺いたいと思います。
また、職員一人一人のスキルアップがなされれば、数に頼らないでできる状況も生まれて
くると説明いただいたこともありました。管理職の負担、育成状況はできているか。県全体
のデータでは、広川町職員、これは一般職のみですが、３分の１以上が経験10年未満、しか
も、30代前半となっており、これはよく言えば若い職員の役場となっていると考えてもよろ
しいのでしょうが、周辺市町との業務報酬比較などはなされているか。また、その内容次第
で他地区への転職というのも職員不足、退職増という要因の一つになっていないか、伺いた
いと思います。
次に、町の子ども・子育てについてです。
町の政策の目玉とも言えるこどもまんなか施策、こどもまんなかプロジェクトですが、先
ほどの町長の施政方針の中でもかなり内容のいい、必要性のあることをうたっていただきま
したので、もうかなりの質問内容は削られてくると思います。
人材育成を第１の目的とした施策であり、個人的にも人口減少対策として重要な施策でも
あると感じております。将来を見越し、広川サイクルとして広川町に戻ってくる人材の環境
づくりにおいて、現状の子供たちへ生きる力、地域全体の取組、またメディア活用、特に
「ふるさとWish」などを見ますと、物おじせず自信を持ってコメントし、堂々とした取組姿
勢を見るに当たって、まだ始まって短い期間ではありますが、既に一定の成果が現れている
のではないかと自分自身確信できるものです。今後も、町としてしっかり取り組んでいただ
きたい施策だと思っております。
そのような中、国の実態調査の中には、40歳未満の方へのアンケートでは、過半数で子供
はつくりたくない、育てたくないといった状況であり、課題でもある出産不安、育児不安、
教育費不安に手を尽くしていても、状況はなかなか改善しないところでもあります。
1999年の1.57ショックから35年、エンゼルプラン、次世代育成対策、子育て応援、新エン
ゼルプラン、待機児童ゼロ対策など、国も地域も状況や要望に応じて取り組んできました。
令和７年のこども家庭庁の対策予算は７兆円を超え、前年比から比べれば１兆円増となっ
ております。今度の高市政権において、先ほどの静かな有事として国の活力をむしばむ、本
当に取り組んでいくべき大事な状況であるとともに、成長戦略17の戦略として、まずは経済
の立て直しに取り組む中、じゃ、その財源はどこから、どこの事業が削られていくのかなど
の懸念も出てきています。
子育て関連政策は、出産費用の自己負担の支援、働く家庭への家事支援は明言されており
ますが、経済立て直しに尽力されるイメージを強く感じます。国の政策が変われば交付金に
も少なからず影響はあるのではないかという不安もある上、もちろん町としては急な変更は
考えられないとする中、広川町では、令和８年度はこども議会の開催、リーダー育成事業の
ブラッシュアップなどが計画されており、今後も子育て世帯の情報発信強化、こども公共交
通機関、こども基本条例の立ち上げなどが予定されております。周辺状況、経済状況に合わ

せた追加や変更、また、評価項目として毎年度の評価を行うとされている評価状況を伺いた
いと思います。
何よりこのはっきりとした成果は、町長の方針でもあったとおり、10年後、あるいは、そ
れ以上かかるかもしれない内容でもあります。これまでの成果や今後の見通し、また、見直
し等があれば伺いたいと思います。よろしくお願いします。
○議長（光益良洋）
町長。
○町長（氷室健太郎）
池尻議員の御質問にお答えをいたします。
初めに、職員採用の取組と職員数についてお答えをいたします。
令和６年12月議会において職員定数増の条例改正を御承認いただきましたので、直ちに準
備を進め、令和７年度の開始と同時に採用試験を実施するなど、今年度は計３回の採用試験
を行いました。
前年度末に改定した人材育成基本方針に基づき、主に社会人経験者を対象とした試験を２
回実施し、その際、従来の筆記試験に代えて、社会人としての実績や課題解決能力を評価す
る書類審査や面接を重視するなど、新たな手法も導入したところです。
定数条例における職員数は、令和７年４月時点では118.4人でありましたが、年度途中で
４人を採用し、さらに新規11人を採用する予定です。ここから退職予定者10.8人を差し引く
と、令和８年度の定数条例の職員数は122.6人となる見込みです。
なお、この職員数に小数点以下の端数が生じておりますのは、暫定再任用短時間勤務職員
については勤務時間に応じたカウントを行っているためです。例えば、週４日勤務の職員に
ついては、１人ではなく0.8人として計算をしております。
次に、人材育成やスキルアップに向けた取組と、それに伴う職員の負担についてお答えを
いたします。
公務を取り巻く環境は年々複雑化し、職員一人一人が担う業務量も増加傾向にあります。
こうした状況への対応として、職員の能力や生産性の向上につなげていくため、業務多忙な
中ではありますが、研修の機会を増やし、人材育成に努めているところです。
一方で、日々の業務に追われる中で、研修に参加する時間を確保すること自体が職員の負
担となっている現状も認識をしております。だからこそ、職員の能力や生産性の向上を通じ
て日々の業務や仕事のやり方を見直していく、業務の効率化を図りながらもその質を高めて
いく、その結果、職員の業務時間には余裕が生じ、その時間を活用して研修等に参加するこ
とで、さらに能力が向上するという好循環を生み出すことが重要であります。
次年度予算案にも計上しておりますが、こうした好循環につなげていくため、業務プロセ
スを根本的に再設計し、最適化すること、いわゆるＢＰＲを強力に推進してまいります。こ
うした取組を通じて、職員の日々の業務に係る負担感を解消し、学びの機会やじっくりと政
策について考える時間を確保できる環境を整備してまいります。
いずれにしても、今後も職員との対話を重ね、中長期的な視点から必要な取組を行ってま
いります。
最後に、周辺市町との業務内容や報酬の差についてお答えをいたします。
地方自治体は、その人口規模や都市機能に応じて異なる行政権限を持っております。町村

は基礎的な行政サービスを担うこととされており、独自事業を除けば、基本的な業務内容は
ほぼ同じであると認識しております。人口規模が類似する他の町と比較した場合、業務内容
に大きな差異はないと思われますが、人口規模が大きい周辺の市と比較しますと、本町にお
いては、１つの課や職員一人一人が担う業務の範囲は相当広くならざるを得ないと考えてお
ります。
給料等の差につきましては、福岡県が公表している令和６年地方公務員給与実態調査にお
いて、本町の一般行政職の平均給料月額は289,600円であり、県内60市町村のうち、少ない
ほうから３番目という状況であります。業務への意欲を持ち、能力向上に励み、成果につな
げていく職員が正当に評価されるよう、人事評価の改善や人材育成の在り方については引き
続き検討をしてまいります。
次に、子ども・子育てについてお答えをいたします。
本町が推進するこどもまんなかプロジェクトは、単なる子育て支援策にとどまらず、広川
町で育った子供たちが郷土に愛着を持ち、親世代となって再び広川町で次世代を育てるとい
う広川サイクルの確立を目指しております。この循環を生み出すためには、子供を主権者と
して捉え、自分の行動で町を変えられるという自己効力感を育成することが不可欠でありま
す。
令和６年度から４年間のアクションプラン第１ステージでは「こどもが大切にされている
と実感できるまち」を目指し、各種事業に取り組んでおります。町長への意見箱に加え、
「町長と話そう」や「町長と給食を食べよう」において、子供たちが直接町長へ声を届けら
れる環境を整備したことにより、役場の開放や藤田運動公園へのサッカーゴールの設置など、
町長との対話を通じて自分の意見が町を動かすと実感できる機会を創出しております。
今後の展望としては大きく３つほどあります。
まず１つ目ですが、引き続き子供の居場所づくりを積極的に進めてまいります。現在も一
部の行政区において取り組んでいただいておりますが、公民館の開放の取組も地域の皆様と
御相談をさせていただきながら進めてまいります。加えて、今年11月には竜光寺公園がリ
ニューアルオープンする予定です。これは町内の子ども・子育て世代を含め、町民にとって
の憩いの場であり、人と人とが関わる交流の場、居場所につなげていきたいと考えておりま
す。
２つ目ですが、地域の資源を最大限に活用してまいります。昨年11月より始めたこどもま
んなか応援店舗の取組により、地域全体で子供を支えるプラットフォームが強固に形成され
始めております。この機運をさらに推し進めるべく、例えば、町内の企業や団体と連携する
ことで子供の新たな居場所や交流の機会づくりにつなげていくことを検討しております。
さらに、３つ目です。令和８年度からは、これまでの成果をデジタルの力でつなげ、広川
サイクルをさらに加速させる戦略的投資を行います。具体的には、公式LINEの機能拡充など
を通じたデジタルインフラを整備することにより、町民の利便性の向上を図ります。私も子
育て世代ですが、仕事をしながら自分自身で子育て情報を集めてくることはとても大変であ
ります。例えば、デジタルシステムを活用して子育て情報をプッシュ型で配信する、その情
報を基に、子育て世代の方がサービスを受ける予約等をオンラインで行えるようになる、こ
うしたことは確実に町民の利便性の向上につながります。
こどもまんなかの取組は、子供たちの声を原動力とし、全町民がその才能と可能性を輝か

せることのできる社会の実現に向けた取組であります。引き続き地域や企業、団体等と連携
しながら全庁一丸となって取り組んでまいりますので、皆様方の御理解と御協力をお願い申
し上げます。
以上でございます。
○議長（光益良洋）
11番池尻浩一議員。
○11番（池尻浩一）
職員数の件ですが、メディア等で出てくるに当たって、親がさせたい職業というのは５年
連続断トツ１位で公務員だそうです。町の各職員と、えっという声が出てくるときもありま
すけれども、今の状況とか客観的に見たらそうなんであろうというのが実態であります。
離職者に関しては、全国的にいろんな職場の中で増えていることであり、離職しやすい環
境ができているというのが本当は問題かとも正直思っております。これは各人の辞められる
方の生活環境とか考えの中でのことですから、職場環境改善だけに取り組んでもなかなか難
しいのかなというところはありますけれども、当然職場環境というのは変えていただいた上
で、取り組んでいただいた上での内容になるかと思います。
先ほど町長の答弁の中には、来年度122.6人の見込みとされていますけれども、当然現在
の事業整理も進められている中で、事業評価も併せた中でいろいろ取り組んでいきたいとい
うのも以前の答弁の中にもありました。この定数が現状満たされているかということと、町
長としては現定数で十分か、あるいはやっぱり事業に対してもっと増やしたいのか、何より
