○議長（光益良洋）
町長。
○町長（氷室健太郎）
職員につきましては定数を増やしていただいたんですけれども、採用活動も一生懸命やっ
ているんですけれども、なかなか増えていないという現状で、私としてはまだ足りていない
というのが実感としてございます。
