を検討しなければならない状況であるという認識でございます。
以上でございます。
○議長（光益良洋）
11番池尻浩一議員。
○11番（池尻浩一）
もちろん、当然町としても単純に軽い気持ちで職員を増やしたいとか、そういう考えでは
