うのも厳しい話かなとも十分理解しております。
事業内容に関しては、結局、周辺市町村と基本的には変わりないだろうと。田舎に行った

り離島、山間部に行くと、逆に公務員数だけが多くてというのも本当によく聞く話でもあり
