○議長（光益良洋）
総務課長。
○総務課長（鹿田 健）
先ほど町長のほうから申し上げました給与実態調査報告によります給与の比較でございま
すが、その基となります数字というのは、職員の単純の月給の比較でございます。先ほど池
尻議員の質問の中にもありましたとおり、経験年数が少ない職員が多いということでありま
したけど、その表とは別に、職員の年齢構成別の内訳を書いたものがございまして、そちら
のほうを町村の中で一番高い町のほうと比較をいたしました。そうしたところ、39歳までの
職員が一番高いところが約40％で、私どもの町につきましては52％程度と、若い職員が多い
ということでございます。
それからもう一つ、これは60歳以上の職員についての区分もあるんですが、そこの比較を
してみますと、広川町のほうは再任用職員の浸透が早かったので、その職員が多いというこ
とがあります。再任用職員は給与の額が下がってきますので、若い職員が多い、それから、
再任用職員が多いという理由でもちまして、単純な平均が低くなっているという分析をした
ところでございます。
以上です。
