○議長（光益良洋）
子ども課長。
○教育委員会事務局子ども課長（才所潤一）
こどもまんなかプロジェクトのほうが少子化対策と連携しているのかというところでござ
いますが、こどもまんなかプロジェクトにつきましては、地方創生総合戦略や広川町人口ビ
ジョンと連携をしております。また、こどもまんなかアクションプランの４つの柱の一つ、
「こどもへの愛着形成を支援する」の分野では、子どもの医療費の無償化や出産・子育て応
援給付金の町単独上乗せ分でありましたり、おむつの定期便など、少子化対策も含まれてい
る部分がございます。
ただ、こどもまんなかプロジェクトの主な目的としましては、未来の地域社会の担い手を
育成することとしており、未来の担い手である子供にしっかりと投資を行い、いろんな主体
的な経験を積むことで、町外に出たとしても、ライフステージの転機で広川町に戻り、また
次の世代を育てる好循環、いわゆる広川サイクルを回し続けることを目指しております。
こどもまんなかプロジェクトは、目の前の少子化対策というよりも、人材育成を強化する
ことで、人口減少社会であっても地域が活力を失わない対策の意味合いのほうが強い取組で
はございますが、この取組を町内外に発信していくことで広川町で子育てをしたいと思って
もらえれば少子化対策に寄与すると考えております。
以上でございます。
○議長（光益良洋）
11番池尻浩一議員。
○11番（池尻浩一）
１つの取組が広い範囲に及ぶ、影響できることは本当にいいことだと思っていますので、
それを含めた中で、自分たちが取り組んでいる、町のお世話させていただいている中で、ま
た協力連携ができればと思っております。
先ほどの答弁の中にも、居場所づくりとか公民館活用というのもありましたけれども、こ
れは行政職員を含む育成する側のスキルアップに関してはどう考えているか。居場所づくり
には、公民館活用として地域役員等の協力も当然必要となってきますけれども、このこども
まんなかプロジェクト、また、チームを組んでいろんな課が連携しながらやっているという
ことも以前の答弁にもありましたけれども、育成する側のいろんなスキルアップというのも
並行してできているか、伺っていいですか。
○議長（光益良洋）
子ども課長。

○教育委員会事務局子ども課長（才所潤一）
このこどもまんなかプロジェクトは、様々なほとんどの課の職員が携わっているところで
ございます。各種関連事業につきましては、それぞれの課、また、複数の課で一緒に取組を
進めておりまして、その事業を進めていく中で、対外的な部分での地域とのつながり、企業、
事業所とのつながりの部分でございましたり、庁内の連携の部分で事業を進めていく上での
事業の組立てでありましたり、家庭におけるプロセス、またデジタル化、ＩＣＴ化等を利用
した事業を進めるところの部分におきまして、そういった職員のスキルアップにもつながっ
ていると考えております。
以上です。
○議長（光益良洋）
11番池尻浩一議員。
○11番（池尻浩一）
いろんな町長の方針とか答弁の中で、職員同士の意識共有とか、自分たちもそうですね、
職員だけでは動けませんし、地域の意識協力、意識改善、当然自分たちもその中でと思って
おります。
これはちょっと細かい質問にもなりますけれども、高齢者の方から、子供ばかりというよ
うなことも町長の耳にも届いているかと思っております。高齢者まんなかプロジェクトもし
てくれということも言われていますけれども、町の方向性と自分たちもどう説明するかとい
うのは当然同じ内容でなければいけないと思っています。個人的には、高齢者支援は本当に
長らく取り組んでまいりました。これは継続中であり、町の予算を一々削ってとか事業内容
を削ってということは、こどもまんなかプロジェクト、アクションプランを進めるに当たっ
て、それをおろそかにしているとか放置しているということは一切ありません。逆に言えば、
ある一定行き着いている。問題は、自分たちのみで運営、取り組むことに無理を感じている
のが問題じゃないですか、今うまく自分たちで継続できていない、運営ができていないとい
うところのほうが問題じゃないですかと。極端に言うなら、準備、片づけまでとは言わない
ですけれども、マンネリ化してきた新しい企画とか会計等についても、役場の方がしてくだ
さいというような形のところも、これは社協がいきいき体操やら貯筋体操とかをしているか
ら、また別の話かもしれないですけれども、そういったほうが問題じゃないですかと。基本
的にはもうできていますので、これを新しくさらに積み上げていくか、広げていくかは、
やっぱり自分たちでするべきじゃないんですかということも高齢者の方にも話をしています。
今何より子供育成、出生率を上げておかないと、自分たち、その子たちまで影響があるの
じゃないですかと。これが十分な理解、こちら側としては周知が足りないのではないかと考
えております。
ここに関しては、町長のこどもまんなかプロジェクトに対する発信力が、アピールが強過
ぎて、日陰になってしまった部分が余計に重く感じるのではないかと思いますけれども、そ
ういうことも含めて、高齢者に対する説明とか取組というのをきちんと共有させていただき
たいとは思いますが、その辺どうでしょうか。
○議長（光益良洋）
町長。
○町長（氷室健太郎）

ありがとうございます。御指摘をいただきましたように、高齢者の方々から厳しい御意見
をいただくことはありますので、私はそのたびに、もちろん高齢者の方をおろそかにしてい
ることはありませんと、高齢者施策に関してもきちんとやっていますし、何回も言いますけ
れども、私も今の公民館でやられているような高齢者のいきいきサロンとか、ボランティア
センターもそうですけど、そういった取組を職員時代に担当して、高齢者の方々が住み慣れ
た地域でいつまでも暮らし続けられる、そういう事業をやってきましたので、その気持ちは
一切変わりはないという点をまずお伝えをしております。
もう一つが、こどもまんなかというのは、単に子供たちのため、あるいは子供を持つ世帯
のためだけにやっているんじゃないんですと、全住民に影響が及ぶ施策なんですと。具体的
には、施政方針の中でも書いておりましたけれども、10年後、20年後、誰かの支えを必要と
する、人間は誰でも衰えるから、介護とか医療の現場で誰かの支えを必要とするときは来る
んですけど、そのとき、じゃ、10年後、20年後、医療や介護の現場で働いているのは誰かと
いうと、今、目の前にいる子供たちなんですよと。今、目の前にいる子供たちがしっかりこ
の地域に残って地域社会の未来の担い手になってくれなければ、そのとき本当の意味で高齢
者が端っこに置かれるような社会になってしまいますよと。それを防ぐために、高齢者を真
ん中に置くためにこどもまんなかに取り組んで、みんな真ん中の社会をつくるんだというの
が常に私が説明していることでありますので、ぜひ皆様方にも御協力をいただいて、住民の
皆様方に御理解をいただきますように御協力をお願いいたします。ありがとうございます。
○議長（光益良洋）
11番池尻浩一議員。
○11番（池尻浩一）
まさにそういうことですね。方針の中に、要するに、特定世代の問題ではありませんとい
うことを町長がおっしゃっていました。その中で、やはり住民側の意識改善がもう少しでき
ていないんではないかなと。極端に言うなら、全体的な危機意識の少なさというのが本当に
問題であり、町長が今さっき答えられた部分を、本当に広い世代のところに正しい周知をも
う少し行っていかなければと思っております。特に若い世代、20代、30代の方にそういった
特定世代の問題ではないですよということをはっきり教えていかなければ、これがぐっと進
むことはないんじゃないかなという感覚さえあります。
先日、人口減のところで、東京都の取組と周辺の神奈川、埼玉、千葉の取組の差で、東京
の出生数が非常に増えたと報道されました。これは先を考えた正しい取組の周知や、特にお
金やレジャー、物欲や収入欲のみで満たされてしまう、そういうところに意識を持っていっ
てしまうというのは、先を考えた中で少々足りないのではないかなと。今後も広川町の魅力
を正しく伝えて、町の取組が十二分スピーディーに、内容よく進むことを期待しまして、質
問を終わらせていただきます。
以上です。
○議長（光益良洋）
次に、８番栗原福裕議員の登壇を求めます。
○８番（栗原福裕）
８番栗原です。一般質問の最後を務めさせていただきます。もうしばらく時間を頂戴いた
します。

それでは、通告書に従い、質問をさせていただきます。
八女消防本部広川消防署については昭和46年12月に完成し、八女消防署広川分署として運
用を開始されております。その後、令和２年４月１日より消防署へ昇格し、現在に至ってい
るところでございます。
建築面積は１・２階を合わせまして397.96平米、開設時の署員数は８名でスタートをして
おります。片班４名体制で業務が開始されているところでございます。
その後、町の人口増加や企業進出により業務量が増加し、署員数は平成４年４月より15名
体制、平成20年４月より17名体制、平成26年４月より19名体制、令和４年４月より21名体制
で今業務が行われているところでございます。開設時からしますと、署員数は２倍以上に
なっているところです。署員数の増加により、仮眠室は今、会議室を利用してある状況です。
この間ちょっと伺って見せていただきましたが、３分の２ほどは仮眠室で利用されている状
況です。町長も御存じだと思います。私は今の消防署の状況では消防業務にも支障が出るも
のではないかと危惧しているところでございます。この状況は町も十分承知してあると思っ
ております。
現在、八女消防本部の庁舎建設事業が進んでいるところでございますが、その後は広川消
防署の建て替え事業に着手する必要があると私は考えております。
そこで、町として、現時点で建て替え時期をどう考えてあるのか、お伺いします。
次に、建築場所についてもどう考えてあるのかをお伺いします。
私は訓練等ができる敷地面積の確保が必要だと考えておるところです。また、今のように
役場と消防署が近接の場所がいいのではないかということで考えております。それは、災害
時におきまして、消防署との連携が必要です。災害時の対応、連携がすぐに図れるからとい
うことで考えておりますので、それを踏まえて町長の答弁をお伺いします。
あとは個別に幾つか質問をさせていただきます。よろしくお願いします。
○議長（光益良洋）
町長。
○町長（氷室健太郎）
栗原議員の御質問にお答えをいたします。
現在の広川消防署の庁舎は、昭和46年12月に八女消防署広川分署として竣工し以来55年と
いう長い年月が経過をしております。これまで長寿命化のための改修とメンテナンスを施し
ながら使用されておりますが、施設の老朽化は確実に進行をしております。
さらに、令和２年４月に分署から消防署へ昇格したこともあり、先ほど御指摘をいただき
ましたように、署員が増加したことで手狭になっていると聞いておりますし、女性隊員が勤
務するためのスペースも確保できていないのが現状であるというふうな認識も持っておりま
す。
このような状況から、町としても今後建て替えが必要になるという認識は持っております。
ただ、現時点では具体的な建設時期や場所、規模までの協議までは行っておりません。議員
も御承知のとおり、現在、八女消防本部八女消防署の新庁舎建設が進められておりますので、
まずはそちらの建設を最優先で進められておるものと認識をしております。ただ、複雑・多
様化する近年の災害への対応力を高め、町民の皆様の安全・安心を確保するためにも、繰り
返しになりますが、そう遠くない時期に新たな広川消防署が必要になると認識をしておりま

す。
これらを踏まえ、今後、八女地区消防組合と協議を開始する場合には、様々な事情を考慮
し、最適な場所と施設内容を検討してまいりたいと考えております。
消防防災機能の充実は地域の安全・安心の要ですので、今後も関係機関との連携をさらに
密にし、住民の安全・安心の確保に全力を尽くしてまいります。
以上でございます。
