企画課長。

○企画課長（井上新五）
一部事務組合であります八女消防本部の各庁舎の建て替えにつきましては、改修等の計画
について町が定める各計画書内の位置づけは行っていないという状況です。
理由としましては、町は八女地区消防組合、一部組合の構成員ではございますが、施設の
建て替え計画を策定する主体はあくまでも組合であることや、現段階では公的な協議に至っ
ていないことから、広川町だけの意向では計画を進めることができないというふうに思って
おります。関係市町間での合意形成が必要と考えておりますので、計画の位置づけというの
は町の部分では詳細に行っていないという状況です。
以上です。
○議長（光益良洋）
８番栗原福裕議員。
○８番（栗原福裕）
計画にも位置づけていないということです。一部事務組合であるということは、私もその
議員ですので、分かっております。ですが、場所については町で確保するというようなこと
