○議長（光益良洋）
企画課長。
○企画課長（井上新五）
まず、建設面積につきましても公式な協議には至っておりませんので、申し上げることは
できませんが、庁舎の建て替え等に関する考え方、こちらについてちょっと説明をさせてい
ただきます。
まず、女性消防団員（72ページで訂正）の配置、こちらが八女消防本部のほうでも実施さ
れておりますが、現在３名の女性消防職員が在職されております。八女消防本部では、総務
省消防庁の方針目標に基づきまして、この女性消防職員の配置を令和10年度までに５名とす
る方針と定められております。全国的に女性消防職員の配置、女性活躍推進法に基づき計画
をされているということとなります。
しかし、八女管内の庁舎を見てみますと、一部の署で改修が進み、女性職員の施設の整備、
こちらが終わり、令和８年度からが本格配備されるということとなっております。ただ、広
川署を含む多くの分署においては、建物の狭隘により改修ができない状況となっているとお
聞きしております。また、広川署では、署員の増員によって事務所や仮眠室もままならない
状況となっており、迅速な消防活動や署員の待機環境において支障を来しているという状況
とお聞きをしております。このような状況から、車両数や隊員数、また女性職員の配置環境
整備などを考慮した場合、現在の建物面積、延べ面積であります約400平方メートルでは狭
い状況ではないかと考えております。
現段階ではどの程度の規模と申し上げることはできませんが、車両数や隊員数、または女
性配置の環境整備等を考慮すると、現在の建物の床面積以上は必要ではないかというふうに
考えております。

以上です。
