すみません、先ほどの答弁の中で女性消防職員のことを団員と言ってしまいました。職員
の間違いです。
まず、建築場所につきましても、こちらも正式な公的な協議には至っておりませんが、現
段階での考え方、消防管轄の部署としての考え方について説明をさせていただきます。
消防署の建設に当たりましては、大規模災害時における防災拠点としての機能を確実に維
持する必要があると現在認識をしております。
まず、必要な敷地面積についてですが、現在の職員数21名及び消防車両が４台という体制
を基に災害時の非常招集や訓練スペース、これを考慮しますと、現在の敷地以上の面積が必
要であるというふうには思っております。その理由としましては、現在、広川消防署の敷地
面積については527平方メートルという敷地になっておりますが、庁舎内の建物だけで敷地
の大部分を占めるのではないかというふうに考えております。加えまして、敷地内の基本的
な消防訓練や車両の安全な運行や整備を行うための活動地につきましては、やはり十分な広
さが確保する必要があるというふうに考えております。
以上です。
○議長（光益良洋）
８番栗原福裕議員。
○８番（栗原福裕）
ありがとうございました。面積については十分な訓練等もできるような確保が私も必要と
考えておりますので、ぜひそれを踏まえて今後検討を行っていただきたいと思います。
次に、場所でございますが、今現在、消防署は役場の東にあるわけです。災害が発生した
場合にもすぐに連携が取れる位置でございます。私は先ほども申しましたが、できる限り役
場に近い場所がよいと考えておりますが、現在の消防署は災害の浸水区域に入っているよう
でございます。それらを含めてどう考えてあるのか、お伺いいたします。
○議長（光益良洋）
企画課長。
○企画課長（井上新五）

議員御指摘のとおり、現在の消防署については役場のすぐ東側に位置しておりまして、平
時、有事を問わず行政と消防が顔の見える関係で密に連携を取れるという点において、非常
に優れた立地であるというふうに認識しております。
平成24年の九州北部豪雨や平成28年の熊本地震、また令和５年の豪雨など、大規模災害時
には役場に災害対策本部が設置されます。消防署と役場が地理的に近いことは、情報共有や
迅速な意思決定を行う上で大変有利であり、重要な要素であると認識をしております。可能
な限り役場に近い場所がよいという栗原議員の考えには基本的に同感でございます。
しかしながら、懸念されているとおり、現在の敷地は浸水想定区域に含まれております。
近年の気象状況は激甚化の一途をたどっており、万が一、大規模水害が発生したときに、住
民の命を救うべき消防署自体が水につかり、ポンプ車や救急車両、こういったものが出動で
きなくなる、あるいは通信機能が麻痺してしまうといった事態は絶対に避けなければならな
いというふうに思っております。
したがいまして、今後の建て替え等の計画においては、やはり安全性の絶対確保、あと、
機能的な連携の維持等を両立させる方針に基づいて、場所の選定、こういったものを決定し
ていきたいというふうに思っております。
以上でございます。
○議長（光益良洋）
８番栗原福裕議員。
○８番（栗原福裕）
ぜひとも役場に近く、アクセスのよい場所を選定していただきたいと考えているところで
ございます。
次でございますが、本町で確保する必要があるということで先ほど申し上げましたが、早
い段階での検討、協議を行っていただきたいと考えております。どういうふうに考えてある
のか、お伺いいたします。
○議長（光益良洋）
企画課長。
○企画課長（井上新五）
広川消防署を含めまして、この八女管内の分署の建て替え計画についてはまだございませ
んので、幹事会なりで八女消防本部のほうと協議はさせていただきたいなというふうに考え
ております。
ただ、現段階では、八女本庁舎のほうの建築が進み始めた段階となっておりますので、内
容としましては、この本庁舎の建築が終了した後に迅速的に開始できるような形で八女消防
本部のほうとの協議、こちらのほうはさせていただきたいと考えております。
以上です。
○議長（光益良洋）
８番栗原福裕議員。
○８番（栗原福裕）
八女本部の本庁舎が終わった後に協議、検討を発したいということでございますが、９年
度末には本部庁舎が完成するわけですね。あと１年先ぐらいになるわけです。私はそれから
では遅いと考えております。今すぐにでも、やはり土地だけでも先に進めていくべきだと考

えておりまして、再度そこの辺りはどう考えてあるのか、お伺いいたします。
○議長（光益良洋）
企画課長。
○企画課長（井上新五）
議員御指摘のとおり、土地の選定にはやはり時間を要します。消防組合の事業採択を待つ
間に町として適地をリストアップし、交渉のめどをつけておくことも必要ではないかと思っ
ております。
この八女消防本部の庁舎、こちらを待つというものではなくて、各自治体にある消防庁舎
の用地確保については、そこの自治体のほうで確保するという形になっておりますので、用
地選定の準備、こちらは広川町として先行して進めることが可能となりますので、対応をし
てまいりたいと思っております。
以上です。
○議長（光益良洋）
８番栗原福裕議員。
○８番（栗原福裕）
以上で私の一般質問を終わりますが、ぜひとも消防本部とか関係機関と相談されて、場所
の選定、敷地の確保だけは先行して進めていっていただきたいと思います。私も一部事務組
合の議員として努力してまいりますので、ここら辺りの連携を図りながら、取り組んでいき
たいと思います。
この八女消防本部広川消防署の建築は、町の防火、防災の核となる施設であります。町の
安心・安全なまちづくりにも大きく影響する施設でございますので、推進していただくこと
をお願いし、私の一般質問を終わらせていただきます。どうもありがとうございました。
○議長（光益良洋）
以上で一般質問を終わります。
以上をもって本日の日程は全部終了いたしました。
本日はこれにて散会いたします。
午後３時12分 散会

