○議長（光益良洋）
日程第２．議案第５号 広川町保健・福祉センターの設置、管理及び運営に関する条例の
一部改正についてを議題といたします。
提案者の提案理由並びに内容説明を求めます。町長。
○町長（氷室健太郎）
議案書４ページをお願いいたします。
議案第５号 広川町保健・福祉センターの設置、管理及び運営に関する条例の一部改正に
ついて御説明申し上げます。
提案理由といたしましては、本条例の指定管理に係る管理において、より適正な管理を行
うため、本条例を一部改正するものでございます。
詳細につきましては福祉課長が御説明いたしますので、御審議の上、御決定賜りますよう
お願い申し上げます。
○議長（光益良洋）
福祉課長。
○福祉課長（小松朋雄）
それでは、議案第５号 広川町保健・福祉センターの設置、管理及び運営に関する条例の
一部改正について説明いたします。
６ページ、新旧対照表にて説明いたします。
第13条第１項中、「以下「法」という。」を削りまして、同条第２項中「第１項」を「前
項」に、「第12条」を「前条」に改め、第15条中、「５年間」を「５年以内」に改め、この

条例は公布の日から施行します。
以上で説明を終わります。よろしくお願いいたします。
○議長（光益良洋）
説明が終わりましたので、質疑を行います。
質疑のある方の挙手を願います。５番竹下英治議員。
○５番（竹下英治）
説明を受けていないということで、改めて今議会で。
実際、このトリガー、こういう変更になる背景をどういうふうに捉えておられたのかとい
うのと、実態として、役場の動きにどう影響するのかというのをちょっとお伺いしたいと思
います。
○議長（光益良洋）
福祉課長。
○福祉課長（小松朋雄）
実は平成18年から指定管理制度を本格導入しまして、必要に応じて改善を図ることで各施
設の設置目的をより効果的かつ効率的に達成し、住民福祉の一層の向上に取り組んできたと
ころであります。しかしながら、公共サービスに対する町民のニーズは多様化並びに高度化
する一方で、老朽化が進む公共施設の更新問題により財政状況が一段と厳しさを増していく
中で、近年、ＰＦＩ、ＰＦＳ手法などの新たな管理運営手法により取組が進んでおります。
行政と民間事業者の下、改めて町の制度運用に関する基本的な考えを検討し、さらなる町民
サービスの向上を図るためでもあります。
また、近年は最低賃金の上昇並びに物価高騰が続いておりまして、指定管理の施設の管理
運営に大きな影響を及ぼしている状況が背景にございます。
ですから、このようなことを踏まえまして、指定管理者の健全経営を通じた施設の適正な
管理運営や業務の適正な履行の確保を目的として検証していこうと思っております。ただ、
行政運営に関しまして、何ら支障はございません。
以上です。
○議長（光益良洋）
５番竹下英治議員。
○５番（竹下英治）
すみません、行政運営に支障はないと思いますけど、何がよく変わるんですか。現実的な
動きですよ。今の御説明は大体そんな話ですよね。ペイ・フォー・サクセスについては前か
らそうあるべきだと申し上げておったと思うんですけれども、動きは何がよくなるんですか。
具体的にいいですよ、簡単で。
○議長（光益良洋）
福祉課長。
○福祉課長（小松朋雄）
簡単に言いますと、しっかりと行政と指定管理者との間で協議をしまして、さらなる維持
管理の向上に向けていきたいと考えております。
○議長（光益良洋）
８番栗原福裕議員。

○８番（栗原福裕）
関連なんですが、この第15条、今までは５年間と明確に定めてありました。どういう関係
で５年以内ということに変えられたのか、お伺いします。
○議長（光益良洋）
福祉課長。
○福祉課長（小松朋雄）
実は５年と言いますと、先ほどの物価高騰、賃金の上昇というのも、５年間の債務負担行
