○町長（氷室健太郎）
議案書７ページをお願いいたします。
議案第６号 広川町行政手続条例の一部改正についてを御説明申し上げます。
提案理由といたしましては、令和５年６月16日法律第63号により行政手続法が改正され、
不利益処分を行う際の所在不明者への通知方法が見直されたことに伴い、本条例を一部改正
するものでございます。
詳細につきましては総務課長が御説明いたしますので、御審議の上、御決定賜りますよう

