総務課長。
○総務課長（鹿田 健）
それでは、議案第６号の内容について御説明をいたします。
議案書のほうは10ページ、11ページの新旧対照表のほうで説明をさせていただきます。
町長が提案理由で申し上げたとおり、令和５年の行政手続法の改正は、いわゆるアナログ
規制の見直しの一環として、書類の送達の規定が見直されたものでございます。
行政手続条例第15条第３項には、聴聞の手続における通知の名宛人の所在が不明なときの
書類の送達手続が規定されており、この手続を書面だけではなく別の方法でもできるように、
現行条例第15条第３項の「その者の氏名、同項第３号及び第４号に掲げる事項並びに当該行
政庁が同項各号に掲げる事項を記載した書面をいつでもその者に交付する旨を当該行政庁の
事務所の掲示場に掲示すること」の文言を「公示の方法」に改め、同項後段の「この場合に
おいては、掲示を始めた日から２週間を経過したときに、当該通知がその者に到達したもの
とみなす。」という文言を削るものでございます。
第３項の次に、公示すべき事項及び、この書面をいつでもその本人に交付する旨を記載し
たものを不特定多数の者が閲覧できる状態に置くとともに、公示すべき事項などが記載され
た書面をこれまでと同様に掲示板に掲示する方法、または事務所の電子計算機の映像を表示
する措置によって行うこととすること、これまでどおり、これらの措置を行って２週間経過
した後に、この通知がその者に到達したものとみなすこととする条文を追加するものでござ
います。
第16条及び11ページの第22条第３項の２か所につきましては、本条例第15条第３項及び第
４項の改正に伴う引用条文の条文番号の改正を行うものでございます。
また、第22条第３項後段中、「掲示を始めた日から２週間を経過した」の文言を２か所削
り、「掲示を始めた」の文言を「当該措置を開始した」の文言に改めるものです。
第29条については、本条例第15条第３項及び第４項の改正に伴う引用条文番号の改正とな
ります。
この条例は、附則によりまして、改正行政手続法の施行日に合わせて令和８年５月21日か
ら施行するものでございます。
以上で説明を終わります。どうぞよろしくお願いいたします。
