それでは、議案第８号について御説明いたします。
この改正は、令和８年度から子ども・子育て支援納付金の拠出が開始されることに伴い、
広川町国民健康保険税に子ども・子育て支援分を追加するため、改めるものでございます。
内容につきましては、16ページから21ページの改正案及び22ページから37ページの新旧対
照表によるところですが、初めに議案書38ページの説明資料により御説明をいたします。
まず、上２つの表、賦課区分・国民健康保険税率（額）です。
現行は上の表で、医療保険分、後期支援分、介護保険分の３区分となっておりますが、改
正後は下の表のとおり、子ども・子育て支援分を追加いたします。
税率、税額は所得割を0.27％、均等割を1,100円、平等割を1,100円、18歳以上均等割を100
円といたします。
今回追加します子ども・子育て支援分では、18歳未満に係る均等割は全額軽減となります。
その軽減分を18歳以上の被保険者で分かち合って負担するために設けられたものが18歳以上

均等割でございます。子育て世帯を支援するための各事業費に充てるという趣旨のため、子
供がいる世帯の負担が大きくならないようにするためです。
この子ども・子育て支援分の税額案は、県が市町村ごとに示す標準保険料率を100円単位
にまとめたものです。県内の53の市町村が市町村ごとに示された標準保険料率を採用予定と
しているとのことで、そういった県内の状況も踏まえ、広川町におきましても同様に採用し
たところでございます。
次に、下２つの表、課税限度額についてですが、子ども・子育て支援分は上限を30千円と
しておるところでございます。
概要につきましては今御説明したとおりですが、改めまして本条例の主な改正箇所につい
て、議案書22ページからの新旧対照表を使って御説明をいたします。
まず、第２条第１項第１号です。この条文では医療保険分について定めております。
医療保険分は、国民健康保険税のうち、ほかの賦課区分、後期支援分、介護保険分に充て
る費用を除いたものとなっておりますので、後期支援分、介護支援分に子ども・子育て支援
分を追加するものでございます。
続いて、第２条第１項第４号に子ども・子育て支援分を国民健康保険税の課税額の一つと
して規定をしております。
続きまして、23ページです。
中ほどの第２条第５項に子ども・子育て支援分の限度額を定めております。
次に、24ページから25ページにかけてでございます。
第９条の４に子ども・子育て支援分の所得割額を、第９条の５に均等割額を、第９条の６
に18歳以上被保険者均等割額を、25ページ、第９条の７に平等割額をそれぞれ定めておりま
す。
第23条は国民健康保険税の減額について定めておりますが、減額の対象に子ども・子育て
支援分を追加しております。
26ページから28ページにかけてです。
第23条第１項第１号のキ、ク、ケにつきましては、子ども・子育て支援分の低所得者に対
する均等割額と平等割額の７割軽減となる場合の軽減額を、27ページ、第２号のキ、ク、ケ
につきましては５割軽減となる場合の軽減額を、28ページ、第３号のキ、ク、ケにつきまし
ては２割軽減となる場合の軽減額の規定を追加しておるところでございます。
29ページです。
第23条第２項は未就学児に対する均等割の減額について定めておりますが、同項第３号と
して、子ども・子育て支援分を追加しているところです。
29ページから30ページにかけてでございます。
第23条第３項は、出産被保険者に対する軽減について定めておりますが、そこに18歳以上
被保険者均等割額を追加しております。同項第７号に出産被保険者に係る子ども・子育て支
援分の所得割額の減額についてを、第８号に同じく均等割額の減額についてを、第９号に18
歳以上被保険者均等割額の減額についてをそれぞれ追加しておるところです。
30ページ、第23条第４項といたしまして、18歳未満被保険者に係る子ども・子育て支援分
課税額の被保険者均等割額を全額免除する規定を追加しておるところです。
30ページ以降の附則につきましては、第３項、第４項及び第６項から第13項まで課税の特

例規定について、子ども・子育て支援納付金課税額の所得割額を適用対象に加える旨、追加
をしております。
議案書20ページから21ページにかけての附則を御覧ください。
この条例は、令和８年４月１日から施行いたします。また、改正後の当条例の規定は令和
８年度以降の年度分の国保税について適用し、令和７年度分までにつきましては従前の例に
よると定めております。
