そういった喫緊の課題であります少子化対策の抜本的な改革、改正、制度がよいほうに向
かっていくということでございますので、これにつきましては広川町国民健康保険の被保険
者の皆様方にも一定の御負担をいただきたいということでございます。
以上です。
○議長（光益良洋）
ほかにありませんか。
〔「なし」と呼ぶ者あり〕
○議長（光益良洋）
質疑もないようですので、これをもって質疑を終結いたします。
これから討論を行います。
討論のある方の挙手を願います。９番江藤美代子議員。
○９番（江藤美代子）
議案第８号 広川町国民健康保険税条例の一部改正について、反対の立場で討論を行いま

す。
この制度は、健康保険の税率に子ども・子育て支援分を設けて課税する増税です。国民健
康保険は病気やけがのときに安心して医療が受けられるようにする社会保障制度です。子ど
も・子育て支援金の対象事業は何かといいますと、児童手当とかこども誰でも通園制度など、
子育ての施策です。子育て施策を充実させるなら、国の一般財源で対応すべきと考えます。
国民健康保険とか、ほかの健康保険などで徴収するのは明らかな目的外使用と考えます。
もう一点、子ども・子育て支援金は子育て支援のための増税であるから子供に負担させる
のはおかしいということで、18歳までの均等割は10割軽減措置となります。そのうち、未就
学児の５割の均等割は公費で負担です。未就学児の残りの５割と６歳から18歳までの均等割
分は子供以外の国保被保険者が負担するとなっています。これも子育て支援と言うならば、
国が財源を手当てすべきです。
国民健康保険は、先ほども言いましたけれども、病気やけがのときに安心して医療が受け
られるようにする社会保障の制度です。国民健康保険は支え合いの制度と言う方があります
が、支え合いというのは、本来、自発的な助け合いを意味します。しかし、国民健康保険や
子ども・子育て支援金は公的な制度で、法律による強制徴収になります。支え合いという言
葉で負担増を説明していないでしょうか。
さらに、今回、課税限度額の改定を提案しながら医療保険分10千円引上げについては提案
していません。昨年度、課税限度額の引上げは、さっき御答弁にありましたように、専決で
行われました。専決は、特に緊急を要するため、議会を招集する時間的余裕がないことが明
らかであると認めるときにできるとなっています。本年度の引上げは、専決事項とするには
適当ではない。現に、子ども・子育て支援分の引上げは提案をしています。議案を修正して
再提案するか、本議会に追加議案として提出すべきであると考えます。
反対いたします。
○議長（光益良洋）
次に、賛成者の発言を求めます。４番梶原一美議員。
○４番（梶原一美）
私は、国民健康保険税条例の一部改正について賛成の立場で討論をいたします。
本条例における保険税率の改正は、児童手当の拡充や妊婦のための支援給付など、既に始
まっている子ども・子育て支援の拡充に充てられる子ども・子育て支援金に関するものです。
少子化対策は喫緊の課題であり、社会保障制度の維持については、この解消は必要なもの
だと考えます。被保険者の負担増も一定程度あるものの、喫緊の課題である少子化対策の抜
本的強化につながるものとして、その導入については理解が必要だと考えております。
税率については、将来の保険税率県内統一化を見据え、県が示す標準保険料率に準じてい
ることから妥当なものであると判断します。
これらのことから本議案に賛成いたします。
○議長（光益良洋）
ほかにありませんか。
〔「なし」と呼ぶ者あり〕
○議長（光益良洋）
ないようですので、これをもって討論を終結いたします。

これから議案第８号 広川町国民健康保険税条例の一部改正についてを採決いたします。
討論がありますので、この採決は起立によって行います。
原案のとおり決定することに賛成の方は起立願います。
〔賛成者起立〕
○議長（光益良洋）
起立多数です。よって、議案第８号は原案のとおり可決されました。
日程第６ 議案第９号
○議長（光益良洋）
日程第６．議案第９号 広川町特定乳児等通園支援事業の運営に関する基準を定める条例
の制定についてを議題といたします。
提案者の提案理由並びに内容説明を求めます。町長。
○町長（氷室健太郎）
議案書39ページをお願いいたします。
議案第９号 広川町特定乳児等通園支援事業の運営に関する基準を定める条例の制定につ
いて御説明申し上げます。
提案理由といたしましては、子ども・子育て支援法等の一部を改正する法律の施行により、
新たな通園給付として、こども誰でも通園制度が創設され、令和８年４月１日から給付化さ
れることに伴い、給付の対象となる特定乳児等通園支援事業として確認するための基準を定
めるため、本条例を制定するものでございます。
詳細につきましては子ども課長が御説明いたしますので、御審議の上、御決定賜りますよ
うお願いいたします。
○議長（光益良洋）
子ども課長。
○教育委員会事務局子ども課長（才所潤一）
議案第９号 広川町特定乳児等通園支援事業の運営に関する基準を定める条例の制定につ
いて御説明いたします。
議案書の39ページを御覧ください。
子ども・子育て支援法の一部改正により、令和８年４月１日から、保育所等に通園してい
ないゼロ歳６か月から３歳未満の児童を対象に、一定時間までの利用可能枠の中で就労要件
等を問わず柔軟に利用できる乳児等通園支援事業、いわゆるこども誰でも通園制度が導入さ
れます。
本町では、乳児等通園支援事業の実施に伴い、実施事業所に対する本町の設備及び運営に
係る基準を定めるため、広川町乳児等通園支援事業の設備及び運営に関する基準を定める条
例を昨年12月定例会において制定いただいたところですが、改正後の子ども・子育て支援法
では、施設等に対して乳児等支援給付費を支給することが定められており、給付費の支給の
ための確認手続を行うため、国の基準を踏まえ、本町の確認基準について新たに条例を制定
しようとするものです。
それでは、条例の内容について御説明いたします。
議案書は40ページをお願いします。

第１条では、本条例の趣旨、第２条では、事業運営の基本理念や運営に関する一般原則を
定めております。
41ページになります。
第３条では、特定乳児等通園支援事業者は１時間当たり及び１か月当たりの利用定員を定
めること、また、第４条では、利用開始前に保護者と面談を行い、子供の状況や養育環境を
把握すること、またあわせて、重要事項の文書交付と同意取得を規定しております。
42ページになります。
第５条では、申込みに対し、正当な理由なく拒否することの禁止、第６条では、市町村が
行う利用のあっせんや要請に対する協力、第７条では、利用資格や給付内容が正しいか、市
町村が発行する認定証での確認、第８条では、未認定の保護者から相談があった際、速やか
に申請が行えるよう援助することを規定しています。
43ページになります。
第９条では、子供と保護者の状況、ほかのサービスの利用状況の把握に努めること、第10
条では、幼稚園や保育所等へスムーズに移行できるよう情報提供や連携に努めること、第11
条では、提供日時や内容などの詳細な記録の義務づけを規定しています。
第12条では、利用料に加え、日用品や行事費、食事代などの実費徴収ができることや、徴
収時は事前説明と書面による同意、領収証を交付することを規定しています。
45ページをお願いします。
第13条では、市町村から支払われた給付費の額を保護者に通知すること及び提供証明書の
交付について規定、第14条では、保育の内容について国の指針に準じた適切な内容で支援を
提供することを規定、第15条では、サービスの質の自己評価及び外部評価の受審、公表につ
いて規定しています。
46ページになります。
第16条では、子供、保護者からの相談に対し適切な助言や援助を行う義務、第17条では、
子供の体調急変時は速やかに家族や医療機関へ連絡、措置を講じる義務、第18条では、不正
受給の疑いがある場合、遅滞なく市町村に通知する義務、第19条では、事業の目的、内容、
職員体制、料金、虐待防止策などを定めた規定の整備を義務づけています。
47ページになります。
第20条では、適切な職員配置、自社職員による提供、研修機会の確保を規定、第21条では、
あらかじめ定めた定員を超えてサービスを提供することの禁止、第22条では、運営規程や料
金などの重要事項を事業所内での掲示及びウェブサイト等で公表する義務を規定しています。
48ページになります。
第23条では、国籍、信条、社会的身分、支払い状況による差別的取扱いの禁止、第24条で
は、職員による子供への虐待、有害な影響を与える行為の禁止、第25条では、職員及び管理
者の守秘義務や他機関への情報提供時の同意取得を規定、第26条では、保護者が適切に選択
できるよう情報提供に努めること及び虚偽、誇大広告の禁止を規定しています。
49ページになります。
第27条では、利用者の紹介を目的とした紹介料などの金品のやり取りを禁止、第28条では、
窓口設置、記録、市町村の調査への協力、指導に対する改善義務を規定しています。
50ページになります。

第29条では、地域住民や自発的活動との交流、連携に努めること、第30条では、事故防止
指針の策定、委員会の設置、事故発生時の市町村、家族への連絡及び損害賠償義務について
規定しています。
51ページになります。
第31条では、本事業の会計を他の事業の会計と明確に分ける義務、第32条では、計画、提
供、記録、苦情、事故記録などの整備、完結日から５年間の保存義務を規定しています。
52ページになります。
第33条では、書面の作成、保存、交付に代えてデジタルデータによる対応を認めることを
規定しています。
54ページになります。
附則として、この条例は令和８年４月１日から施行するとしています。
説明は以上となります。よろしくお願いいたします。
