本条例の一部改正については、町の融資制度であります広川町中小企業融資資金について、
筑後信用金庫、福岡銀行に50,000千円を預託し、運用いただいております。近年、この融資
を利用される事業者が増えていること、また、金利を据え置くため金融機関から預託金の増
額要望があり、10,000千円を増額するものです。
議案書79ページの新旧対照表を御覧ください。
第４条、預託金の額中、「50,000千円」を「60,000千円」に改めるものです。
