○６番（山下 茂）
融資枠の要望があったということなんですけど、融資枠が幾らまで増えるかということと、
あと、向こうのほうから要望があったということで、協調倍率とか、その辺の交渉について
どういうふうにされたか、お伺いいたします。
○議長（光益良洋）
産業課長。
○産業課長（山下誠紀）
増額分の10,000千円につきましては、筑後信用金庫さんの枠を増やします。現在、50,000
千円中、筑後信用金庫が35,000千円、福岡銀行が15,000千円となっており、現在の執行率は
全体で67％となっておるところです。
協調の倍率につきましては、条例上は２倍以上となっており、現状４倍までとなっておる
ところです。こちらは変更はございません。
以上です。
○議長（光益良洋）
ほかにありませんか。７番丸山幸弘議員。
○７番（丸山幸弘）
預託金に対する協調倍率で融資の枠の総額が決まると思うんですね──そうですよね。融
資枠が足りなくなってきているし、金利が今、町の制度融資で利率が下がっているので利用
者が増えるだろうということで、融資枠を増やそうということだろうと思うんです。
預託金を増やす方法と協調倍率を増やすという二通り方法があるので、銀行が預託金を増
やしてくれと要望があったから、じゃ、増やしましょうと言うんではなくて、協調倍率２倍
以上と書いてあるんですから、これは話合いで、例えば、今４倍でしょうけど、５倍にする
とか６倍にすればもっと融資枠は増えるんですけれども、そういう交渉をされたかどうかで
すね。
この際、低金利で今有利になっているのであれば、そっちの協調倍率も上げて、もっとた
くさん融資を使っていただけるようにしていただいたほうがいいかなと思うので、その辺に
ついてちょっとお伺いしたいと思います。
○議長（光益良洋）

産業課長。
○産業課長（山下誠紀）
確かに、制度としては２種類やり方はあると思いますけれども、今回の金融機関との協議
の中では、預託金の増額要望があっておるところでございます。
今後につきましては、確かに、現在、町の融資制度の利率のほうが有利となっております
し、今後この制度を利用される中小企業の方も増えることかと予測がされますので、金融機
関ともこの制度について、今後また融資制度会議の中で検討していきたいと考えております。
以上です。
