82ページの新旧対照表を御覧ください。
本条例におきまして、水道事業及び下水道事業の経営の規模を規定しております。
現行では、第３条第３項第１号における下水道の排水区域は、下水道法第４条第１項に規
定する事業計画に定められた区域としておりますが、第２号以降は以前の全体計画の数値で
ある排水区域面積550ヘクタール、排水人口１万5,800人、１日最大処理能力は5,755立方
メートルの各数値を記載しております。令和３年度に全体計画を変更しており、この数値が
減少していることや、本来、最新の整備計画として届出している事業計画の区域、区域内人
口をそれぞれ排水区域、排水人口とすべきと考えまして、第２号を削り、第３号中「排水人
口は、１万5,800人とする。」を「前号の区域内人口とする。」に改め、第４号を削ります。
なお、矢部川流域下水道事業各構成市におきましても、具体的な数値は記載しておらず、
事業計画の内容としております。
81ページ、附則でこの条例は公布の日から施行するとしております。
