計上し、２項．国庫補助金は254千円、３項．国庫委託金は192千円をそれぞれ減額していま
す。
16款１項．県負担金は2,990千円の増額、２項．県補助金は園芸農業等総合対策事業補助
金など39,091千円の減額、３項．県県委託金は都市計画基礎調査業務委託金など1,126千円
を増額しています。
18款１項．寄付金は500千円を増額、19款１項．基金繰入金は財政調整基金繰入金など116,032
千円を減額しています。
21款４項．雑入は4,388千円の減額、22款１項．町債は地方債の補正にて説明しました事
業について41,200千円を増額しています。
