総務課長。
○総務課長（鹿田 健）
質問の趣旨のほうがちょっと定かではございません。私が理解していないところなんです
が、歳出の執行残に関する金額が多くないかという観点から申し上げますと、見ていただく
とおり、かなりのマイナスの精算の補正がございまして、結果として、その分を学校建設基
金で積み立てるというような予算にしているところでございます。
この点につきましては、８年度の予算編成におきまして、執行残が多額であるものにつき
ましては各課に一旦戻して再査定等を実施したところで、できる限り、執行残をつくらない
ような方向で新年度予算編成をやらせていただいたところでございます。
今年度の補正につきましては、執行残がやや多いのではないかというふうに感じるところ

でございます。
以上です。
