議案第24号 令和８年度広川町一般会計予算について御説明申し上げます。
予算書１ページをお願いいたします。
新年度の一般会計予算については、第１条第１項のとおり、歳入歳出予算総額9,996,091
千円で御提案いたします。前年度予算と比較すると464,999千円、約4.9％の増となっており
ます。
第２条 債務負担行為につきましては、予算書７ページのとおり、福岡県議会議員一般選
挙費をはじめ、10の債務負担行為をお願いするものです。
第３条 地方債につきましては、予算書８ページのとおり、11の起債の目的ごとに限度額、
起債の方法、利率、償還の方法を定め、総額204,000千円の地方債をお願いするものです。
第４条は歳出予算の流用について定めたものであり、給料、職員手当等及び共済費につい
て、地方自治法第220条第２項ただし書による項の経費の流用を定めたものです。
２ページをお願いします。
歳入予算について御説明いたします。
１款．町税は前年度より約2.8％、70,587千円の増収を見込み、2,630,088千円を計上して
おります。
２款．地方譲与税は76,500千円、３款．利子割交付金は5,000千円、４款．配当割交付金
は18,000千円、５款．株式等譲渡所得割交付金は20,000千円、６款．法人事業税交付金は
55,000千円を計上しています。
７款．地方消費税交付金は530,000千円、８款．ゴルフ場利用税交付金は6,000千円、10款．
地方特例交付金は40,483千円を計上しています。
３ページをお願いいたします。
11款．地方交付税につきましては、地方財政計画や町税の状況等により前年度より210,000
千円増の20億円を計上しています。
12款．交通安全対策特別交付金は2,510千円、13款．分担金及び負担金は44,921千円、14
款．使用料及び手数料は48,210千円を計上しています。
15款．国庫支出金は1,820,797千円、16款．県支出金は1,110,464千円、17款．財産収入は
22,901千円を計上しています。
４ページをお願いいたします。
18款．寄付金は430,000千円、19款．繰入金は607,152千円、20款．繰越金は１億円、21款．
諸収入は224,065千円、22款．町債は204,000千円を計上しています。
続きまして、５ページ、６ページをお願いいたします。
歳出予算について御説明いたします。
１款．議会費は92,518千円、２款．総務費は1,428,366千円を計上しています。
３款．民生費は前年度より約9.6％増の4,240,508千円、４款．衛生費は726,323千円を計
上しています。

５款．農林水産業費は292,917千円、６款．商工費は184,562千円を計上しております。
７款．土木費は竜光寺公園リニューアル工事の進捗などにより約8.6％減の777,970千円、
８款．消防費は防災拠点施設整備事業の進捗などにより約19.3％減の530,850千円を計上し
ております。
９款．教育費は、１項．教育総務費のＧＩＧＡスクール推進事業におけるタブレット端末
更新などにより約36.4％増の975,477千円を計上しております。
10款．災害復旧費は5,500千円、11款．公債費は721,100千円、12款．予備費は20,000千円
を計上しております。
歳入歳出予算に係る詳細につきましては、９ページ以降の歳入歳出予算事項別明細書に記
載しております。
また、170ページ以降には、給与費明細書、債務負担行為に関する調書、地方債に関する
調書をつけております。
例年と同様に予算説明資料を事前に配付しておりますので、併せて御覧いただきますよう
にお願いをいたします。
以上で議案第24号の説明を終わらせていただきます。
次に、議案第25号 令和８年度広川町国民健康保険特別会計予算について御説明申し上げ
ます。
予算書の１ページをお願いします。
新年度の歳入歳出予算の総額は、第１条第１項のとおり、2,190,241千円を計上しており
ます。前年度と比較すると88,614千円、約3.9％の減となっており、主な要因としては被保
険者の減少によるものです。
第２条は歳出予算の流用を定めたものです。
それでは、歳入予算の主なものについて御説明いたします。
２ページをお願いいたします。
１款１項．国民健康保険税480,944千円、６款１項．県負担金1,515,622千円、10款１項．
他会計繰入金185,405千円を計上しています。
続きまして、歳出予算の主なものについて御説明いたします。
３ページをお願いいたします。
１款１項．総務管理費は職員の人件費や事務的経費に要する予算で、36,443千円を計上し
ています。
２款１項．療養諸費は1,277,411千円、２項．高額療養費は192,100千円、４項．出産育児
諸費は6,000千円を計上しています。
３款１項．医療給付費分は411,788千円、２項．後期高齢者支援金等分は145,577千円、３
項．介護給付金分は53,536千円、４項．子ども・子育て支援金分は13,166千円を計上してい
ます。
６款２項．特定健康診査等事業費は45,180千円、９款１項．償還金及び還付加算金は2,350
千円を計上し、10款１項．予備費には1,000千円を計上しております。
以上、総額2,190,241千円の予算としています。
歳入歳出予算に係る詳細につきましては、５ページ以降の歳入歳出予算事項別明細書に記
載しています。

また、20ページ以降には給与費明細書をつけております。
以上で議案第25号の説明を終わらせていただきます。
続きまして、議案第26号 令和８年度広川町後期高齢者医療特別会計予算について御説明
申し上げます。
予算書の１ページをお願いいたします。
新年度の歳入歳出予算の総額は、第１条第１項のとおり414,918千円を計上しています。
前年度と比較すると40,647千円、約10.9％の増となっております。主な要因といたしまして
は、被保険者の増加、医療の高度化及び高額薬剤の保険適用によるものです。
２ページをお願いします。
歳入予算について御説明いたします。
１款１項．後期高齢者医療保険料307,378千円、４款１項．一般会計繰入金102,699千円、
５款１項．繰越金4,000千円が主な歳入となります。
３ページをお願いいたします。
歳出予算について御説明いたします。
１款１項．総務管理費1,820千円、２款１項．後期高齢者医療広域連合納付金412,259千円
が主な歳出となります。
歳入歳出予算に係る詳細につきましては、４ページ以降の歳入歳出予算事項別明細書に記
載しています。
以上で議案第26号の説明を終わらせていただきます。
次に、議案第27号 令和８年度広川防災ダム管理特別会計予算について御説明申し上げま
す。
予算書の１ページをお願いします。
新年度の歳入歳出予算の総額は、第１条第１項のとおり37,105千円を計上しており、前年
度と比較すると4,180千円、約12.7％の増となっております。
２ページをお願いいたします。
歳入予算について御説明いたします。
２款３項．県委託金13,053千円、４款１項．一般会計繰入金23,852千円、５款１項．繰越
金200千円を計上しています。
３ページをお願いいたします。
歳出予算について御説明いたします。
１款１項．総務管理費28,334千円、２款１項．公債費8,571千円、10款１項．予備費200千
円を計上しています。
歳入歳出予算に係る詳細につきましては、４ページ以降の歳入歳出予算事項別明細書に記
載をしています。
また、10ページに地方債に関する調書をつけております。
以上で議案第27号の説明を終わらせていただきます。
次に、議案第28号 令和８年度広川町水道事業会計予算について御説明申し上げます。
水道事業におきましては、１月末現在で6,390戸、１日平均で約4,300立方メートルの水を
供給しております。一般住宅、共同住宅の増、地下水から上水道への切替え等により加入件
数は増加していますが、節水機器の普及、人口減少等により使用水量は横ばいか、やや減少

傾向に転じております。本年度も水道施設の適切な維持管理、給水サービスに努め、安全で
良質な水の安定供給に努めてまいります。整備面では、水圧不足箇所の配水管ループ化等を
実施いたします。
予算書１ページをお願いいたします。
本年度の予算総額は377,854千円で、前年度に対して31,613千円の減額であります。
第２条では業務の予定量を定めております。給水戸数6,420戸、年間総給水量158万450立
方メートル、１日平均給水量4,330立方メートルと定めております。
第３条、予算の収益的収支は100,450千円でございます。
第４条、予算の資本的収支では73,634千円の不足分が生じますが、過年度分損益勘定留保
資金等をもって補填するものでございます。
予算書２ページをお願いいたします。
第５条では、議会の議決を経なければ流用することができない経費を定めております。
第６条では、一般会計から補助を受ける金額を720千円と定めております。
収益的収支予算及び資本的収支予算の詳細につきましては、３ページ以降の広川町水道事
業会計予算実施計画に記載をしております。
以上で議案第28号の説明を終わらせていただきます。
最後に、議案第29号 令和８年度広川町下水道事業会計予算について御説明申し上げます。
下水道整備状況は、令和７年度末で330ヘクタール、既存の全体計画のうち約75％の面整
備が完了しております。また、利用件数は１月末現在で2,989件となっております。令和８
年度については、新たな事業認可区域である吉常東部付近の整備に着手する予定であります。
予算書１ページをお願いいたします。
本年度の予算総額は722,551千円で、前年度に対して109,403千円、率にして17.8％の増額
であります。
業務の予定量は、処理戸数3,040戸、年間有収水量91万4,000立方メートルを予定しており
ます。主要な建設改良事業は、管路建設費159,000千円、流域下水道の建設負担金22,061千
円となっております。
第３条、予算の収益的収支は20,108千円でございます。
第４条、予算の資本的収支では139,621千円の不足分が生じますが、当年度分損益勘定留
保資金等をもって補填するものでございます。
予算書２ページをお願いします。
第５条では、企業債の限度額等を定めております。
第６条では、一時借入金の限度額を３億円と定めております。
第７条では、議会の議決を経なければ流用することができない経費を定めております。
第８条では、一般会計から補助を受ける金額を178,445千円と定めております。
第９条では、利益剰余金の処分について、資本的収入額が資本的支出額に対して不足する
額の補填として処分する額を44,498千円と定めるものです。
収益的収支予算及び資本的収支予算の詳細につきましては、３ページ以降の広川町下水道
事業会計予算実施計画に記載をしております。
以上で議案第29号の説明を終わらせていただきます。御審議の上、御決定賜りますようよ
ろしくお願いいたします。

