○議長（光益良洋）
おはようございます。定刻になりましたので、ただいまから本日の会議を開きます。
本日の日程は、お手元に配付いたしております議事日程第４号のとおりであります。
直ちに議事日程に入ります。
日程第１ 議案第24号
○議長（光益良洋）
日程第１．議案第24号 令和８年度広川町一般会計予算についてを議題といたします。
本案について、一般会計予算審査特別委員会委員長の審査報告を求めます。一般会計予算
日程第１ 議案第24号 令和８年度広川町一般会計予算について
