日程第４ 議案第27号 令和８年度広川防災ダム管理特別会計予算について
日程第５ 議案第28号 令和８年度広川町水道事業会計予算について
日程第６ 議案第29号 令和８年度広川町下水道事業会計予算について
日程第７ 発委第１号 広川町議会委員会条例の一部改正について
日程第８ 常任委員会、議会運営委員会及び議会広報調査特別委員会の閉会中の所管事
務調査について

審査特別委員長、山下茂議員。
○一般会計予算審査特別委員会委員長（山下 茂）
一般会計予算審査特別委員会の審査結果について御報告申し上げます。
議案第24号 令和８年度広川町一般会計予算については、去る３月10日の本会議にて一般
会計予算審査特別委員会に付託されたもので、特別委員会に常任委員会の所管ごとの分科会
を設置し、３月11日から16日までの３日間、関係職員の説明を求め慎重に審査が行われまし
た。
３月18日に特別委員会を開催し、分科会の審査結果の報告を求め、慎重に審査し、採決の
結果、賛成多数で原案どおり可決すべきものと決定をいたしました。
なお、可決するに当たり、次の附帯決議がされたので、御報告申し上げます。
１つ、計画的な財政運営に努めるとともに、持続可能な財政基盤の構築に努められたい。
２つ、デジタル技術等の活用により、住民の利便性の向上と業務の効率化を図られたい。
３つ、人材育成基本方針に基づき、職員の能力向上を図るとともに、適切に配置し、機能
する組織の構築に努められたい。
４つ、自然災害に強いまちづくりを推進されたい。
５つ、行政区や地域コミュニティの在り方については、財政面を含め、今後の方針を示さ
れたい。
６つ、公共施設の指定管理については民間活用を推進し、地域の活性化を図られたい。
７つ、こどもまんなかアクションプランの効果的な実行に努められたい。
８つ、全町民の健康増進のため、健康づくり及び疾病の早期発見、早期治療を全世代にわ
たり推進し、健康寿命の延伸にさらに努められたい。
以上、御報告申し上げます。
○議長（光益良洋）
委員長の報告が終わりましたので、質疑を行います。
質疑のある方の挙手を願います。
〔「なし」と呼ぶ者あり〕
○議長（光益良洋）
質疑もないようですので、これをもって質疑を終結いたします。
これから討論を行います。
討論のある方の挙手を願います。９番江藤美代子議員。
○９番（江藤美代子）
令和８年度一般会計予算については、評価するべき予算がたくさんございます。国の予算
に上乗せもして、質を落とさない小学校学校給食費の無償化、教育支援センターの始動、併
せてKibiru（キビル）の活用、下広川小学校のグラウンド整備、武道場、中学校体育館の空
調整備への着手など、大いに期待します。
一方、国の交付金を活用したネイティブテキスタイル産地プロジェクトや地域力創造アド
バイザー制度の活用事業、地域活性化起業人の受入れについては疑問が残ります。また、同
和対策事業予算についてですけれども、人権問題の早期解決のためとありますが、広川町の
人権問題の解決にどう役立っているのでしょうか。いつから始まったかも分からないほど、
長年にわたり事業が行われているにもかかわらず、まだ解決していないということは効果が

上がっていないということではないでしょうか。同和に関する補助金を特定団体に投げ渡す
ことはやめるべきです。全ての人の人権が尊重される広川町実現のために、町民誰もが納得
する予算編成を求めます。
反対いたします。
○議長（光益良洋）
次に、賛成者の発言を求めます。４番梶原一美議員。
○４番（梶原一美）
私は賛成の立場で意見を述べさせていただきます。
今回提案されている一般会計予算案については、一般会計予算審査特別委員会に付託され、
各分科会において慎重に審議を重ねてまいりました。議会からの前年度決算に対する意見や
指摘事項等についても真摯に受け止められ、適正な予算編成が行われているものと感じてお
ります。その結果、一般会計予算審査特別委員会においても、委員長報告のとおり、賛成多
数で原案のとおり可決することと決定いたしております。
反対意見があった中の同和問題に対する予算についてですが、2002年の特措法終了後、一
般対策に移されておりますが、このことは、同和問題の早期解決を目指す取組を放棄するも
のではないと地対協の具申の中でも言われております。現在、部落問題は形を変えて悪質・
巧妙化しています。ネット等を含めて、まだまだ解決すべき課題は多いと考えます。同和問
題を解消することは我が国の重要な課題であり、積極的に施策を推進していくことが町の責
務でもあります。
以上により、一般会計予算に賛成するものであります。
○議長（光益良洋）
ほかにありませんか。５番竹下英治議員。
○５番（竹下英治）
一応反対討論の立場で発言するわけですけれども、まずちょっと目的が、私は必ずしも同
和の部分を反対しているんじゃないということも明確にしたいと。同和については、不完全
ながら最低限のことをやられているかなと、そういうことで特にはそこに言及しません。執
行部はよく頑張っておられるなという感じは持っています。
そもそもこの背景となるのは、こども家庭庁の存在に対してちょっと僕は反対のところが
あって、疑義があって、そこの延長線上で反対討論をさせていただくことになると思います。
具体的には、時間があまりない中ですけれども、まず、施政方針の中の第５項目の中身、
これがこどもまんなかで一生懸命やるというのは理解できることなんですが、やっぱり子供
自体のことを考えて本当にやっているのかというところの趣旨から、この５番目の中身につ
いてちょっと疑義があるということで、今後も頑張っていただきたいということで、この施
政方針の５項の違和感を御報告させていただきます。
具体的には、強いて挙げれば、いわゆる物価高騰対応重点支援地方創生臨時交付金事業の
中の中学校子供給食の部分なんですが、４分の１ほど助成されていますが、ここは全額やれ
ばどうだと、私はちょっと期待していました。そもそも予算説明の中でこれは期待していた
項目で、ちょっとそこが外れていたということで、補正予算等で僕は年度内でもここは完全
無償化というか、一部補助金は出さざるを得ないかもしれないけれども、やったらどうだと
いうようなこと、そういうようなところにちょっと不足感を感じたから、こどもまんなかを

効果的に進めてもらうという意味合いでも一応反対という立場を取らせていただきたいとい
うふうに思います。
以上です。
○議長（光益良洋）
次に、賛成者の発言を求めます。１番下田めぐみ議員。
○１番（下田めぐみ）
私は本予算に計上されております同和対策事業について、賛成の立場から討論いたします。
我が国においては、2016年に全６条から成る部落差別の解消の推進に関する法律が施行さ
れました。部落差別解消は重要な課題であると明確に示されております。主な内容の１つに、
国、自治体の責務の項目がございます。国及び地方公共団体が連携し、相談体制の充実、教
育、啓発の推進を行うことを定めたとございます。法律が施行されてから10年がたちますが、
インターネット上での差別的書き込みや偏見に基づく誤った認識など、形を変えた差別が今
なお存在している現状がございます。差別は見えにくくなっただけで、決してなくなったわ
けではございません。だからこそ、正しい理解を広げるための啓発活動や教育の推進、相談
体制の充実は極めて重要です。人権施策は特定の誰かのためだけのものではなく、全ての町
民が安心して暮らせる地域社会を築くための基盤でもございます。
ここで、財政面について申し上げます。
限られた財源の中での予算措置であることは十分承知しております。しかし、人権施策は
支出ではなく、将来への投資だと思います。差別や偏見が放置されれば、地域の分断や対立
を生み、結果として行政コストや社会的損失を拡大させることにもつながりかねません。早
い段階での啓発や教育は、問題の深刻化を防ぐ予防的な財政運営であり、長期的に見れば、
持続可能なまちづくりでもあるわけです。人権が尊重される町は、子供にとっても、高齢者
にとっても、そして、将来世代にとっても誇れる町だと考えます。差別のない社会づくりは
行政の責務であり、私たち議員の責任でもございます。
奈良県人権保育研究会の大寺和男さんは、差別意識、偏見は誰もが持ってしまう意識です。
私たちが課題としなければならないのは、持ってしまった、持ってしまうかもしれない差別
意識に気づき、正していく力をどのようにつけていくかである。この力が人権感覚であると
述べられています。だからこそ、本予算はその理念を具体的な行動に移すためのものであり、
未来への投資であることと考え、賛成いたします。
以上、討論といたします。
○議長（光益良洋）
ほかにありませんか。
〔「なし」と呼ぶ者あり〕
○議長（光益良洋）
ないようですので、これをもって討論を終結いたします。
これから議案第24号 令和８年度広川町一般会計予算についてを採決いたします。
本案に対する委員長の報告は可決です。
討論がありますので、この採決は起立によって行います。委員長の報告のとおり決定する
ことに賛成の方は起立願います。
〔賛成者起立〕

○議長（光益良洋）
起立多数です。よって、議案第24号は原案のとおり可決されました。
お諮りいたします。一般会計予算審査特別委員長から報告がありました議案第24号に対す
る附帯決議を承認することに異議ありませんか。
〔「異議なし」と呼ぶ者あり〕
○議長（光益良洋）
異議なしと認めます。よって、附帯決議は一般会計予算審査特別委員長の報告のとおり承
