日程第２ 議案第25号
○議長（光益良洋）
日程第２．議案第25号 令和８年度広川町国民健康保険特別会計予算についてを議題とい
たします。
本案について、厚生文教常任委員長の審査報告を求めます。厚生文教常任委員長、梶原一
美議員。
○厚生文教常任委員会委員長（梶原一美）
厚生文教常任委員会に付託されました、議案第25号 令和８年度広川町国民健康保険特別
会計予算の審査結果について御報告申し上げます。
去る３月10日の本会議において付託されましたので、３月12日、関係職員の説明を求め慎
重に審査し、採決の結果、賛成多数で原案のとおり可決すべきものと決定いたしました。
なお、可決するに当たり、次の附帯決議がなされたので、報告いたします。
１、被保険者の健康意識を高め、医療費の縮減に努められたい。
２、税制改正の周知の徹底を図られたい。
３、国民皆保険を維持するため、国に対し財政支援を求められたい。
以上、御報告申し上げます。
○議長（光益良洋）
委員長の報告が終わりましたので、質疑を行います。
質疑のある方の挙手を願います。
〔「なし」と呼ぶ者あり〕
○議長（光益良洋）
質疑もないようですので、これをもって質疑を終結いたします。
これから討論を行います。
討論のある方の挙手を願います。９番江藤美代子議員。
○９番（江藤美代子）
国民健康保険特別会計について、私は一般質問でも、また、これの議案審議の折にも意見
を申しましたけれども、来年度から国保税に追加課税される子ども・子育て支援金分は明ら
かな目的外使用です。また、均等割についても、子ども・子育て支援金は子育て支援のため
の増税であるから子供に負担させるのはおかしいと言いながら、国が負担することなく、18
歳以上の国保被保険者が負担するとなっています。
この制度は国が決めた制度ではありますが、町は保険税率や一般会計からの繰入れなど、

努力すべきと考えます。本予算案は、子ども・子育て支援金分の課税を盛り込んだ予算案で
す。
反対いたします。
○議長（光益良洋）
次に、賛成者の発言を求めます。４番梶原一美議員。
○４番（梶原一美）
賛成の立場で討論いたします。
国民健康保険は、他の医療制度に比べ被保険者の年齢構成が比較的高く、医療費水準も高
いため、保険税負担も重くなるなど、構造的な課題を抱えております。そのため、財政基盤
の脆弱さが指摘されています。その現状に鑑み、広川町も名を連ねる全国町村会では、毎年
3,400億円の確実な公費の投入と、各自治体の実情に応じた財政支援を国へ要望していると
聞いております。
さて、広川町では１人当たりの医療費が、近年、県平均を下回ってはいるものの、依然高
い状況にあり、一方で被保険者は減り、税収においても令和８年度予算では昨年度から9,270
千円の減になっております。厳しい状況ではありますが、国民皆保険制度の最後のとりでと
してその役割を果たし、後につないでいかなければなりません。
そのような中、来年度から全世代で子供や子育て支援を支えるという新しい連帯の仕組み
として子ども・子育て支援金制度が始まります。国は支援金導入による負担について、その
裏側では社会保障の歳出改革を行い、社会保険料の負担を軽減させるため、負担は相殺され
ると説明していますが、いずれにしても、国が言うように、この支援金による実効性のある
子育て支援、少子化対策によって国民皆保険制度の維持可能性をも高めるという重要な意義
を持つというものであるならば、その導入に異論を挟む余地はありません。支援金の国保税
への賦課についても理解できると考えます。
以上のことから本予算に賛成いたします。
○議長（光益良洋）
ほかにありませんか。５番竹下英治議員。
○５番（竹下英治）
反対討論をするんですが、江藤議員とほぼ一緒なんですけど、ちょっとニュアンスが僕は
違うところがあるので、そこは言っておかないといけないかなということになりましたので、
若干の発言をさせていただきます。
そもそも特別会計なんですよね。特別会計の中で一般会計からの繰入れも１億数千万円あ
る中で、えらいシステムが複雑になっているなというふうに感じています。この前の広川町
国民健康保険条例の一部改正、このとき僕も反対したんですけれども、これの改正をやった
ということは、こういう施策をしないといけないということで、執行部の動きとしてはしよ
うがないかなと思う中で、そもそも我々が地方議会であってもやっぱり考えないといけない
のは、国民負担率をどうやって下げるかということでしょう。こういう制度の中で国がやっ
たことについても、地方議会としては、ここはやっぱり意見を言わないと地方議会の意味が
ないのかなと思ったところで反対すべきかなと思っています。
若干の話をすると、副町長がおられますけど、そもそも厚労省の所掌だったと思うんです
よね。厚労省が医療保険も担当しているんですね。そこら辺の絡みで、こども家庭庁ができ

たときに、内閣府と厚労省の部分から成っていますから、この辺の絡みも僕はあるんだとい
うふうに若干の疑いを持っています。そもそもこれは歳入庁といってインカムは１個にまと
めないといけない中において、そういった流れに逆行する施策を国がやっています。これに
ついては、国がやって、執行部もしようがないかなということでやる中においては、やっぱ
り地方議会はちゃんと意見を申さないと、いつまでもよくならないのかなという立場から反
対をさせていただきます。
○議長（光益良洋）
ほかにありませんか。
〔「なし」と呼ぶ者あり〕
○議長（光益良洋）
ないようですので、これをもって討論を終結いたします。
これから議案第25号 令和８年度広川町国民健康保険特別会計予算についてを採決いたし
ます。
本案に対する委員長の報告は可決です。
討論がありますので、この採決は起立によって行います。委員長の報告のとおり決定する
