日程第３ 議案第26号
○議長（光益良洋）
日程第３．議案第26号 令和８年度広川町後期高齢者医療特別会計予算についてを議題と
いたします。
本案について、厚生文教常任委員長の審査報告を求めます。厚生文教常任委員長、梶原一
美議員。
○厚生文教常任委員会委員長（梶原一美）
それでは、厚生文教常任委員会に付託されました、議案第26号 令和８年度広川町後期高
齢者医療特別会計予算の審査結果について御報告申し上げます。
去る３月10日の本会議において付託されましたので、３月12日、関係職員の説明を求め慎
重に審査し、採決の結果、賛成多数で原案のとおり可決すべきものと決定いたしました。
以上、御報告申し上げます。
○議長（光益良洋）
委員長の報告が終わりましたので、質疑を行います。

質疑のある方の挙手を願います。
〔「なし」と呼ぶ者あり〕
○議長（光益良洋）
質疑もないようですので、これをもって質疑を終結いたします。
これから討論を行います。
討論のある方の挙手を願います。
〔「なし」と呼ぶ者あり〕
○議長（光益良洋）
討論もないようですので、これをもって討論を終結いたします。
これから議案第26号 令和８年度広川町後期高齢者医療特別会計予算についてを採決いた
します。
本案に対する委員長の報告は可決です。委員長の報告のとおり決定することに異議ありま
せんか。
〔「異議なし」「異議あり」と呼ぶ者あり〕
○議長（光益良洋）
異議がありますので、この採決は起立によって行います。委員長の報告のとおり決定する
ことに賛成の方は起立願います。
〔賛成者起立〕
○議長（光益良洋）
起立多数です。よって、議案第26号は原案のとおり可決されました。
