日程第７ 発委第１号
○議長（光益良洋）
日程第７．発委第１号 広川町議会委員会条例の一部改正についてを議題といたします。
提案者の提案理由並びに内容説明を求めます。議会運営委員会委員長、山下茂議員。
○議会運営委員会委員長（山下 茂）
それでは、説明させていただきます。
発委第１号 広川町議会委員会条例の一部改正について説明いたします。
標記の条例案を地方自治法第109条第６項及び第７項並びに広川町議会会議規則第13条第
３項に基づき、別紙のとおり提出いたします。
提案理由ですが、広川町役場課設置条例が役場組織機構の見直しにより改正されたことか
ら、広川町議会委員会条例第２条を改正するものです。
次の新旧対照表を御参照ください。
第２条第１号、総務産業常任委員会の所管に、新たに新設されました「、自治防災課」を
加える改正を行うものです。
この条例は令和８年４月１日から施行するものです。
以上で説明を終わります。どうぞよろしくお願いいたします。
○議長（光益良洋）
説明が終わりましたので、質疑を行います。
質疑のある方の挙手を願います。
〔「なし」と呼ぶ者あり〕
○議長（光益良洋）
質疑もないようですので、これをもって質疑を終結いたします。
これから討論を行います。

討論のある方の挙手を願います。
〔「なし」と呼ぶ者あり〕
○議長（光益良洋）
討論もないようですので、これをもって討論を終結いたします。
これから発委第１号 広川町議会委員会条例の一部改正についてを採決します。
原案のとおり決定することに異議ありませんか。
〔「異議なし」と呼ぶ者あり〕
○議長（光益良洋）
異議なしと認めます。よって、発委第１号は原案のとおり可決されました。
日程第８ 常任委員会、議会運営委員会及び議会広報調査特別委員会の閉会中
の所管事務調査について
○議長（光益良洋）
日程第８．常任委員会、議会運営委員会及び議会広報調査特別委員会の閉会中の所管事務
調査についてを議題といたします。
総務産業常任委員長、厚生文教常任委員長、議会運営委員長及び議会広報調査特別委員長
から、会議規則第74条の規定によって、お手元に配付しました所管事務の調査について閉会
中の継続調査の申出がありました。
お諮りします。各委員長から申出のとおり、閉会中の継続調査とすることに異議ありませ
んか。
〔「異議なし」と呼ぶ者あり〕
○議長（光益良洋）
異議なしと認めます。よって、各委員長から申出のとおり、閉会中の継続調査とすること
に決定いたしました。
お諮りします。本定例会の会議に付議されました案件は全て終了いたしました。よって、
会議規則第６条の規定により、本日をもって閉会したいと思います。これに異議ありません
か。
〔「異議なし」と呼ぶ者あり〕
○議長（光益良洋）
異議なしと認めます。よって、本定例会は本日をもって閉会することに決定いたしました。
以上をもって本日の会議を閉じます。
これをもって令和８年第１回広川町議会定例会を閉会いたします。お疲れさまでした。
午前10時７分 閉会

