    ('c20c6947-8d36-4be6-8b7b-5d6e883a3428', v_assembly_id, '議案第9号', '広川町特定乳児等通園支援事業の運営に関する基準を定める条例の制定について', '条例の制定', '提案理由といたしましては、子ども・子育て支援法等の一部を改正する法律の施行により、新たな通園給付として、こども誰でも通園制度が創設され、令和８年４月１日から給付化されることに伴い、給付の対象となる特定乳児等通園支援事業として確認するための基準を定めるため、本条例を制定するものでございます。', '可決', '2026-03-09', 6, '{"points":["子ども・子育て支援法等の改正により新たな通園給付制度が創設された","令和8年4月1日から「こども誰でも通園制度」が給付化される","給付対象となる特定乳児等通園支援事業の確認基準を条例で定める必要がある"],"conclusion":"子ども・子育て支援法等の改正に伴い創設される「こども誰でも通園制度」の給付化に対応するため、特定乳児等通園支援事業を確認するための運営基準を定める条例を制定するもの。"}'::jsonb, 'draft', '2026-08-15T01:01:17.069+00:00', '43a1ad969155622aed2f73617e84406051e0cfd2ed9192c995d5025bc82f2912'),
    ('fb38b0e7-d998-425d-b941-d1c7c4ce99ff', v_assembly_id, '議案第10号', '広川町特定教育・保育施設及び特定地域型保育事業の運営に関する基準を定める条例の一部改正について', '条例の改正', '提案理由といたしましては、児童福祉法等の一部を改正する法律の施行により、特定教育・保育施設及び特定地域型保育事業並びに特定子ども・子育て支援施設等の運営に関する基準が一部改正されたことに伴い、本条例の一部を改正するものでございます。', '可決', '2026-03-09', 7, '{"points":["児童福祉法等の一部を改正する法律の施行に伴う改正である点","特定教育・保育施設及び特定地域型保育事業の運営基準が一部改正された点","特定子ども・子育て支援施設等の運営に関する基準も一部改正された点","上位法令の改正内容に合わせて本条例を整合させる必要がある点"],"conclusion":"児童福祉法等の改正により特定教育・保育施設等の運営基準が一部改正されたことに伴い、広川町の条例についても所要の一部改正を行うもの。"}'::jsonb, 'draft', '2026-08-15T01:01:45.281+00:00', '42681b004dba644311c2e5ba970c00791b2c77971a994f5f6fde580f315873c4'),
    ('95bbf6d7-fe10-4171-ac5b-230c9412940e', v_assembly_id, '議案第11号', '広川町家庭的保育事業等の設備及び運営に関する基準を定める条例の一部改正について', '条例の改正', '提案理由といたしましては、児童福祉法等の一部を改正する法律の施行により、家庭的保育事業等の設備及び運営に関する基準が一部改正されたことに伴い、本条例の一部を改正するものでございます。', '可決', '2026-03-09', 8, '{"points":["児童福祉法等の一部を改正する法律の施行が改正の契機となっている","国の基準改正に伴い、家庭的保育事業等の設備及び運営に関する基準が一部改正された","これに合わせて本町の条例も一部改正する必要がある"],"conclusion":"児童福祉法等の改正により家庭的保育事業等の設備及び運営に関する基準が一部改正されたため、広川町家庭的保育事業等の設備及び運営に関する基準を定める条例を一部改正するもの。"}'::jsonb, 'draft', '2026-08-15T01:02:08.68+00:00', '11b2790aec44dfdf4bab2fefcb715802b449ea8ca4618021ac84dd9086872708'),
    ('6ab98d05-108b-4421-af72-10f4310c2bc6', v_assembly_id, '議案第12号', '広川町乳児等通園支援事業の設備及び運営に関する基準を定める条例の一部改正について', '条例の改正', '提案理由といたしましては、国が定める乳児等通園支援事業の設備及び運営に関する基準の一部を改正する内閣府令により一部改正されたことに伴い、本条例の一部を改正するものでございます。詳細につきましては子ども課長が御説明いたしますので、御審議の上、御決定賜りますようお願い申し上げます。○議長（光益良洋）子ども課長。○教育委員会事務局子ども課長（才所潤一）それでは、議案第12号 広川町乳児等通園支援事業の設備及び運営に関する基準を定める条例の一部改正について御説明いたします。議案書の68ページの新旧対照表により御説明いたします。第９条、第10条及び第18条につきましては、「事業者」から「事業所」へ用語の変更がなされたことによる改正です。第13条につきましては、児童福祉法等の一部改正により、虐待対応が強化されたことによる改正です。第16条及び69ページの第20条第３項の改正につきましては、利用定員の年齢区分の柔軟化によるものでございます。', '可決', '2026-03-09', 9, '{"points":["国の内閣府令改正に伴い、乳児等通園支援事業の設備及び運営基準条例を一部改正するもの","第9条・第10条・第18条は「事業者」から「事業所」への用語変更","第13条は児童福祉法等の改正により虐待対応強化を反映","第16条・第20条第3項は利用定員の年齢区分を柔軟化する改正"],"conclusion":"国の基準改正に伴い、広川町乳児等通園支援事業の設備及び運営基準条例を改正するもの。用語変更、虐待対応強化、利用定員年齢区分の柔軟化が主な内容で、審議の上決定を求める議案。"}'::jsonb, 'draft', '2026-08-15T01:06:55.126+00:00', '9b917646f101df4863a8400e67a53fe1bfc6246011e222c634fac8bccb589653'),
    ('f473de7b-2538-417e-88eb-c2750752d2d2', v_assembly_id, '議案第13号', '広川町放課後児童健全育成事業の設備及び運営に関する基準を定める条例の一部改正について', '条例の改正', '提案理由といたしましては、児童福祉法等の一部を改正する法律の施行により、放課後児童健全育成事業の設備及び運営に関する基準が一部改正されたことに伴い、本条例の一部を改正するものでございます。', '可決', '2026-03-09', 10, '{"points":["児童福祉法等の一部改正に伴う条例改正である","放課後児童健全育成事業の設備及び運営に関する基準が国において一部改正された","上位法の改正内容に整合させるため本条例の関係規定を改める必要がある"],"conclusion":"児童福祉法等の改正により放課後児童健全育成事業の設備及び運営に関する基準が一部改正されたことに伴い、広川町の関連条例を整合させるため一部改正するもの。"}'::jsonb, 'draft', '2026-08-15T01:08:08.085+00:00', 'f5156005fb5356ea07648c22068408f6f42150122de62f73d129faa205629ee4'),
    ('492405c9-fbb1-4155-b1fa-0e5f0abc3813', v_assembly_id, '議案第14号', '広川町火入れに関する条例の一部改正について', '条例の改正', '提案理由といたしましては、消防庁の火災予防条例改正により本条例を一部改正するものでございます。詳細につきましては産業課長が御説明いたしますので、御審議の上、御決定賜りますようお願い申し上げます。○議長（光益良洋）産業課長。○産業課長（山下誠紀）それでは、議案第14号について説明いたします。議案書は75ページをお願いします。本条例の一部改正については、令和７年２月に大船渡市で発生した大規模な林野火災を受け、消防庁にて林野火災注意報や林野火災警報を創設する火災予防条例の改正を行っております。今回、八女地区消防組合の火災予防条例の改正に合わせ、広川町火入れに関する条例についても林野火災に関する気象条件の文言を改正するものでございます。', '可決', '2026-03-09', 11, '{"points":["消防庁が火災予防条例を改正し、林野火災注意報・警報を新設したことが背景にある","令和7年2月の大船渡市大規模林野火災を受けた措置である","八女地区消防組合の火災予防条例改正に合わせて本町条例も改正するものである","林野火災に関する気象条件の文言を改正する内容である"],"conclusion":"消防庁の火災予防条例改正を受け、林野火災に関する気象条件の文言を改める広川町火入れに関する条例の一部改正案について、産業課長が説明し審議を求めた。"}'::jsonb, 'draft', '2026-08-15T01:08:28.13+00:00', '174be55bf05b8e9a6230574579aba19d3f84666a9e3ce93920aaf5e3b76c2cc7'),
    ('973d8f48-07f9-4866-a181-6ee4908670f9', v_assembly_id, '議案第15号', '広川町中小企業融資資金貸付条例の一部改正について', '条例の改正', '提案理由といたしましては、金融機関の預託金増額要望により本条例を一部改正するものでございます。詳細につきましては産業課長が御説明いたしますので、御審議の上、御決定賜りますようお願い申し上げます。○議長（光益良洋）産業課長。○産業課長（山下誠紀）それでは、議案第15号について説明いたします。本条例の一部改正については、町の融資制度であります広川町中小企業融資資金について、筑後信用金庫、福岡銀行に50,000千円を預託し、運用いただいております。近年、この融資を利用される事業者が増えていること、また、金利を据え置くため金融機関から預託金の増額要望があり、10,000千円を増額するものでございます。', '可決', '2026-03-09', 12, '{"points":["金融機関からの預託金増額要望に基づく条例改正である","広川町中小企業融資資金は筑後信用金庫・福岡銀行に5,000万円を預託し運用している","融資利用事業者の増加と金利据え置きのため、預託金を1,000万円増額する"],"conclusion":"広川町中小企業融資資金貸付条例について、融資利用者の増加と金利据え置きを理由に金融機関から預託金増額要望があり、預託金を1,000万円増額する一部改正を行う議案である。"}'::jsonb, 'draft', '2026-08-15T01:08:50.745+00:00', '276e8706267ad6ac4c6ae9987a57a823c11a0e5ba5b78607db6d5d4916a4ae3c'),
