    ('37e3252c-132a-473d-8c9c-f7dd1a20d40f', v_assembly_id, '議案第17号', '広川町保健・福祉センターの指定管理者の指定について', '指定管理者の指定', NULL, '可決', '2026-03-09', 14, '{"points":["広川町保健・福祉センターの指定管理者の指定に関する議案であること以外、審議内容の詳細は本文に記載がない"],"conclusion":"広川町保健・福祉センターの指定管理者を指定する議案であるが、具体的な審議内容や指定管理者名、期間等の詳細は本文に記載がなく不明である。"}'::jsonb, 'draft', '2026-08-15T01:09:30.948+00:00', '3f4c000d5ffd618870ea455416e6be8a76fdc8f94dc02ae08010af09c841734b'),
    ('765bf68d-a89f-40f9-985b-ba3cae89206e', v_assembly_id, '議案第18号', '福岡県市町村職員退職手当組合を組織する地方公共団体の数の減少及び規約の変更について', '規約変更', '提案理由といたしましては、令和８年３月31日を限り、久留米市外三市町高等学校組合が解散されることに伴い、福岡県市町村職員退職手当組合を組織する地方公共団体の数を減少し、また、令和８年４月１日から久留米広域市町村圏事務組合が名称を変更することに伴い、福岡県市町村職員退職手当組合規約を変更するため、地方自治法第290条の規定により議会の議決を求めるものでございます。', '可決', '2026-03-09', 15, '{"points":["久留米市外三市町高等学校組合が令和8年3月31日限りで解散するため、福岡県市町村職員退職手当組合を組織する地方公共団体の数を減少させる必要がある","久留米広域市町村圏事務組合が令和8年4月1日から名称変更することに伴い、退職手当組合の規約変更が必要となる","地方自治法第290条の規定に基づき、組織団体数の減少及び規約変更について議会の議決を求めるもの"],"conclusion":"高等学校組合の解散に伴う組織団体数の減少と、久留米広域市町村圏事務組合の名称変更に伴う規約変更について、地方自治法第290条に基づき議会の議決を求める議案。"}'::jsonb, 'draft', '2026-08-15T01:09:52.107+00:00', 'a4a17520c1563d989d29d65129c135ee6b57fa077f7782424d00a07ca3e61f55'),
