    ('67135751-b8a9-4c97-8598-d1200bb69186', v_assembly_id, '発委第1号', '広川町議会委員会条例の一部改正について', '条例の改正', NULL, '可決', '2026-03-19', 27, NULL, 'none', NULL, NULL);

