  insert into public.question_topics
    (id, general_question_id, topic_title, raw_excerpt, department, display_order)
  values
    ('aa738a2c-8dbb-4302-8938-28826370cc33', '08028dad-af4c-420e-8cc3-ff4b08eb4041', '職員定数増と採用状況', '職員定数増後の中途採用状況や事業に対する適正な職員数確保について質問。答弁では、令和6年12月に定数増の条例改正を行い、令和7年度に計3回の採用試験を実施、社会人経験者向け試験を2回実施したと説明。令和7年4月時点の定数職員数は118.4人、年度途中に4人採用、さらに新規11人採用予定で、退職予定者10.8人を差し引くと令和8年度の定数は122.6人となる見込み。町長は採用活動を行っているが依然として職員数は足りていないとの認識を示した。', '総務課', 1),
    ('947d9c15-4951-4710-a7b6-69cc3b081d1d', '70806efe-5378-4555-b76a-099cc0e1f07f', '令和8年度予算編成の方針と財政指標', '町長は、現状維持は後退という危機感のもと、予算編成を2段階に分け新規・レベルアップ事業への財源確保、強靱な行政経営基盤・こどもまんなか社会・安全共生社会への重点配分、基金運用の国債等への切替などを説明した。竹下議員は経常収支比率や固定費を除いた予算額の見込みを質問したが、総務課長は決算前のため経常収支比率の見込みはなく、固定費の概念も集計していないと回答した。', '総務課', 1),
    ('356681a2-b685-44eb-9d30-478386c41e49', '02570c60-ee53-4c84-9738-70896f638b61', '建て替えの必要性と時期の認識', '広川消防署庁舎は昭和46年12月竣工から55年が経過し老朽化が進行、令和2年の消防署昇格による署員増加で手狭になり女性隊員用スペースも未確保という現状が示された。町長は建て替えの必要性は認識しているが、八女消防本部新庁舎建設を最優先とし、現時点では具体的な建設時期・場所・規模についての協議は行っていないと答弁した。', NULL, 1),
    ('549bb7d6-9f74-41cb-98e3-e44d272ffca1', '37b30949-b594-4a3d-9bf4-3e96dbaaf94b', '第5次総合計画の進捗状況と課題', '広川町第5次総合計画は令和6年度から13年度までの8年間の計画で、令和7年度は前期基本計画の2年目。施策評価は「順調」約4%、「おおむね順調」約74%、「あまり進んでいない」約22%。あまり進んでいない要因は空き家・空き地対策、移住定住施策、ふるさと納税、DX事業など相手方の意思や行動が成果に直結する事業と説明。令和8年度は移住定住事業との連携強化、空き家利活用相談会や専門アドバイザー活用、DX化交付金事業を活用した住民サービス向上や内部事務効率化を進める計画と答弁された。', '企画課', 1),
    ('c345e869-c2e9-4ff1-8341-8de568149e15', '070a9bc9-43d0-49c8-8fec-96d32edd899b', '町の財政状況と税制改正の影響', '議員は京都市の財政再建団体転落を例に広川町の財政状況と令和8年度税制改正の影響を質問。町長・総務課長は、実質公債費比率など財政指標は健全だが、長期的には人口減少や高齢化により歳入は伸び悩み、社会保障費は増加すると回答。令和8年度はガソリン税暫定税率廃止や1,030千円の壁改正により地方揮発油譲与税・環境性能割交付金・個人住民税の減収が見込まれるが、地方特例交付金で措置される部分もあり、住民税所得割は賃上げで前年度より増収見込みと説明した。', '総務課', 1),
    ('eb9cfb2a-3fbf-4369-a872-3b0eeed68963', '961e7081-fb9e-4dc7-ad9a-b8bf58e21e99', '国民健康保険の現状と子育て支援金', '江藤議員は国保の現状、子ども・子育て支援金導入、保険料統一、滞納状況、特別療養費について質問。町長・住民課長は、被保険者数が前年比95人減の3,779人、1人当たり医療費が410千円台であること、子ども・子育て支援金として所得割0.27%・均等割1,100円等を条例改正案で提案しており県の標準保険料率に基づく設定であること、令和15年度に県内保険料水準統一を目指すこと、収納率73.1%で前年比1.5%減、滞納世帯割合約13%で低所得・若年層に多い傾向、特別療養費は災害等特別事情がなく1年以上滞納した場合に適用されることを答弁した。', '住民課', 1),
    ('55bb33e0-6e33-40fb-9463-32fd18aa63cc', '070a9bc9-43d0-49c8-8fec-96d32edd899b', '長期的な歳出見通しと財政運営', '議員は社会保障費増加やインフラ老朽化(消防本部建替、斎場整備、公立病院、ごみ処理施設、上広川小学校移設、広川ダム改修等)を挙げ、長期的な歳出見通しを質問。総務課長は扶助費・繰出金・人件費など義務的経費が増加傾向にあり、今後数年から10年で多額の財政需要が集中すると回答。また国の補正予算縮小・当初予算重視や複数年度予算編成の動きについても、地方財政にとって好ましい変化であり調査研究していくと答弁した。副町長は日本版DOGEやゼロベース思考による予算編成、行財政改革の必要性について見解を述べた。', '総務課', 2),
    ('3ff63502-4848-4938-8de8-780913ce42da', '70806efe-5378-4555-b76a-099cc0e1f07f', '産業展示会館の直営化経緯', '竹下議員は、令和8年度から産業展示会館が町直営となった経緯を質問した。産業課長は、平成23年度から15年間指定管理を担ってきた広川町商工会が令和7年10月の総代会で指定管理から退くことを決定し、観光協会との協議も調わず、一般公募の期間確保や4月からの管理者不在の影響を考慮した結果、直営管理に至ったと説明した。', '産業課', 2),
    ('bdcbe121-218b-493b-b90c-cf8bbf567e82', '08028dad-af4c-420e-8cc3-ff4b08eb4041', '職員のスキルアップと給与比較', '職員育成の重点内容、退職者増加の要因、周辺市町との給与比較について質問。総務課長は、令和3年以降48人が退職し全職員の4割を占め、経験の浅い職員が多いことでノウハウ浸透や業務負担に課題があると回答。給与実態調査では本町一般行政職の平均給料月額は289,600円で県内60市町村中下から3番目。要因は39歳以下職員の割合が52%と高いことと、再任用職員が多く給与水準が低いことによると分析した。', '総務課', 2),
    ('363860a5-4194-4c0c-8277-205767a3394c', '961e7081-fb9e-4dc7-ad9a-b8bf58e21e99', '教育費の保護者負担軽減', '江藤議員は給食費以外の教育費負担について質問。教育長・子ども課長は、学校徴収金が小学校年額約18~41千円、中学校約27~48千円であること、入学時の制服代が小学校約33千円・中学校約100千円であること、就学援助認定率13.5%、入学支度金を小学校64,300円・中学校81千円に増額予定であること、副教材のICT化や精査による負担軽減、学校備品化については個人持ち教材と公費負担の区分を今後も精査していく方針を答弁した。', '教育委員会事務局子ども課', 2),
    ('69af4ead-27b1-4bf2-aa43-719b88978d61', '37b30949-b594-4a3d-9bf4-3e96dbaaf94b', '水害復旧・浸水対策事業の進捗', '令和5年7月豪雨で被災した町施設30か所のうち28か所の工事が完了し、残る松川原橋・高山橋橋梁は令和8年度出水期前の6月完成見込み。災害復旧は原形復旧が原則だが、橋梁は河川管理施設等構造令に基づき橋脚のない安全性の高い構造とした。県営の浸水対策重点地域緊急事業では6井堰撤去・2護岸工事に着手、地元説明会で維持管理費負担軽減や固定堰改修等の要望が出された。転倒堰の維持管理費は県から約15年分補償されるとの答弁があり、対象外井堰は今後の効果検証を踏まえ要望を行うとされた。', '建設課・都市計画課', 2),
    ('570a3871-8a7b-4e84-bbed-317cb7cac6fc', '02570c60-ee53-4c84-9738-70896f638b61', '内部協議・計画への位置づけ状況', '企画課長は、八女地区消防組合や幹事会での広川消防署の建築予定・時期・場所・敷地面積に関する公式な計画協議は行われておらず、役場内部での協議も行っていないと答弁した。また、建て替え計画は一部事務組合である八女消防組合が策定主体であり、関係市町間の合意形成が必要なため、町の各計画書内にも位置づけを行っていないと説明した。', '企画課', 2),
    ('600878f5-a6fb-4992-8912-a6a2486bcf9e', '08028dad-af4c-420e-8cc3-ff4b08eb4041', 'こどもまんなかと出生数・少子化対策', '出生数減少とこどもまんなかプロジェクトの関連、移住・定住や少子化対策としての位置づけについて質問。子ども課長は、同プロジェクトが地方創生総合戦略や人口ビジョンと連携しており、医療費無償化や出産・子育て応援給付金上乗せ、おむつ定期便など少子化対策的要素も含むと説明。主目的は未来の担い手を育成し広川サイクルを回すことであり、少子化対策そのものよりも人材育成強化の意味合いが強いが、発信を通じて定住・少子化対策にも寄与すると考えていると回答した。', '子ども課', 3),
    ('9f596249-8448-4966-8427-696a00be5d51', '37b30949-b594-4a3d-9bf4-3e96dbaaf94b', 'こどもまんなか政策の進捗', 'こどもまんなかアクションプランは令和6年度から8年間計画で、4つの柱に基づき子ども医療費無償化年齢引上げ、竜光寺公園リニューアル、おむつ定期便、「町長と話そう」「町長と給食を食べよう」等を実施。庁内連携は副町長をトップに子ども課・企画課のコアメンバー会議と各課プロジェクトチームで進捗確認と課題検討を行う体制。29事業中55%が順調に進み、全体評価は「おおむね良好」。アンケートでは「自分の行動で町を変えられる」との回答が41%から44%、「居場所がある」との回答が75%から88%に上昇した。', '子ども課', 3),
    ('11922983-a12b-4f8d-9d53-b833c465ccf0', '070a9bc9-43d0-49c8-8fec-96d32edd899b', '基金運用と株式保有の検討', '議員は他自治体のJR西日本株保有事例を挙げ、広川町でも基金の金融資産運用や公共交通企業株式取得を検討すべきと質問。総務課長は、地方自治法上株式運用は否定されていないが、公金は安全性・流動性・効率性の原則があり元本割れリスクに慎重であるべきとしつつ、インフレ対策として株式運用の可能性も含め先進事例の調査研究を進めると回答。町長は令和8年度予算編成方針として行財政基盤の確立や選択と集中、規律ある財政運営に努めると述べた。', '総務課', 3),
    ('3fe5a691-107c-4f44-9683-a8b66225fa92', '961e7081-fb9e-4dc7-ad9a-b8bf58e21e99', '各種基金の運用・活用方針', '江藤議員は基金の運用・活用計画について質問。町長・各課長は、基金総額約4,360,000千円のうち、ふるさと創生基金は竜光寺公園改修事業で全額活用予定、ふるさとづくり基金は令和8年度から目的別残高の3分の1を上限に経常経費へ充当する方針、学校建設基金・公共施設整備基金は今後の大規模改修費用に必要であること、財政調整基金約1,920,000千円・減債基金約356,000千円は財源不足対応に必要と説明した。また鶴寿奨学会基金・地域振興基金・最終処分場対策基金・中山間ふるさと基金など長期間残高が変わらない基金については、各担当課が今後の活用方法を検討する旨答弁した。', NULL, 3),
    ('fb1f71e9-7d73-4965-9ad9-f8b4c8450159', '02570c60-ee53-4c84-9738-70896f638b61', '必要な建築面積の考え方', '企画課長は、建築面積について公式協議には至っていないとしつつ、女性消防職員の配置(令和10年度までに5名の方針)や車両数・隊員数の増加を考慮すると、現在の延べ床面積約400平方メートルでは狭いとの認識を示し、現在の床面積以上が必要ではないかと答弁した。', '企画課', 3),
    ('0881f8c2-0c02-4bd0-b2d7-27346af851d0', '70806efe-5378-4555-b76a-099cc0e1f07f', 'ネイティブテキスタイル事業の状況', '竹下議員はネイティブテキスタイル産地プロジェクト推進協議会の構成、令和7年度予算35,600千円の執行状況、指定管理施設Hodokuの活用、ラボラトリー構築やウェブサイト整備、ワークショップ実施状況、Origeの移住・定住促進機能の継続について質問した。産業課長は、協議会は正会員10社・賛助会員5社で構成され会長は坂田織物、予算はおおむね全額執行、OrigeとHodokuを活動拠点として活用し、ワークショップやクリスマス点灯式を実施、移住・定住促進業務も指定管理業務に含まれると回答した。', '産業課', 3),
    ('2b2db771-5252-4c04-b927-1b81fdb04605', '08028dad-af4c-420e-8cc3-ff4b08eb4041', '高齢者施策との関係と職員連携', '高齢者への説明や意識共有、育成に携わる職員のスキルアップについて質問。子ども課長は、こどもまんなかプロジェクトは複数課の職員が連携して事業を進めており、その過程で職員のスキルアップにもつながっていると説明。町長は、高齢者施策をおろそかにしていないことを強調し、こどもまんなかは子供世帯だけでなく全住民に影響する施策であり、将来の医療・介護の担い手となる子供たちを育成することが高齢者を含む地域社会全体を支えることにつながると説明した。', NULL, 4),
    ('a17adc38-d4bf-4c01-b308-21817950991d', '02570c60-ee53-4c84-9738-70896f638b61', '建築場所と浸水想定区域の課題', '企画課長は、現在の敷地面積527平方メートルでは訓練スペース等を含め不足するとの考えを示した。また現在の消防署は役場のすぐ東側にあり行政と消防の連携に優れた立地だが、浸水想定区域に含まれているため、安全性の確保と機能的連携の両立を図る方針で場所選定を行うと答弁した。', '企画課', 4),
    ('37e6d4d3-a380-4772-8f86-279b0b67e01e', '37b30949-b594-4a3d-9bf4-3e96dbaaf94b', '学校教育における平和教育', '広川町は昭和59年に「非核・恒久平和の町」を宣言し、学習指導要領に基づき全教科・全領域で平和教育を実施。8月6日前後の出校日に平和学習を行い、小学校修学旅行では長崎で被爆体験の語り部から話を聞く機会を設けている。中学校でも令和6年度に長崎の平和祈念館から語り部を招き被爆体験講話を実施し、戦争や平和についての議論を通じて考える力を養う教育を行っている。今後は子供たちが自ら平和について発表する機会や宣言文作成などの取組を充実させる方針が示された。', '子ども課', 4),
    ('2fa32543-4c0b-4cf5-a4e5-d2b5abd81371', '70806efe-5378-4555-b76a-099cc0e1f07f', '学校給食無償化の予算編成', '竹下議員は小学校給食無償化の予算への影響と、中学校給食無償化を令和8年度から実施する検討をしなかったか質問した。子ども課長は、国基準額と実費との乖離分を町単独で補填し小学校給食を完全無償化する予算を計上したこと、中学校無償化には食材費だけで約36,000千円必要であり、まずは体育館等の空調整備を優先する方針で検討していると説明した。', '子ども課', 4),
    ('a7941ddb-34b7-4089-9c78-0984cbc64e6e', '070a9bc9-43d0-49c8-8fec-96d32edd899b', '地域コミュニティ推進事業の評価と延長', '議員は15年間続く地域コミュニティ推進事業の成果や2年延長の理由を質問。企画課長は、事業により協働のまちづくりが定着し地域課題解決が継続している一方、担い手不足や事務負担軽減を求める意見があると回答。2年延長は第3期への移行を保留し、令和10年度の制度刷新に向けた検証準備期間として設定したものであり、単なる延長ではないと説明した。来年度の委員長への説明は1月末に実施済みで、要望があれば追加説明会を開くとした。', '企画課', 4),
    ('300faed3-71b7-49b1-80e7-469bbb5972b0', '02570c60-ee53-4c84-9738-70896f638b61', '用地確保の先行実施について', '企画課長は、消防庁舎の用地確保は各自治体が行うものであり、八女消防本部庁舎の完成を待たずに広川町として用地選定の準備を先行して進めることが可能であるとし、適地のリストアップや交渉のめどをつける対応を行っていく考えを示した。', '企画課', 5),
    ('239e658c-8958-4118-ac2e-d27f0d289fdf', '37b30949-b594-4a3d-9bf4-3e96dbaaf94b', '主権者教育の取組', '広川町明るい選挙推進協議会が中心となり啓発活動を実施し、ぎんなん学級でも身近な暮らしと政治について学ぶ場を提供。福島高校では福岡財務支局と合同で財政教育プログラムの出前講座を令和6年度から実施し、国家予算のグループワークと投票を行っている。上広川・下広川小学校では給食大臣を選ぶ模擬選挙を実施し、実際の投票用紙・投票箱を使用。中広川小学校でも令和8年度から同様の出前講座を実施する計画であると答弁された。', '選挙管理委員会', 5),
    ('06d10cc8-fe2f-4389-bd2e-75f0afa717c4', '070a9bc9-43d0-49c8-8fec-96d32edd899b', '行政区・自治会の担い手不足と今後の在り方', '議員は行政区の担い手不足、区長後継者難、公民館等維持管理費、未加入世帯増加などの課題を挙げ、今後の行政区の方針を質問。企画課長は、近隣区との連携による事務の共通化や行事の合同開催など柔軟な手法を検討するとし、コミュニティセンター構想については既存の地区公民館・自治会体制を活かす方針を示した。町長は自治会が地域づくりの基盤であるとし、デジタルインフラ活用による役員負担軽減など支援策を検討し、住民と議論しながら自治会運営支援の在り方を検討すると答弁した。', '企画課', 5),
    ('74dd70d8-eb61-430b-b2ca-86a8fbf74683', '70806efe-5378-4555-b76a-099cc0e1f07f', '人材育成基本方針の進捗状況', '竹下議員は令和7年3月改定の広川町人材育成基本方針の進捗と、定年延長・再任用・新規採用・会計年度任用職員の育成方針を質問した。町長は、マンスリーレポートによる情報共有、経営チーム会議やマネジメント研修、人事評価制度の見直し、人物重視の採用試験、令和8年度に全正規職員対象の強み診断実施などを説明し、退職者の多さやOJTの質向上、有給休暇取得率の数値目標設定が今後の課題であると述べた。', '総務課', 5),
    ('e96df523-6599-487b-9813-49f46f40fab2', '70806efe-5378-4555-b76a-099cc0e1f07f', '温暖化対策計画と下水道事業', '環境課長は、地球温暖化対策実行計画の策定背景として、これまでの世界各国の取組みが影響しており、町民・事業者・農業関係者など様々な立場での検討が必要だとして計画を作成したと説明。竹下議員はSDGsワークショップでの太陽光パネル評価について、製造から廃棄までを踏まえた情報共有の必要性を指摘した。また下水道事業計画区域について、令和3年頃に550から440ヘクタールへ20％削減した経緯があり、今後さらなる面積削減の検討予定はないと環境課長が答弁した。', '環境課', 6),
    ('f45e7ed1-97fa-4b20-bfd5-ef160dd449e0', '70806efe-5378-4555-b76a-099cc0e1f07f', 'パンデミック計画・国保・教育支援・LGBT', '竹下議員は新型インフルエンザ等対策行動計画の特定接種・住民接種の検証状況を質問し、住民課長は特段の検証は行っていないと回答。国民健康保険の18歳以下均等割減免について、町独自の検討はしていないが国の動向は認識していると住民課長が答弁。教育支援センターは令和8年4月にはなやぎの里2階で開設予定で、八女市「あしたば」利用者や相談中の児童・生徒がいると子ども課長が説明。LGBTに関する地域特性は学校教育を通じた生徒の状況以外は把握していないと生涯学習課長が答弁した。', NULL, 7),
    ('0dbad34d-f6f3-4926-9717-51a066ad3698', '70806efe-5378-4555-b76a-099cc0e1f07f', '基金運用方針の見直し', '竹下議員が広川町資金管理運用方針・債券運用方針に基づく基金運用の拡大について質問。総務課長は、これまで定期預金中心だった運用を政府関係機関の財投債等の活用へ転換しており、現在9億円を運用しているとし、今後さらに運用額を増やしていく方針であると答弁した。', '総務課', 8),
    ('575c0550-5d72-4237-bc6a-a0cae668fc3d', '70806efe-5378-4555-b76a-099cc0e1f07f', '職員の非違事例と中国交流', '竹下議員は役場の非違事例（ごみ購入の議決漏れ、消費税納付遅滞、課税資料送付漏れ、竜光寺公園での交通事故等）について質問。企画課長は交通事故について本人への聞き取りで前方不注意と確認したが、当時公共交通に関する業務課題を抱えていた状況もあったと説明した。また中国蘇州市との友好関係については、廃止に向けた詳細な事務手続きはまだ行っていないと企画課長が答弁した。', '企画課', 9),
    ('e3b6a4ce-c584-4f06-80e9-d46466369dcf', '70806efe-5378-4555-b76a-099cc0e1f07f', '職員採用基準とキャリアパス・人材育成', '竹下議員は職員採用基準、町内在住者の採用割合、人材育成基本方針の毎年検証方法について質問。総務課長は、目指すべき職員像や5つの行動姿勢を採用試験で公表し、居住地は合否基準にしていないと説明。副町長は自身の厚労省でのキャリアパス経験（初任者研修、自治体研修、現場視察等）を紹介し、広川町職員にも地域との触れ合いを通じた愛着醸成を期待すると述べた。窓口対応や挨拶など公僕意識の向上についても、人材育成基本方針に基づき職員の意識徹底とDX化による住民サービス向上を図ると答弁した。', '総務課', 10);

end $$;
